const resolveChannelKey = (platform, channel) => {
  const p = platform ? String(platform).trim() : "";
  const c = channel ? String(channel).trim() : "";
  return (
    CHANNEL_KEY_MAP[p] ||
    CHANNEL_KEY_MAP[p.toLowerCase()] ||
    CHANNEL_KEY_MAP[c] ||
    CHANNEL_KEY_MAP[c.toLowerCase()] ||
    "channelbot"
  );
};

