/* provider statuses exactly as MrAssistant returns them */
const MRA_STATUS = ["initiated", "ringing", "answered", "ended", "failed"];
const STATUS_LABEL = { initiated: "Connecting", ringing: "Ringing", answered: "In progress", ended: "Completed", failed: "Failed", missed: "Missed", busy: "Busy", cancelled: "Cancelled", transferred: "Transferred" };
/* capabilities the provider genuinely exposes; the UI hides anything false */
const VOICE_CAPS = { outbound: true, inbound: true, mute: true, transfer: true, endCall: true, recording: true, transcript: true, summary: true, liveEvents: true, diagnostics: true, campaigns: true, hold: false, whisper: false, barge: false };

function makeVoiceProvider(cfg) {
  const url = (key, params, query) => {
    const e = MRA_ENDPOINTS[key];
    let p = e.p.replace(/\{(\w+)\}/g, (m2, k) => encodeURIComponent((params || {})[k] || ""));
    const qs = query ? Object.entries(query).filter(([, v]) => v !== undefined && v !== "").map(([k, v]) => k + "=" + encodeURIComponent(v)).join("&") : "";
    return VOICE_PROXY + p + (qs ? "?" + qs : "");
  };
  const call = async (key, { params, query, body } = {}) => {
    if (!cfg.connected) {
      const err = new Error("VOICE_NOT_CONNECTED");
      err.friendly = "Voice is not connected yet. Add your MrAssistant workspace in Settings to place and receive real calls.";
      throw err;
    }
    const e = MRA_ENDPOINTS[key];
    const res = await fetch(url(key, params, query), {
      method: e.m === "SSE" ? "GET" : e.m,
      headers: { "Content-Type": "application/json" },     // auth is attached by our backend, never here
      body: body ? JSON.stringify(body) : undefined,
    });
    if (!res.ok) {
      const err = new Error("VOICE_" + res.status);
      err.friendly = res.status === 401 ? "Your voice workspace needs to be reconnected."
        : res.status === 404 ? "That call is no longer available from the provider."
        : res.status === 422 ? "That phone number was rejected. Check it is in full international format."
        : res.status >= 500 ? "The voice provider is unavailable right now. Nothing was charged and no call was placed."
        : "Unable to complete that voice action.";
      throw err;
    }
    return res.json();
  };
  return {
    name: "MrAssistant.ai", caps: VOICE_CAPS, connected: cfg.connected, endpointFor: url,
    listCalls: (agentId, q) => call("listCalls", { params: { agent_id: agentId }, query: q }),
    activeCalls: (agentId) => call("activeCalls", { params: { agent_id: agentId } }),
    outbound: (b) => call("outboundCall", { body: b }),
    endCall: (id) => call("endCall", { params: { call_id: id } }),
    mute: (id, on) => call("muteCall", { params: { call_id: id }, body: { muted: on } }),
    transfer: (id, to) => call("transferCall", { params: { call_id: id }, body: { transfer_to: to } }),
    control: (id, action) => call("controlCall", { params: { call_id: id }, body: action }),
    recording: (id) => call("callRecording", { params: { call_id: id } }),
    transcript: (agentId, sessionId) => call("getTranscript", { params: { agent_id: agentId, session_id: sessionId } }),
    summarize: (agentId, sessionId) => call("summarize", { params: { agent_id: agentId, session_id: sessionId } }),
    trace: (sessionId) => call("sessionTrace", { params: { session_id: sessionId } }),
    stats: (q) => call("callStats", { query: q }),
  };
}

/* phone normalization so a call always resolves to one CRM contact */
const normPhone = (p) => (p || "").replace(/[^\d]/g, "").slice(-10);
const matchContact = (number) => {
  const n = normPhone(number);
  if (!n) return null;
  return CONTACTS.find((c) => normPhone(c.phone) === n) || null;
};

