const bestTimes = { instagram: "18:00 to 20:00", linkedin: "08:00 to 10:00", facebook: "12:00 to 14:00", x: "09:00 and 21:00", youtube: "17:00", google: "10:00", tiktok: "19:00" };

const POSTS_INIT = []; // TODO_BACKEND
const SOCIAL_CAMPAIGNS_INIT = []; // TODO_BACKEND
const ASSETS_INIT = []; // TODO_BACKEND
const SOCIAL_COMMENTS_INIT = []; // TODO_BACKEND

/* content generation from brand + pillar + platform */
const HOOKS = ["The one thing nobody tells you about", "We tested this for 30 days:", "Most businesses get this wrong:", "Here is what changed everything:", "Three questions we hear daily:"];
function genPost({ pillar, platform, brand, ind, kind }) {
  const spec = PLATFORMS[platform];
  const who = ind ? ind.people.toLowerCase() : "customers";
  const base = {
    Education: `${HOOKS[Math.floor(Math.random() * HOOKS.length)]} response time decides who wins the ${who}. Here is the 3 step system we use, and you can copy it today.`,
    Product: `Every message, call and DM lands in one inbox, and the AI answers in seconds. That is the whole product. ${brand.cta}.`,
    "Customer stories": `A ${who.slice(0, -1)} came to us missing a third of their inquiries. Six weeks later: zero missed, 40 second replies, same team size.`,
    "Behind the scenes": `A quiet look at how we build: one whiteboard, a lot of customer calls, and a rule that nothing ships until it saves someone an hour.`,
    Promotional: `This week only: ${brand.cta.toLowerCase()} and get your setup done with you, not by a help article.`,
  }[pillar] || `${brand.desc} ${brand.cta}.`;
  let text = base;
  if (platform === "linkedin") text = base + "\n\nWhat is your current first response time? Curious how others handle it.";
  if (platform === "x") text = base.split(".")[0] + ". " + brand.cta + ".";
  if (platform === "instagram") text = base + " " + (kind === "Reel" ? "Full breakdown in the reel." : "Save this for later.");
  if (platform === "youtube") text = base + "\n\nChapters in the description. Subscribe for the weekly teardown.";
  if (text.length > spec.limit) text = text.slice(0, spec.limit - 1) + "…";
  const tagPool = ["#automation", "#customerexperience", "#smallbusiness", "#ai", "#growth", "#customerservice"];
  return { text, tags: spec.tags ? tagPool.slice(0, Math.min(3, spec.tags)) : [] };
}
/* repurpose one piece into platform-native variants */
function repurpose(text, brand) {
  return [
    { platform: "linkedin", kind: "Text", text: text + "\n\nThe short version: speed beats polish. What would change if you replied in under a minute?" },
    { platform: "instagram", kind: "Carousel", text: text.split(".")[0] + ". Swipe for the 3 step version. " + brand.cta + "." },
    { platform: "x", kind: "Thread", text: "1/ " + text.split(".")[0] + ".\n2/ Here is what actually moved the number.\n3/ " + brand.cta + "." },
    { platform: "facebook", kind: "Image", text: text + " " + brand.cta + " → link in the first comment." },
    { platform: "youtube", kind: "Short", text: "HOOK: " + text.split(".")[0] + "?\nBODY: the 3 step system.\nCTA: " + brand.cta + "." },
  ];
}
/* pre publish quality check */
function qualityCheck(post, brand) {
  const issues = [];
  post.channels.forEach((ch) => {
    const spec = PLATFORMS[ch];
    if (!spec) return;
    if (post.text.length > spec.limit) issues.push({ lvl: "error", t: `${spec.label}: ${post.text.length} characters exceeds the ${spec.limit} limit.` });
    if ((post.tags || []).length > spec.tags) issues.push({ lvl: "warn", t: `${spec.label} allows ${spec.tags} hashtags; you have ${(post.tags || []).length}.` });
    if (!spec.kinds.includes(post.kind)) issues.push({ lvl: "warn", t: `${spec.label} does not support ${post.kind}; it will publish as ${spec.kinds[0]}.` });
    if (!spec.caps.publish) issues.push({ lvl: "warn", t: `${spec.label} cannot be auto published through its API. ${spec.note}` });
  });
  const bad = (brand.forbidden || "").split(",").map((x) => x.trim().toLowerCase()).filter(Boolean).filter((w) => post.text.toLowerCase().includes(w));
  if (bad.length) issues.push({ lvl: "warn", t: `Off brand wording found: ${bad.join(", ")}.` });
  if (!/https?:\/\/|link in bio|book|call|dm|comment/i.test(post.text)) issues.push({ lvl: "warn", t: "No clear call to action. Your brand CTA is “" + brand.cta + "”." });
  if (!post.channels.length) issues.push({ lvl: "error", t: "No platform selected." });
  return issues;
}

/* ==================================================================== */
/* APPROVAL / GOVERNANCE CONTROL PLANE                                   */
/* One policy engine decides whether an action may run, who may sign it  */
/* off, how risky it is and how long it stays valid. Every approval      */
/* carries the payload so approving executes the exact proposed action.  */
/* ==================================================================== */

const ROLES = ["Owner", "Admin", "Manager", "Finance Manager", "Marketing Manager", "Sales Manager", "Support Lead", "Agent"];
/* who can sign off what. Owner and Admin can sign anything. */
const ROLE_POWER = {
  Owner: ["*"], Admin: ["*"],
  Manager: ["Manager", "Sales Manager", "Support Lead", "Marketing Manager", "Agent"],
  "Finance Manager": ["Finance Manager", "Manager", "Agent"],
  "Marketing Manager": ["Marketing Manager", "Agent"],
  "Sales Manager": ["Sales Manager", "Agent"],
  "Support Lead": ["Support Lead", "Agent"],
  Agent: ["Agent"],
};
const RISK = ["Low", "Medium", "High", "Critical"];
const RISK_TINT2 = { Low: "bg-zinc-100 text-zinc-600 border-zinc-200", Medium: "bg-sky-50 text-sky-700 border-sky-200",
  High: "bg-amber-50 text-amber-700 border-amber-200", Critical: "bg-red-50 text-red-700 border-red-200" };
const APPROVAL_STATES = ["Pending", "In review", "Approved", "Rejected", "Expired", "Cancelled", "Executing", "Executed", "Failed"];
const AP_TINT = { Pending: "bg-amber-50 text-amber-700 border-amber-200", "In review": "bg-sky-50 text-sky-700 border-sky-200",
  Approved: "bg-emerald-50 text-emerald-700 border-emerald-200", Executed: "bg-emerald-50 text-emerald-700 border-emerald-200",
  Rejected: "bg-zinc-100 text-zinc-500 border-zinc-200", Expired: "bg-zinc-100 text-zinc-500 border-zinc-200",
  Cancelled: "bg-zinc-100 text-zinc-400 border-zinc-200", Executing: "bg-sky-50 text-sky-700 border-sky-200", Failed: "bg-red-50 text-red-700 border-red-200" };
const REJECT_REASONS = ["Incorrect information", "Wrong customer", "Too risky", "Needs clarification", "Policy violation", "Wrong tone", "Duplicate", "Not appropriate"];

const POLICIES_INIT = []; // TODO_BACKEND

/* map a platform action to a policy category */
const policyCategory = (actionKey) => {
  if (!actionKey) return "*";
  if (/REFUND|PAYMENT_LINK/.test(actionKey)) return "refund";
  if (/CAMPAIGN/.test(actionKey)) return "campaign";
  if (/SOCIAL/.test(actionKey)) return "social";
  if (/CALL/.test(actionKey)) return "call";
  if (/DELETE/.test(actionKey)) return "delete";
  if (/CANCEL_APPOINTMENT/.test(actionKey)) return "cancel_appt";
  return "*";
};
const opTest = { gt: (a, b) => a > b, gte: (a, b) => a >= b, lt: (a, b) => a < b, eq: (a, b) => a === b };

/* the policy engine: which rule applies, what role signs it, how risky, how long it lives */
function evaluatePolicy({ actionKey, meta = {}, policies = POLICIES_INIT }) {
  const cat = policyCategory(actionKey);
  const match = policies.find((p) => {
    if (p.action !== cat) return false;
    if (!p.field) return true;
    const v = Number(meta[p.field] || 0);
    return opTest[p.op] ? opTest[p.op](v, p.value) : false;
  }) || policies.find((p) => p.action === "*") || { role: "Manager", risk: "Low", slaMin: 240, expiryMin: 1440, bulk: true, label: "Default" };
  /* financial value escalates risk regardless of category */
  let risk = match.risk;
  const amt = Number(meta.amount || 0);
  if (amt >= 1000) risk = "Critical";
  else if (amt >= 100 && RISK.indexOf(risk) < RISK.indexOf("High")) risk = "High";
  const recips = Number(meta.recipients || 0);
  if (recips >= 1000) risk = "Critical";
  else if (recips >= 100 && RISK.indexOf(risk) < RISK.indexOf("High")) risk = "High";
  return { policy: match, role: match.role, risk, slaMin: match.slaMin, expiryMin: match.expiryMin, bulkAllowed: !!match.bulk && risk !== "Critical" && risk !== "High" };
}

/* can this user sign this approval, directly or by delegation? */
function canDecide(userRole, requiredRole, { delegations = [], userName = "" } = {}) {
  const powers = ROLE_POWER[userRole] || [];
  if (powers.includes("*") || powers.includes(requiredRole)) return { ok: true, why: `${userRole} can sign off ${requiredRole} approvals.` };
  const d = delegations.find((x) => x.to === userName && x.role === requiredRole && new Date(x.until) > new Date());
  if (d) return { ok: true, why: `Delegated from ${d.from} until ${new Date(d.until).toLocaleDateString()}.`, delegated: true };
  return { ok: false, why: `This needs ${requiredRole} authority. You are signed in as ${userRole}.` };
}

const apAge = (a) => Math.round((Date.now() - new Date(a.createdAt).getTime()) / 60000);
const apDue = (a) => a.slaMin - apAge(a);
const apState = (a) => {
  if (["Approved", "Rejected", "Executed", "Failed", "Cancelled", "Executing"].includes(a.status)) return a.status;
  if (a.expiryMin && apAge(a) > a.expiryMin) return "Expired";
  return a.status;
};
const fmtMins = (m) => m < 0 ? Math.abs(m) + "m overdue" : m < 60 ? "due in " + m + "m" : "due in " + Math.round(m / 60) + "h";

const APPROVALS_INIT = []; // TODO_BACKEND

const REACHED = ["Sent", "Delivered", "Opened", "Clicked", "Replied", "Converted"];
const campMetrics = (c) => {
  const r = (c && c.recipients) || [];
  if (r.length > 0) {
    const has = (list) => r.filter((x) => list.includes(x.status)).length;
    return {
      audience: r.length, eligible: r.filter((x) => x.status !== "Suppressed").length, suppressed: has(["Suppressed"]),
      queued: has(["Queued"]), sent: has(REACHED), delivered: has(["Delivered", "Opened", "Clicked", "Replied", "Converted"]),
      opened: has(["Opened", "Clicked", "Replied", "Converted"]), clicked: has(["Clicked", "Replied", "Converted"]),
      replied: has(["Replied", "Converted"]), converted: has(["Converted"]), failed: has(["Failed"]),
    };
  }
  const sent = c?.sent || 0;
  const replied = c?.replied || 0;
  const converted = c?.converted || 0;
  const failed = c?.failed || 0;
  const eligible = c?.eligible || (sent + replied + converted) || 1;
  return {
    audience: eligible, eligible, suppressed: c?.suppressed || 0,
    queued: c?.queued || 0, sent, delivered: c?.delivered || sent,
    opened: c?.opened || Math.floor(sent * 0.8), clicked: c?.clicked || Math.floor(sent * 0.5),
    replied, converted, failed,
  };
};
const pctOf = (n, d) => d ? Math.round((n / d) * 100) + "%" : "—";

/* ==================================================================== */
/* HOME BRIEFING ENGINE                                                  */
/* The narrative, the priorities and the opportunities are all derived   */
/* from live records, so an empty workspace says so rather than showing  */
/* a plausible number.                                                   */
/* ==================================================================== */

/* what needs a human today, ranked by consequence */
function buildPriorities(d) {
  const { approvals, appts, wfRuns, calls, convs, contacts, kb, conns, agents, usage, ent, billing } = d;
  const out = [];
  const add = (level, title, why, go, count) => out.push({ level, title, why, go, count });

  const overdueAp = (approvals || []).filter((a) => apState(a) === "Pending" && apDue(a) < 0);
  if (overdueAp.length) add("high", `${overdueAp.length} approval${overdueAp.length > 1 ? "s are" : " is"} past its deadline`, "Agent work is blocked while these wait.", "approvals", overdueAp.length);
  const pendAp = (approvals || []).filter((a) => apState(a) === "Pending" && apDue(a) >= 0);
  if (pendAp.length) add("medium", `${pendAp.length} action${pendAp.length > 1 ? "s need" : " needs"} your approval`, pendAp.map((a) => a.title).slice(0, 2).join(", ") + ".", "approvals", pendAp.length);

  const unconfirmed = (appts || []).filter((a) => a.status === "Pending" && new Date(a.start) > Date.now());
  if (unconfirmed.length) add("high", `${unconfirmed.length} appointment${unconfirmed.length > 1 ? "s are" : " is"} unconfirmed`, "Unconfirmed slots are where no shows come from.", "appointments", unconfirmed.length);

  const waiting = (convs || []).filter((v) => v.state === "Escalated" || (!v.ai && v.state !== "Resolved"));
  if (waiting.length) add("high", `${waiting.length} conversation${waiting.length > 1 ? "s are" : " is"} waiting on a person`, "The AI has handed these over and nobody has replied yet.", "inbox", waiting.length);

  const missed = (calls || []).filter((k) => k.status === "missed");
  if (missed.length) add("medium", `${missed.length} missed call${missed.length > 1 ? "s" : ""}`, "Nobody has called these people back.", "calls", missed.length);

  const failed = (wfRuns || []).filter((r) => r.status === "Failed");
  if (failed.length) add("medium", `${failed.length} workflow run${failed.length > 1 ? "s" : ""} failed`, "Failed automation stops follow up silently.", "automations", failed.length);

  const cold = (contacts || []).filter((c) => !c.archived && c.status === "New" && (c.lastContact || 0) >= 2);
  if (cold.length) add("high", `${cold.length} new lead${cold.length > 1 ? "s have" : " has"} not been contacted`, "Speed to first reply is the strongest predictor of conversion.", "crm", cold.length);

  Object.entries(conns || {}).forEach(([id, c]) => {
    if (c && c.on && ["Error", "Token expired"].includes(connHealth(c).state)) {
      const p = PROVIDERS.find((x) => x.id === id);
      add("high", `${p ? p.name : id} needs reconnecting`, "Anything depending on it will fail until it is fixed.", "integrations", 1);
    }
  });
  if (ent && ent.aiActions !== Infinity && usage && usagePct(usage.aiActions, ent.aiActions) >= 90)
    add("medium", `AI usage at ${usagePct(usage.aiActions, ent.aiActions)}%`, "You are close to the monthly allowance on this plan.", "settings", 1);
  if (billing && ["past_due", "unpaid"].includes(billing.sub))
    add("high", billing.sub === "unpaid" ? "Subscription unpaid" : "Payment failed", "Billing needs attention before access is restricted.", "settings", 1);

  const brokenAgents = (agents || []).filter((a) => a.status === "Active" && agentHealth(a, 4).level === "Action required");
  if (brokenAgents.length) add("low", `${brokenAgents.length} agent${brokenAgents.length > 1 ? "s are" : " is"} misconfigured`, brokenAgents[0].name + ": " + agentHealth(brokenAgents[0], 4).issues[0].t, "agents", brokenAgents.length);

  const stale = (kb || []).filter((x) => !x.archived && kbFreshness(x) === "Stale");
  if (stale.length) add("low", `${stale.length} knowledge source${stale.length > 1 ? "s are" : " is"} stale`, "Agents may be quoting information that has changed.", "knowledge", stale.length);

  const rank = { high: 0, medium: 1, low: 2 };
  return out.sort((a, b) => rank[a.level] - rank[b.level]);
}

/* what the AI got done without being asked */
function workDone(activity, days = 1) {
  const recent = (activity || []).filter((e) => inRange(e.at, days) && e.actorType !== "human");
  const by = {};
  recent.forEach((e) => {
    const k = e.action;
    by[k] = by[k] || { action: k, n: 0, ok: 0, category: e.category };
    by[k].n++; if (e.outcome === "success") by[k].ok++;
  });
  return { total: recent.length, blocked: recent.filter((e) => e.outcome === "blocked").length,
    failed: recent.filter((e) => e.outcome === "failed").length,
    items: Object.values(by).sort((a, b) => b.n - a.n).slice(0, 6) };
}

/* growth openings worth acting on, each with the records behind it */
function findOpportunities(d) {
  const { contacts, deals, appts, camps, convs } = d;
  const out = [];
  const live = (contacts || []).filter((c) => !c.archived);

  const quiet = live.filter((c) => ["Working", "Qualified"].includes(c.status) && (c.lastContact || 0) >= 7);
  if (quiet.length) out.push({ title: `${quiet.length} qualified leads have gone quiet`, why: `No contact in a week or more. They were interested enough to qualify.`, go: "crm", ask: `Follow up with the ${quiet.length} qualified leads who have gone quiet` });

  const stuck = (deals || []).filter((x) => ["Negotiation", "Proposal Sent"].includes(x.stage));
  if (stuck.length) { const val = stuck.reduce((a, x) => a + x.value, 0);
    out.push({ title: `${stuck.length} deals worth ${money(val)} are mid negotiation`, why: "These are the closest thing you have to booked revenue.", go: "crm", ask: `What should I do about the ${stuck.length} deals in negotiation?` }); }

  const lapsed = live.filter((c) => c.status === "Converted" && (c.lastContact || 0) >= 60);
  if (lapsed.length) out.push({ title: `${lapsed.length} customers have not heard from you in two months`, why: "Existing customers convert far more cheaply than new ones.", go: "crm", ask: `Create a win back campaign for the ${lapsed.length} lapsed customers` });

  const noAppt = live.filter((c) => c.status === "Qualified" && !(appts || []).some((a) => a.contactId === c.id));
  if (noAppt.length) out.push({ title: `${noAppt.length} qualified leads have no appointment booked`, why: "Qualified without a meeting is where most pipelines leak.", go: "crm", ask: `Book appointments for the ${noAppt.length} qualified leads without one` });

  const best = (camps || []).map((c) => ({ c, m: campMetrics(c) })).filter((x) => x.m.sent > 0)
    .sort((a, b) => (b.m.converted / b.m.sent) - (a.m.converted / a.m.sent))[0];
  if (best && best.m.converted) out.push({ title: `"${best.c.name}" is converting at ${Math.round((best.m.converted / best.m.sent) * 100)}%`, why: "Your best performing campaign; worth sending to a wider segment.", go: "campaigns", ask: `Why is the ${best.c.name} campaign working so well?` });

  return out.slice(0, 4);
}

/* the morning narrative, assembled from the same numbers shown below it */
function buildBriefing(d) {
  const { contacts, convs, deals, appts, activity, calls } = d;
  const live = (contacts || []).filter((c) => !c.archived);
  const newNow = live.filter((c) => inRange(c.created, 7)).length;
  const newPrev = live.filter((c) => inRange(c.created, 7, 1)).length;
  const delta = pctChange(newNow, newPrev);
  const aiWork = workDone(activity, 1);
  const uncontacted = live.filter((c) => c.status === "New" && (c.lastContact || 0) >= 2).length;
  const unconfirmed = (appts || []).filter((a) => a.status === "Pending" && new Date(a.start) > Date.now()).length;
  const won = (deals || []).filter((x) => x.stage === "Won");

  if (!live.length && !(convs || []).length) return { empty: true, text: "Your workspace is ready but there is nothing in it yet. Tell me about your business and I will set up your agents, workflows and knowledge so this screen starts filling with real activity." };

  const parts = [];
  parts.push(`${live.length} contacts on file` + (newNow ? `, ${newNow} added this week${delta !== null && newPrev ? ` (${delta >= 0 ? "up" : "down"} ${Math.abs(delta)}% on the week before)` : ""}` : ""));
  if (aiWork.total) parts.push(`your agents took ${aiWork.total} actions in the last day${aiWork.failed ? `, ${aiWork.failed} of which failed` : ""}`);
  if (won.length) parts.push(`${won.length} deals closed for ${money(won.reduce((a, x) => a + x.value, 0))}`);
  const needs = [];
  if (uncontacted) needs.push(`${uncontacted} lead${uncontacted > 1 ? "s" : ""} nobody has replied to`);
  if (unconfirmed) needs.push(`${unconfirmed} unconfirmed appointment${unconfirmed > 1 ? "s" : ""}`);
  const tail = needs.length ? ` The first thing worth doing is ${needs[0]}${needs[1] ? `, then ${needs[1]}` : ""}.` : " Nothing is waiting on you right now.";
  return { empty: false, text: parts.join(", ") + "." + tail };
}
const greeting = () => { const h = new Date().getHours(); return h < 12 ? "Good morning" : h < 18 ? "Good afternoon" : "Good evening"; };

/* ==================================================================== */
/* ASSISTANT: risk, context and voice                                    */
/* ==================================================================== */

/* what a command would do, so consequential work is previewed not assumed */
const CMD_RISK = [
  { re: /\b(delete|remove|wipe|purge)\b/i, risk: "destructive" },
  { re: /\b(call|dial)\s+(everyone|all|\d{2,})/i, risk: "high" },
  { re: /\b(launch|send|blast)\b.*\b(campaign|everyone|all)\b/i, risk: "high" },
  { re: /\b(refund|credit|payment)\b/i, risk: "high" },
  { re: /\b(upgrade|downgrade|cancel)\b.*\b(plan|subscription)\b/i, risk: "high" },
  { re: /\b(pause all|stop all)\b/i, risk: "high" },
  { re: /\b(send|message|whatsapp|email|follow up|call)\b/i, risk: "medium" },
  { re: /\b(create|book|schedule|add|move|assign|update)\b/i, risk: "low" },
];
const classifyCommand = (text) => (CMD_RISK.find((r) => r.re.test(text)) || { risk: "read" }).risk;
const RISK_NEEDS_PREVIEW = ["medium", "high", "destructive"];

/* what the user is looking at, so "this customer" means something */
function assistantContext({ view, selContact, selConv, convs, selAgent, agents }) {
  const bits = [];
  if (view) bits.push({ k: "screen", v: view });
  if (selContact) { const c = CONTACTS.find((x) => x.id === selContact); if (c) bits.push({ k: "contact", v: c.name, id: c.id }); }
  if (selConv) { const v = (convs || []).find((x) => x.id === selConv); const c = v && CONTACTS.find((x) => x.id === v.contactId); if (c) bits.push({ k: "conversation", v: c.name, id: v.id }); }
  if (selAgent) { const a = (agents || []).find((x) => x.id === selAgent); if (a) bits.push({ k: "agent", v: a.name, id: a.id }); }
  return bits;
}

/* browser speech, used only where the platform actually supports it */
const speechSupported = () => typeof window !== "undefined" && !!(window.SpeechRecognition || window.webkitSpeechRecognition);
const ttsSupported = () => typeof window !== "undefined" && !!window.speechSynthesis;
function makeRecognizer({ onText, onEnd, onError }) {
  if (!speechSupported()) return null;
  const R = window.SpeechRecognition || window.webkitSpeechRecognition;
  const r = new R();
  r.continuous = false; r.interimResults = true; r.lang = "en-US";
  r.onresult = (e) => {
    let text = "";
    for (let i = 0; i < e.results.length; i++) text += e.results[i][0].transcript;
    onText(text, e.results[e.results.length - 1].isFinal);
  };
  r.onerror = (e) => onError && onError(e.error === "not-allowed" ? "Microphone access was refused, so voice input is off." : e.error === "no-speech" ? "I did not catch anything." : "Speech recognition failed.");
  r.onend = () => onEnd && onEnd();
  return r;
}
function speak(text, { rate = 1, onDone } = {}) {
  if (!ttsSupported()) return false;
  window.speechSynthesis.cancel();
  const u = new SpeechSynthesisUtterance(String(text).slice(0, 600));
  u.rate = rate;
  if (onDone) u.onend = onDone;
  window.speechSynthesis.speak(u);
  return true;
}
const stopSpeaking = () => { if (ttsSupported()) window.speechSynthesis.cancel(); };

/* ==================================================================== */
/* NOTIFICATION ENGINE                                                   */
/* Notifications are derived from live platform state, so the badge can  */
/* never disagree with what is actually happening.                       */
/* ==================================================================== */

const NOTIF_PRIORITY = { critical: 3, warning: 2, success: 1, info: 0 };
const NOTIF_TINT = { critical: "text-red-500", warning: "text-amber-600", success: "text-emerald-600", info: "" };

function deriveNotifications({ approvals, appts, wfRuns, calls, convs, kb, conns, usage, ent, billing, agents, contacts }) {
  const out = [];
  const push = (o) => out.push({ ...o, id: o.key });

  (approvals || []).filter((a) => apState(a) === "Pending").forEach((a) => {
    const overdue = apDue(a) < 0;
    push({ key: "ap_" + a.id, cat: "Approvals", priority: overdue ? "critical" : ["High", "Critical"].includes(a.risk) ? "warning" : "info",
      title: overdue ? "Approval overdue" : "Approval needed",
      body: `${a.title} for ${a.to}${a.meta && a.meta.amount ? " · " + fmtMoney(a.meta.amount, "INR") : ""} · needs ${a.role}`,
      at: a.createdAt, go: "approvals" });
  });

  (appts || []).filter((a) => a.status === "Pending" || (a.status === "Booked" && new Date(a.start) - Date.now() < 36e5 * 36 && new Date(a.start) > Date.now()))
    .forEach((a) => push({ key: "ap2_" + a.id, cat: "Appointments", priority: "warning", title: "Appointment not confirmed",
      body: `${a.title} on ${fmtWhen ? fmtWhen(a) : fmtD(new Date(a.start))} has not been confirmed`, at: a.start, go: "appointments" }));

  (wfRuns || []).filter((r) => r.status === "Failed").slice(0, 5).forEach((r) =>
    push({ key: "wf_" + r.id, cat: "Automations", priority: "warning", title: "Workflow run failed",
      body: (r.trigger || "A workflow") + " · " + (r.error || "check the run detail"), at: r.at, go: "automations" }));

  (calls || []).filter((k) => k.status === "missed").forEach((k) =>
    push({ key: "call_" + k.id, cat: "Calls", priority: "warning", title: "Missed call",
      body: `${(contacts || []).find((c) => c.id === k.contactId) ? contacts.find((c) => c.id === k.contactId).name : k.number} has not been called back`, at: k.at, go: "calls" }));

  (convs || []).filter((c) => c && ((c.unread || 0) > 0 || (c.unreadCount || 0) > 0)).forEach((c) => {
    const contact = (contacts || []).find((x) => x && (x.id === c.contactId || (c.phone && x.phone === c.phone)));
    const senderName = contact?.name || c.customerName || c.name || c.phone || "Customer";
    const chLabel = (typeof CH !== "undefined" && CH[c.channel] && CH[c.channel].label) || (c.channel ? (c.channel.charAt(0).toUpperCase() + c.channel.slice(1)) : "Messages");
    const lastMsg = c.last || c.lastMessage || (Array.isArray(c.msgs) && c.msgs.length ? c.msgs[c.msgs.length - 1].text : "New message received");
    const lastTime = c.updatedAt || (Array.isArray(c.msgs) && c.msgs.length ? (c.msgs[c.msgs.length - 1].time || c.msgs[c.msgs.length - 1].at) : new Date().toISOString());
    const isCritical = ["critical", "high"].includes((c.priority || "").toLowerCase()) || (c.sentiment || "").toLowerCase() === "angry";
    const unreadNum = c.unread || c.unreadCount || 1;

    push({
      key: "msg_" + c.id,
      cat: chLabel,
      priority: isCritical ? "critical" : "warning",
      title: unreadNum > 1 ? `${unreadNum} new messages from ${senderName}` : `New message from ${senderName}`,
      body: lastMsg && lastMsg.length > 90 ? lastMsg.slice(0, 90) + "…" : (lastMsg || "New incoming message"),
      at: lastTime,
      go: "inbox",
      convId: c.id,
    });
  });

  Object.entries(conns || {}).forEach(([id, c]) => {
    const h = connHealth(c);
    if (c && c.on && ["Error", "Token expired"].includes(h.state)) {
      const p = PROVIDERS.find((x) => x.id === id);
      push({ key: "int_" + id, cat: "Integrations", priority: "critical", title: (p ? p.name : id) + " needs attention",
        body: h.why || "This connection is not usable right now, so anything depending on it will fail.", at: new Date().toISOString(), go: "integrations" });
    }
  });

  if (ent && ent.aiActions !== Infinity && usage) {
    const pct = usagePct(usage.aiActions, ent.aiActions);
    if (pct >= 75) push({ key: "usage_ai", cat: "Billing", priority: pct >= 100 ? "critical" : "warning",
      title: `AI usage at ${pct}%`, body: `${usage.aiActions.toLocaleString()} of ${ent.aiActions.toLocaleString()} monthly AI actions used${pct >= 100 ? ". New AI actions may be blocked or need approval." : "."}`,
      at: new Date().toISOString(), go: "settings" });
  }
  if (billing && ["past_due", "unpaid"].includes(billing.sub))
    push({ key: "bill_state", cat: "Billing", priority: "critical", title: billing.sub === "unpaid" ? "Subscription unpaid" : "Payment failed",
      body: billing.sub === "unpaid" ? "The workspace is restricted until this is resolved." : "You keep access during the grace period; update the payment method to clear it.",
      at: new Date().toISOString(), go: "settings" });

  (kb || []).filter((x) => !x.archived && kbFreshness(x) === "Stale").slice(0, 3).forEach((x) =>
    push({ key: "kb_" + x.id, cat: "Knowledge", priority: "info", title: "Knowledge source is stale",
      body: `${x.name} was last indexed ${kbAge(x)} days ago, so agents may be quoting old information.`, at: x.indexedAt, go: "knowledge" }));

  (agents || []).filter((a) => a.status === "Active").forEach((a) => {
    const h = agentHealth(a, 4);
    if (h.level === "Action required") push({ key: "agent_" + a.id, cat: "Agents", priority: "warning",
      title: a.name + " cannot work properly", body: h.issues[0].t, at: new Date().toISOString(), go: "agents" });
  });

  (contacts || []).filter((c) => !c.archived && c.status === "New" && (c.lastContact || 0) > 2).slice(0, 3).forEach((c) =>
    push({ key: "lead_" + c.id, cat: "Leads", priority: "info", title: "Lead not contacted",
      body: `${c.name} came in ${c.lastContact} days ago and nobody has replied.`, at: new Date().toISOString(), go: "crm" }));

  return out.sort((a, b) => NOTIF_PRIORITY[b.priority] - NOTIF_PRIORITY[a.priority] || new Date(b.at) - new Date(a.at));
}
const notifSummary = (list) => {
  const by = {};
  list.forEach((n) => { by[n.cat] = (by[n.cat] || 0) + 1; });
  return Object.entries(by).sort((a, b) => b[1] - a[1]);
};

/* ==================================================================== */
/* COMMERCIAL ENGINE: pricing, entitlements, usage                       */
/* Prices are data with explicit annual figures and versions, never      */
/* computed in a component. Entitlements are enforced at real call       */
/* sites. Usage is metered from actual platform records.                 */
/* ==================================================================== */

const PLANS = ["Starter", "Growth", "Business", "Pro", "Enterprise"];

/* commercially set per region, not FX converted. Annual is stored, not derived. */
const PRICING_REGIONS = [
  { id: "sg", label: "Singapore", cur: "SGD", sym: "S$", countries: ["SG"],
    price: { Starter: [59, 588], Growth: [149, 1484], Business: [329, 3277], Pro: [649, 6464] } },
  { id: "in", label: "India", cur: "INR", sym: "₹", countries: ["IN"],
    price: { Starter: [2499, 24890], Growth: [6999, 69700], Business: [15999, 159350], Pro: [32999, 328650] } },
  { id: "us", label: "United States and Canada", cur: "USD", sym: "$", countries: ["US", "CA"],
    price: { Starter: [49, 488], Growth: [129, 1285], Business: [299, 2978], Pro: [599, 5966] } },
  { id: "eu", label: "Europe", cur: "EUR", sym: "€", countries: ["DE", "FR", "ES", "IT", "NL", "IE", "PT"],
    price: { Starter: [49, 488], Growth: [129, 1285], Business: [279, 2779], Pro: [579, 5767] } },
  { id: "uk", label: "United Kingdom", cur: "GBP", sym: "£", countries: ["GB"],
    price: { Starter: [42, 418], Growth: [109, 1086], Business: [239, 2380], Pro: [499, 4970] } },
  { id: "au", label: "Australia", cur: "AUD", sym: "A$", countries: ["AU", "NZ"],
    price: { Starter: [79, 787], Growth: [199, 1982], Business: [449, 4472], Pro: [899, 8954] } },
  { id: "af", label: "Africa", cur: "USD", sym: "$", countries: ["NG", "KE", "ZA", "GH", "UG", "TZ"],
    price: { Starter: [25, 249], Growth: [69, 687], Business: [149, 1484], Pro: [299, 2978] } },
  { id: "latam", label: "Latin America", cur: "USD", sym: "$", countries: ["BR", "MX", "AR", "CO", "CL"],
    price: { Starter: [29, 289], Growth: [79, 787], Business: [179, 1783], Pro: [349, 3476] } },
  { id: "me", label: "Middle East", cur: "USD", sym: "$", countries: ["AE", "SA", "QA", "KW", "BH"],
    price: { Starter: [39, 388], Growth: [109, 1086], Business: [249, 2480], Pro: [499, 4970] } },
  { id: "sea", label: "Southeast and East Asia", cur: "USD", sym: "$", countries: ["MY", "ID", "TH", "PH", "VN", "JP", "KR", "HK", "TW"],
    price: { Starter: [39, 388], Growth: [99, 986], Business: [229, 2281], Pro: [449, 4472] } },
];
const ANNUAL_DISCOUNT = 0.17;
/* resolve region from country, never from a client supplied price */
function resolveRegion(countryCode) {
  const cc = (countryCode || "").toUpperCase();
  return PRICING_REGIONS.find((r) => r.countries.includes(cc)) || PRICING_REGIONS.find((r) => r.id === "us");
}
function priceFor(regionId, plan, cycle = "monthly") {
  const r = PRICING_REGIONS.find((x) => x.id === regionId) || PRICING_REGIONS[0];
  if (plan === "Enterprise") return { amount: null, cur: r.cur, sym: r.sym, label: "Custom", region: r };
  const pair = r.price[plan];
  if (!pair) return { amount: null, cur: r.cur, sym: r.sym, label: "unavailable", region: r };
  const amount = cycle === "annual" ? pair[1] : pair[0];
  const saving = cycle === "annual" ? Math.round(pair[0] * 12 - pair[1]) : 0;
  return { amount, cur: r.cur, sym: r.sym, region: r, saving,
    label: r.sym + amount.toLocaleString() + (cycle === "annual" ? " a year" : " a month"),
    monthlyEquivalent: cycle === "annual" ? Math.round(pair[1] / 12) : pair[0] };
}
const fmtMoney = (n, cur = "INR") => {
  const num = Number(n) || 0;
  const v = Math.abs(num) >= 100000 ? (num / 100000).toFixed(1) + "L" : Math.abs(num) >= 1000 ? (num / 1000).toFixed(1) + "k" : Math.round(num).toLocaleString("en-IN");
  return "₹" + v;
};

/* what each plan actually allows. Enforced at the call sites below. */
const ENTITLEMENTS = {
  Starter:    { users: 3,  agents: 2,  workflows: 3,  campaigns: 2,  contacts: 1000,  knowledge: 5,  brands: 1, socialAccounts: 2, aiActions: 1000,  apiAccess: false, advancedGovernance: false, analytics: "basic" },
  Growth:     { users: 10, agents: 6,  workflows: 15, campaigns: 10, contacts: 10000, knowledge: 25, brands: 2, socialAccounts: 6, aiActions: 5000,  apiAccess: true,  advancedGovernance: false, analytics: "full" },
  Business:   { users: 25, agents: 15, workflows: 50, campaigns: 40, contacts: 50000, knowledge: 100, brands: 5, socialAccounts: 15, aiActions: 20000, apiAccess: true, advancedGovernance: true,  analytics: "full" },
  Pro:        { users: 60, agents: 40, workflows: 200, campaigns: 150, contacts: 250000, knowledge: 400, brands: 15, socialAccounts: 40, aiActions: 50000, apiAccess: true, advancedGovernance: true, analytics: "full" },
  Enterprise: { users: Infinity, agents: Infinity, workflows: Infinity, campaigns: Infinity, contacts: Infinity, knowledge: Infinity, brands: Infinity, socialAccounts: Infinity, aiActions: Infinity, apiAccess: true, advancedGovernance: true, analytics: "full" },
};
const ENT_LABELS = { users: "team members", agents: "AI agents", workflows: "workflows", campaigns: "campaigns", contacts: "contacts", knowledge: "knowledge sources", brands: "brands", socialAccounts: "social accounts", aiActions: "AI actions a month" };

/* subscription lifecycle, mirroring the billing provider's own states */
const SUB_STATES = {
  trialing:  { label: "Trial", tint: "bg-sky-50 text-sky-700 border-sky-200", entitled: true },
  active:    { label: "Active", tint: "bg-emerald-50 text-emerald-700 border-emerald-200", entitled: true },
  past_due:  { label: "Payment failed", tint: "bg-amber-50 text-amber-700 border-amber-200", entitled: true, grace: true },
  unpaid:    { label: "Unpaid", tint: "bg-red-50 text-red-700 border-red-200", entitled: false },
  paused:    { label: "Paused", tint: "bg-zinc-100 text-zinc-500 border-zinc-200", entitled: false },
  canceled:  { label: "Cancelled", tint: "bg-zinc-100 text-zinc-500 border-zinc-200", entitled: false },
};

/* usage metered from real platform records, never a stored counter */
function meterUsage({ activity, calls, camps, convs, kb, days = 30 }) {
  const recent = (activity || []).filter((e) => inRange(e.at, days));
  const aiActions = recent.filter((e) => e.actorType === "agent" || e.actorType === "workflow").length;
  const voiceMinutes = (calls || []).filter((k) => inRange(k.at, days)).reduce((a, k) => a + (k.durSec || 0), 0) / 60;
  const waSends = (camps || []).filter((c) => c.channel === "whatsapp").reduce((a, c) => a + campMetrics(c).sent, 0)
    + (convs || []).reduce((a, v) => a + (v.msgs || []).filter((m) => m.from === "ai" && (m.channel || v.channel) === "whatsapp").length, 0);
  const emailSends = (camps || []).filter((c) => c.channel === "email").reduce((a, c) => a + campMetrics(c).sent, 0);
  const smsSends = (camps || []).filter((c) => c.channel === "sms").reduce((a, c) => a + campMetrics(c).sent, 0);
  const storageMb = (kb || []).reduce((a, s2) => a + Math.round((s2.text || "").length / 1024), 0);
  return { aiActions, voiceMinutes: Math.round(voiceMinutes), waSends, emailSends, smsSends, storageMb,
    workflowRuns: recent.filter((e) => e.category === "workflow").length };
}
/* per unit rates for metered services, editable by the workspace */
const METER_RATES = { aiAction: 0.004, voiceMinute: 0.09, waSend: 0.011, emailSend: 0.0004, smsSend: 0.019 };
function usageCost(u, rates = METER_RATES) {
  return { ai: u.aiActions * rates.aiAction, voice: u.voiceMinutes * rates.voiceMinute, wa: u.waSends * rates.waSend,
    email: u.emailSends * rates.emailSend, sms: u.smsSends * rates.smsSend,
    total: u.aiActions * rates.aiAction + u.voiceMinutes * rates.voiceMinute + u.waSends * rates.waSend + u.emailSends * rates.emailSend + u.smsSends * rates.smsSend };
}
/* project month end from elapsed days so an alert fires before the bill does */
function projectUsage(used, dayOfMonth = new Date().getDate()) {
  const daysInMonth = new Date(new Date().getFullYear(), new Date().getMonth() + 1, 0).getDate();
  const factor = daysInMonth / Math.max(dayOfMonth, 1);
  return Math.round(used * factor);
}
/* the entitlement gate: called before anything that consumes an allowance */
function checkEntitlement(key, currentCount, { plan, sub }) {
  const ent = ENTITLEMENTS[plan] || ENTITLEMENTS.Starter;
  const state = SUB_STATES[sub] || SUB_STATES.active;
  if (!state.entitled) return { ok: false, code: "SUBSCRIPTION", why: `Your subscription is ${state.label.toLowerCase()}, so new ${ENT_LABELS[key] || key} cannot be added until it is reactivated.` };
  const limit = ent[key];
  if (limit === undefined) return { ok: true };
  if (limit === Infinity) return { ok: true, remaining: Infinity };
  if (currentCount >= limit) {
    const next = PLANS[PLANS.indexOf(plan) + 1];
    return { ok: false, code: "LIMIT", limit, why: `Your ${plan} plan includes ${limit.toLocaleString()} ${ENT_LABELS[key] || key} and you are using ${currentCount.toLocaleString()}.${next ? ` ${next} includes ${ENTITLEMENTS[next][key] === Infinity ? "unlimited" : ENTITLEMENTS[next][key].toLocaleString()}.` : ""}` };
  }
  return { ok: true, remaining: limit - currentCount, limit };
}
const usagePct = (used, allowed) => allowed === Infinity || !allowed ? 0 : Math.min(100, Math.round((used / allowed) * 100));

/* ---- AI model registry and router ---- */
const AI_PROVIDERS = [
  { id: "openai", name: "OpenAI", keyField: "llm", models: [
    { id: "gpt-4o-mini", label: "GPT-4o mini", ctx: 128000, tools: true, reasoning: false, cost: 0.0006, speed: "fast" },
    { id: "gpt-4o", label: "GPT-4o", ctx: 128000, tools: true, reasoning: true, cost: 0.005, speed: "balanced" }] },
  { id: "anthropic", name: "Anthropic", keyField: "llmAlt", models: [
    { id: "claude-haiku", label: "Claude Haiku", ctx: 200000, tools: true, reasoning: false, cost: 0.0008, speed: "fast" },
    { id: "claude-sonnet", label: "Claude Sonnet", ctx: 200000, tools: true, reasoning: true, cost: 0.006, speed: "balanced" }] },
  { id: "openweight", name: "Open weight, self hosted", keyField: "selfHost", models: [
    { id: "glm-4", label: "GLM-4", ctx: 128000, tools: true, reasoning: true, cost: 0.0002, speed: "balanced" },
    { id: "qwen-72b", label: "Qwen 72B", ctx: 32000, tools: true, reasoning: false, cost: 0.0001, speed: "fast" }] },
];
const AI_TASKS = {
  reply:     { label: "Customer replies", needs: { speed: "fast" } },
  qualify:   { label: "Lead qualification", needs: { tools: true } },
  workflow:  { label: "Workflow generation", needs: { reasoning: true } },
  analytics: { label: "Analytics investigation", needs: { reasoning: true } },
  longdoc:   { label: "Long document analysis", needs: { ctx: 100000 } },
  content:   { label: "Content writing", needs: {} },
};
/* pick a model for a task from the configured providers, with an explained reason */
function routeModel(task, cfg) {
  const need = (AI_TASKS[task] || {}).needs || {};
  const all = AI_PROVIDERS.filter((p) => (cfg.enabled || []).includes(p.id)).flatMap((p) => p.models.map((m) => ({ ...m, provider: p.id, providerName: p.name })));
  if (!all.length) return { model: null, why: "No AI provider is configured, so nothing can run." };
  let pool = all.filter((m) => (!need.tools || m.tools) && (!need.reasoning || m.reasoning) && (!need.ctx || m.ctx >= need.ctx));
  if (!pool.length) pool = all;
  const preferred = pool.find((m) => m.id === cfg.primary) || (need.speed === "fast" ? pool.sort((a, b) => a.cost - b.cost)[0] : pool.sort((a, b) => b.cost - a.cost)[0]);
  const fallback = pool.find((m) => m.id !== preferred.id && m.id === cfg.fallback) || pool.find((m) => m.id !== preferred.id) || null;
  return { model: preferred, fallback,
    why: `${AI_TASKS[task] ? AI_TASKS[task].label : task} needs ${need.reasoning ? "reasoning" : need.tools ? "tool calling" : need.ctx ? "a long context window" : "no special capability"}, so ${preferred.label} was selected${fallback ? ` with ${fallback.label} as fallback` : ""}.` };
}

/* ==================================================================== */
/* ANALYTICS ENGINE                                                      */
/* Pure functions over live platform records. No literal ever appears in */
/* a metric: if there is no data the figure is null and the UI says so.  */
/* ==================================================================== */

const RANGES = [
  { id: "7d", label: "7 days", days: 7 }, { id: "30d", label: "30 days", days: 30 },
  { id: "90d", label: "90 days", days: 90 }, { id: "ytd", label: "Year", days: 365 },
];
const inRange = (iso, days, offset = 0) => {
  if (!iso) return false;
  const t = new Date(iso).getTime();
  const end = Date.now() - offset * days * 86400000;
  const start = end - days * 86400000;
  return t > start && t <= end;
};
const pctChange = (now, prev) => (prev === 0 || prev === undefined || prev === null) ? (now > 0 ? 100 : null) : Math.round(((now - prev) / prev) * 100);
const money = (n) => "₹" + (Math.abs(n) >= 100000 ? (n / 100000).toFixed(1) + "L" : Math.abs(n) >= 1000 ? (n / 1000).toFixed(1) + "k" : Math.round(n).toLocaleString("en-IN"));
const csvOf = (rows, headers) => [headers.join(","), ...rows.map((r) => headers.map((h) => `"${String(r[h] ?? "").replace(/"/g, '""')}"`).join(","))].join("\n");

function attribute(data, model = "first") {
  const { deals, contacts, calls, convs } = data;
  const won = deals.filter((d) => d.stage === "Won");
  const rows = {};
  const add = (key, value, count) => { rows[key] = rows[key] || { source: key, revenue: 0, deals: 0 }; rows[key].revenue += value; rows[key].deals += count; };
  won.forEach((d) => {
    const c = contacts.find((x) => x.id === d.contactId);
    const first = c ? c.source : "Unknown";
    const touches = [];
    if (c) {
      touches.push(c.source);
      const v = convs.find((x) => x.contactId === c.id);
      if (v) touches.push(CH[v.channel] ? CH[v.channel].label : "Chat");
      if (calls.some((k) => k.contactId === c.id)) touches.push("Phone");
      if (d.campaign) touches.push("Campaign");
    }
    const uniq = [...new Set(touches.filter(Boolean))];
    if (model === "first") add(first, d.value, 1);
    else if (model === "last") add(uniq[uniq.length - 1] || first, d.value, 1);
    else uniq.forEach((t) => add(t, d.value / uniq.length, 1 / uniq.length));
  });
  return Object.values(rows).sort((a, b) => b.revenue - a.revenue);
}

function funnel(data, days) {
  const { contacts, convs, appts, deals } = data;
  const live = contacts.filter((c) => !c.archived);
  const captured = live.filter((c) => inRange(c.created, days) || !c.created);
  const engaged = captured.filter((c) => convs.some((v) => v.contactId === c.id) || (c.lastContact || 99) < days);
  const qualified = captured.filter((c) => ["Qualified", "Converted"].includes(c.status));
  const booked = captured.filter((c) => appts.some((a) => a.contactId === c.id));
  const attended = captured.filter((c) => appts.some((a) => a.contactId === c.id && a.status === "Completed"));
  const wonDeals = deals.filter((d) => d.stage === "Won" && captured.some((c) => c.id === d.contactId));
  const stages = [
    { k: "Captured", n: captured.length }, { k: "Engaged", n: engaged.length }, { k: "Qualified", n: qualified.length },
    { k: "Appointment booked", n: booked.length }, { k: "Attended", n: attended.length }, { k: "Won", n: wonDeals.length },
  ];
  const withDrop = stages.map((st, i) => {
    const prev = i === 0 ? st.n : stages[i - 1].n;
    return { ...st, conv: prev ? Math.round((st.n / prev) * 100) : null, drop: prev - st.n };
  });
  const worst = withDrop.slice(1).filter((x) => x.conv !== null).sort((a, b) => a.conv - b.conv)[0];
  return { stages: withDrop, worst, overall: captured.length ? Math.round((wonDeals.length / captured.length) * 100) : null };
}

function channelPerf(data, days) {
  const { convs, calls, deals, camps } = data;
  const keys = [...new Set([...convs.map((v) => v.channel), "voice"])];
  return keys.map((ch) => {
    const vs = ch === "voice" ? calls.filter((k) => inRange(k.at, days)) : convs.filter((v) => v.channel === ch);
    const people = [...new Set(vs.map((v) => v.contactId).filter(Boolean))];
    const wonHere = deals.filter((d) => d.stage === "Won" && people.includes(d.contactId));
    const revenue = wonHere.reduce((a, d) => a + d.value, 0);
    const campSent = camps.filter((c) => c.channel === ch).reduce((a, c) => a + campMetrics(c).sent, 0);
    return { ch, label: ch === "voice" ? "Voice" : (CH[ch] ? CH[ch].label : ch), conversations: vs.length, people: people.length,
      won: wonHere.length, revenue, sent: campSent, convRate: people.length ? Math.round((wonHere.length / people.length) * 100) : null };
  }).filter((r) => r.conversations || r.sent).sort((a, b) => b.revenue - a.revenue || b.conversations - a.conversations);
}

function agentPerf(data) {
  const { agents, convs, calls, approvals } = data;
  return agents.filter((a) => a.status !== "Archived").map((a) => {
    const full = agentFullName(a);
    const myConvs = convs.filter((v) => (v.agent || "").startsWith(a.name));
    const myCalls = calls.filter((k) => (k.agent || "").startsWith(a.name));
    const myAps = approvals.filter((x) => x.agent === full || (x.agent || "").startsWith(a.name));
    const decided = myAps.filter((x) => ["Approved", "Executed", "Rejected"].includes(x.status));
    const approved = myAps.filter((x) => ["Approved", "Executed"].includes(x.status));
    const rate = decided.length ? Math.round((approved.length / decided.length) * 100) : null;
    return { a, handled: myConvs.length + myCalls.length, convs: myConvs.length, calls: myCalls.length,
      escalations: myConvs.filter((v) => v.state === "Escalated").length, actions: (a.activity || []).length,
      approvals: myAps.length, approvalRate: rate, autonomyReady: decided.length >= 3 && rate !== null && rate >= 90 };
  }).sort((x, y) => y.handled - x.handled);
}

const COSTS_INIT = { aiPerConversation: 0.08, voicePerMinute: 0.11, msgPerSend: 0.012, humanPerHour: 22, minutesPerHumanReply: 4 };
function economics(data, costs) {
  const { convs, calls, camps, deals } = data;
  const aiConvs = convs.filter((v) => v.ai).length;
  const humanConvs = convs.filter((v) => !v.ai).length;
  const callMinutes = calls.reduce((a, k) => a + (k.durSec || 0), 0) / 60;
  const sends = camps.reduce((a, c) => a + campMetrics(c).sent, 0);
  const aiCost = aiConvs * costs.aiPerConversation + callMinutes * costs.voicePerMinute + sends * costs.msgPerSend;
  const humanCost = humanConvs * (costs.minutesPerHumanReply / 60) * costs.humanPerHour;
  const allHuman = (aiConvs + humanConvs) * (costs.minutesPerHumanReply / 60) * costs.humanPerHour;
  const wonList = deals.filter((d) => d.stage === "Won");
  const revenue = wonList.reduce((a, d) => a + d.value, 0);
  const total = aiCost + humanCost;
  return { aiConvs, humanConvs, callMinutes: Math.round(callMinutes), sends, aiCost, humanCost, total,
    saved: Math.max(0, allHuman - total), revenue, roi: total ? Math.round(((revenue - total) / total) * 100) : null,
    costPerConversation: (aiConvs + humanConvs) ? total / (aiConvs + humanConvs) : null,
    costPerWonDeal: wonList.length ? total / wonList.length : null };
}

function insights(data, days) {
  const out = [];
  const { contacts, appts, wfRuns, approvals, kbGaps } = data;
  const nowLeads = contacts.filter((c) => inRange(c.created, days)).length;
  const prevLeads = contacts.filter((c) => inRange(c.created, days, 1)).length;
  const dLeads = pctChange(nowLeads, prevLeads);
  if (dLeads !== null && Math.abs(dLeads) >= 10) {
    const bySource = {}, prevBySource = {};
    contacts.filter((c) => inRange(c.created, days)).forEach((c) => { bySource[c.source] = (bySource[c.source] || 0) + 1; });
    contacts.filter((c) => inRange(c.created, days, 1)).forEach((c) => { prevBySource[c.source] = (prevBySource[c.source] || 0) + 1; });
    const movers = Object.keys({ ...bySource, ...prevBySource }).map((k) => ({ k, delta: (bySource[k] || 0) - (prevBySource[k] || 0) })).sort((a, b) => Math.abs(b.delta) - Math.abs(a.delta));
    out.push({ kind: dLeads > 0 ? "up" : "down", title: `New contacts ${dLeads > 0 ? "up" : "down"} ${Math.abs(dLeads)}%`,
      why: movers[0] && movers[0].delta !== 0 ? `${movers[0].k} moved by ${movers[0].delta > 0 ? "+" : ""}${movers[0].delta}, the biggest change of any source.` : "Spread evenly across sources.", go: "crm" });
  }
  const stale = contacts.filter((c) => !c.archived && (c.lastContact || 0) >= 30).length;
  if (stale > 0) out.push({ kind: "risk", title: `${stale} contacts have gone quiet for 30 days or more`, why: "Nothing is scheduled against them, so they will decay unless a follow up campaign picks them up.", go: "crm" });
  const noShow = appts.filter((a) => a.status === "No show").length;
  const totalAppt = appts.filter((a) => a.status !== "Cancelled").length;
  if (totalAppt && noShow / totalAppt > 0.1) out.push({ kind: "risk", title: `No show rate is ${Math.round((noShow / totalAppt) * 100)}%`, why: `${noShow} of ${totalAppt} appointments were missed. Reminder coverage is the usual cause.`, go: "appointments" });
  const overdue = approvals.filter((a) => apState(a) === "Pending" && apDue(a) < 0);
  if (overdue.length) out.push({ kind: "risk", title: `${overdue.length} approvals are past their SLA`, why: "Agent work is blocked while these wait, which slows every downstream response.", go: "approvals" });
  const failedRuns = wfRuns.filter((r) => r.status === "Failed").length;
  if (failedRuns) out.push({ kind: "risk", title: `${failedRuns} workflow runs failed`, why: "Failed automation silently stops customer follow up; check the run detail for the failing node.", go: "automations" });
  if ((kbGaps || []).length) out.push({ kind: "risk", title: `${kbGaps.length} questions have no source to answer them`, why: "Agents fall back to a human on these, which is where response time goes.", go: "knowledge" });
  const f = funnel(data, days);
  if (f.worst && f.worst.conv !== null && f.worst.conv < 60) out.push({ kind: "opportunity", title: `Biggest funnel leak: ${f.worst.k} at ${f.worst.conv}%`, why: `${f.worst.drop} people did not reach this stage. Fixing the step before it moves everything downstream.`, go: "crm" });
  agentPerf(data).filter((x) => x.autonomyReady).forEach((x) => out.push({ kind: "opportunity", title: `${x.a.name} is approved unchanged ${x.approvalRate}% of the time`, why: "Raising its autonomy would stop routine work queueing for a human. This is a suggestion; nothing changes on its own.", go: "agents" }));
  return out;
}

function forecast(data, days) {
  const { deals, contacts } = data;
  const won = deals.filter((d) => d.stage === "Won");
  const open = deals.filter((d) => d.stage !== "Won");
  const weighted = open.reduce((a, d) => a + d.value * ((d.prob ?? 50) / 100), 0);
  const nowLeads = contacts.filter((c) => inRange(c.created, days)).length;
  const prevLeads = contacts.filter((c) => inRange(c.created, days, 1)).length;
  const growth = prevLeads ? (nowLeads - prevLeads) / prevLeads : 0;
  return { weighted, closedSoFar: won.reduce((a, d) => a + d.value, 0), openCount: open.length,
    projectedLeads: Math.round(nowLeads * (1 + growth)), growth: Math.round(growth * 100),
    basis: `${open.length} open deals weighted by their own probability, and lead growth of ${Math.round(growth * 100)}% period over period.` };
}

