const SEV_TINT = { info: "", notable: "text-sky-600", warning: "text-amber-600", critical: "text-red-500" };

/* infer structure from the way the rest of the app already calls log() */
function classifyEvent(actorName, action, detail) {
  const a = (action || "").toLowerCase(), d = (detail || "").toLowerCase();
  let category = "system";
  if (/message|reply|sent|whatsapp|email|sms|conversation|assigned|escalat/.test(a)) category = "message";
  if (/contact|deal|lead|tag|note|task|crm|pipeline|stage/.test(a)) category = "crm";
  if (/appointment|booked|reschedul|no show|confirm/.test(a)) category = "appointment";
  if (/call/.test(a)) category = "call";
  if (/workflow|run/.test(a)) category = "workflow";
  if (/campaign|opt out|suppress/.test(a)) category = "campaign";
  if (/knowledge|source|index/.test(a)) category = "knowledge";
  if (/approval|approved|rejected/.test(a)) category = "approval";
  if (/agent/.test(a)) category = "agent";
  if (/post|content|social/.test(a)) category = "social";
  let outcome = "success";
  if (/fail|error|could not|unable/.test(a + " " + d)) outcome = "failed";
  if (/block|guardrail|refused|denied/.test(a + " " + d)) outcome = "blocked";
  if (/queue|waiting|pending/.test(a + " " + d)) outcome = "queued";
  if (/reject/.test(a)) outcome = "rejected";
  if (/expired/.test(a)) outcome = "expired";
  const mode = actorName === "You" || /^[A-Z][a-z]+ [A-Z]/.test(actorName || "") && !/agent|orchestrator|workflow|system|buzzz/i.test(actorName || "") ? "human"
    : /system|workflow/i.test(actorName || "") ? "system"
    : /approved/.test(a) ? "approved" : "autonomous";
  const severity = outcome === "failed" ? "critical" : outcome === "blocked" ? "warning"
    : /deleted|archived|refund|payment|autonomy|published/.test(a) ? "notable" : "info";
  return { category, outcome, mode, severity };
}
/* link an event to the customer it concerns by scanning the text for a known name */
const findEntity = (text) => {
  const t = (text || "");
  const c = CONTACTS.find((x) => t.includes(x.name));
  return c ? { type: "contact", id: c.id, name: c.name } : null;
};
const makeEvent = ({ actor, action, detail, category, outcome, mode, severity, entity, related, cost, ms, reason, before, after }) => {
  const auto = classifyEvent(actor, action, detail);
  return {
    id: "e" + Date.now() + Math.random().toString(36).slice(2, 6),
    at: new Date().toISOString(),
    actor: actor || "System",
    actorType: /agent|orchestrator|buzzz|voz|sky|mira|sarah|kai|ana/i.test(actor || "") ? "agent" : /workflow/i.test(actor || "") ? "workflow" : /system/i.test(actor || "") ? "system" : "human",
    action: action || "Action", detail: detail || "",
    category: category || auto.category, outcome: outcome || auto.outcome, mode: mode || auto.mode, severity: severity || auto.severity,
    entity: entity || findEntity(detail) || null, related: related || null,
    cost: cost || null, ms: ms || null, reason: reason || null, before: before ?? null, after: after ?? null,
  };
};

/* ---- querying the ledger ---- */
function filterEvents(events, f) {
  return events.filter((e) => {
    if (f.actor && e.actor !== f.actor) return false;
    if (f.actorType && e.actorType !== f.actorType) return false;
    if (f.category && e.category !== f.category) return false;
    if (f.outcome && e.outcome !== f.outcome) return false;
    if (f.mode && e.mode !== f.mode) return false;
    if (f.severity && e.severity !== f.severity) return false;
    if (f.contactId && (!e.entity || e.entity.id !== f.contactId)) return false;
    if (f.days && !inRange(e.at, f.days)) return false;
    if (f.q && f.q.trim()) {
      const hay = [e.actor, e.action, e.detail, e.entity && e.entity.name, e.reason].join(" ").toLowerCase();
      if (!hay.includes(String(f.q || "").toLowerCase())) return false;
    }
    return true;
  });
}
const dayKey = (iso) => {
  const d = new Date(iso), n = new Date();
  if (sameDay(d, n)) return "Today";
  const y = new Date(n); y.setDate(y.getDate() - 1);
  if (sameDay(d, y)) return "Yesterday";
  return d.toLocaleDateString([], { weekday: "long", day: "numeric", month: "short" });
};
function groupByDay(events) {
  const out = [];
  events.forEach((e) => {
    const k = dayKey(e.at);
    let g = out.find((x) => x.key === k);
    if (!g) { g = { key: k, items: [] }; out.push(g); }
    g.items.push(e);
  });
  return out;
}
/* reconstruct what led to an event: same customer, immediately before it */
function chainFor(event, events, span = 8) {
  if (!event.entity) return [];
  const idx = events.findIndex((e) => e.id === event.id);
  return events.slice(idx, idx + span + 1).filter((e) => e.entity && e.entity.id === event.entity.id).reverse();
}
function eventStats(events) {
  const by = (fn) => events.filter(fn).length;
  const byCat = {}; events.forEach((e) => { byCat[e.category] = (byCat[e.category] || 0) + 1; });
  const byActor = {}; events.forEach((e) => { byActor[e.actor] = (byActor[e.actor] || 0) + 1; });
  return {
    total: events.length,
    autonomous: by((e) => e.mode === "autonomous"), approved: by((e) => e.mode === "approved"), human: by((e) => e.mode === "human"),
    failed: by((e) => e.outcome === "failed"), blocked: by((e) => e.outcome === "blocked"),
    autonomyRate: events.length ? Math.round((by((e) => e.mode === "autonomous") / events.length) * 100) : null,
    successRate: events.length ? Math.round((by((e) => e.outcome === "success") / events.length) * 100) : null,
    cost: events.reduce((a, e) => a + (e.cost || 0), 0),
    byCat: Object.entries(byCat).sort((a, b) => b[1] - a[1]),
    byActor: Object.entries(byActor).sort((a, b) => b[1] - a[1]),
  };
}
