/* AND/OR audience resolution against real CRM records */
function resolveAudience(rule, ctx) {
  const { suppression = [], prefs = {} } = ctx || {};
  const test = (c, f) => {
    if (f.status && !f.status.split(",").includes(c.status)) return false;
    if (f.source && c.source !== f.source) return false;
    if (f.owner && c.owner !== f.owner) return false;
    if (f.tag && !(c.tags || []).some((t) => String(t || "").toLowerCase().includes(String(f.tag).toLowerCase()))) return false;
    if (f.stage && c.stage !== f.stage) return false;
    if (f.minScore && c.score < +f.minScore) return false;
    if (f.staleDays && (c.lastContact || 0) < +f.staleDays) return false;
    if (f.minValue && (parseFloat(String(c.value).replace(/[^0-9.]/g, "")) || 0) < +f.minValue) return false;
    return true;
  };
  const groups = rule.groups && rule.groups.length ? rule.groups : [{}];
  const live = CONTACTS.filter((c) => !c.archived);
  const matched = live.filter((c) => rule.join === "OR" ? groups.some((g) => test(c, g)) : groups.every((g) => test(c, g)));

  const seen = new Set(), excluded = [], eligible = [];
  matched.forEach((c) => {
    const key = (c.phone || c.email || c.name).replace(/\s/g, "").toLowerCase();
    if (seen.has(key)) { excluded.push({ c, why: "Duplicate record" }); return; }
    seen.add(key);
    const ch = rule.channel;
    if (suppression.some((x) => x.contactId === c.id && (x.channel === ch || x.channel === "all"))) { excluded.push({ c, why: "Opted out" }); return; }
    const pref = prefs[c.id] || {};
    if (pref[ch] === false) { excluded.push({ c, why: "Channel preference off" }); return; }
    const need = CH_CAPS[ch] ? CH_CAPS[ch].needs : "phone";
    if (need === "phone" && !c.phone) { excluded.push({ c, why: "Missing phone number" }); return; }
    if (need === "email" && !c.email) { excluded.push({ c, why: "Missing email address" }); return; }
    if (need === "phone" && c.phone && c.phone.replace(/\D/g, "").length < 8) { excluded.push({ c, why: "Invalid number" }); return; }
    if ((need === "instagram" || need === "telegram") && !(c.channels || []).includes(need)) { excluded.push({ c, why: "Never messaged you on " + CH_CAPS[ch].label }); return; }
    eligible.push(c);
  });
  return { matched, eligible, excluded };
}

/* {{variables}} resolved from the real contact record */
function personalize(text, c, extra) {
  if (!c) return text;
  const map = {
    first_name: c.name.split(" ")[0], full_name: c.name, company_name: c.company === "—" ? "your team" : c.company,
    owner: c.owner, stage: c.stage, city: (c.location || c.loc || "").split(",")[0] || "your area",
    deal_value: c.value, ...(extra || {}),
  };
  return text.replace(/\{\{(\w+)\}\}/g, (m, k) => (map[k] !== undefined && map[k] !== "" ? map[k] : "{{" + k + "}}"));
}
const missingVars = (text, c) => (text.match(/\{\{(\w+)\}\}/g) || []).filter((v) => personalize(v, c) === v);

/* pre launch validation */
function validateCampaign(camp, audience, accountsOn) {
  const errs = [], warns = [];
  if (!camp.name.trim()) errs.push("Give the campaign a name.");
  if (!camp.body.trim()) errs.push("Write the message.");
  if (!audience.eligible.length) errs.push("No eligible recipients. Widen the audience or fix the exclusions.");
  if (!accountsOn) errs.push(CH_CAPS[camp.channel].label + " is not connected. Connect it in Integrations first.");
  const sample = audience.eligible[0];
  if (sample && missingVars(camp.body, sample).length) warns.push("Some recipients are missing values for " + missingVars(camp.body, sample).join(", ") + "; those merge tags stay literal.");
  if (camp.channel === "sms" && camp.body.length > 480) warns.push("This SMS is " + Math.ceil(camp.body.length / 160) + " segments and will be billed as such.");
  if (camp.ab.on && !camp.ab.bodyB.trim()) errs.push("Variant B is empty.");
  if (audience.eligible.length > 500) warns.push("Large send. At " + camp.throttle + " per minute this takes about " + Math.ceil(audience.eligible.length / camp.throttle) + " minutes.");
  return { errs, warns };
}
const estMinutes = (n, throttle) => Math.max(1, Math.ceil(n / Math.max(throttle, 1)));
/* Quiet hours are stored as hour numbers (from: 9, to: 19) meaning "send between
   these hours". Accept a string too, because settings imported from elsewhere
   may arrive as "21:00" and calling .split on a number crashes the app. */
const quietHour = (v, fallback) => {
  if (typeof v === "number" && isFinite(v)) return Math.min(23, Math.max(0, Math.floor(v)));
  const m = String(v ?? "").match(/^\s*(\d{1,2})/);
  if (!m) return fallback;
  let h = parseInt(m[1], 10);
  if (/pm/i.test(String(v)) && h < 12) h += 12;
  if (/am/i.test(String(v)) && h === 12) h = 0;
  return isFinite(h) ? Math.min(23, Math.max(0, h)) : fallback;
};
/* `from` and `to` describe the SENDING window; quiet is everything outside it. */
const inQuietHours = (rules, now = new Date()) => {
  const from = quietHour(rules && rules.from, 9), to = quietHour(rules && rules.to, 19);
  const h = now.getHours();
  if (from === to) return false;                       // a zero length window blocks nothing
  return from < to ? (h < from || h >= to)             // normal daytime window
                   : (h < from && h >= to);            // window wrapping midnight
};

const CAMPAIGNS = [];   /* real campaigns only — nothing seeded */

/* ==================================================================== */
/* KNOWLEDGE / RAG LAYER                                                 */
/* Chunking, vectorization, retrieval, citation and confidence run here. */
/* The vectorizer is TF-IDF computed locally so retrieval is genuinely   */
/* working in this build; swap `embed` for a neural embedding call on    */
/* the server and nothing else in the pipeline changes.                  */
/* ==================================================================== */

const STOP = new Set("a an the and or but if then than of to in on for with without at by from is are was were be been being it its this that these those we you your our their as we're can cannot do does not no yes will would should could may might must have has had".split(" "));
const tokenize = (t) => String(t || "").toLowerCase().replace(/[^a-z0-9%$. ]/g, " ").split(/\s+/).filter((w) => w.length > 1 && !STOP.has(w));

/* heading aware chunking: keeps sections together instead of cutting every N characters */
function chunkText(text, { source, maxWords = 90 } = {}) {
  const lines = String(text || "").split("\n");
  const out = [];
  let heading = "", buf = [], page = 1;
  const flush = () => {
    if (!buf.length) return;
    const body = buf.join(" ").trim();
    if (body) out.push({ id: "ch" + out.length + "_" + Math.random().toString(36).slice(2, 6), heading, text: body, page, source, words: body.split(/\s+/).length });
    buf = [];
  };
  lines.forEach((raw) => {
    const line = raw.trim();
    if (!line) { if (buf.join(" ").split(/\s+/).length > 40) flush(); return; }
    if (/^#{1,3}\s/.test(line) || (/^[A-Z][A-Za-z0-9 ,'&-]{2,60}$/.test(line) && line.split(" ").length <= 8 && !/[.!?]$/.test(line))) {
      flush(); heading = line.replace(/^#+\s*/, ""); return;
    }
    if (/^page\s+\d+/i.test(line)) { flush(); page = parseInt(line.replace(/\D/g, ""), 10) || page; return; }
    buf.push(line);
    if (buf.join(" ").split(/\s+/).length >= maxWords) flush();
  });
  flush();
  return out;
}

/* the embedder. Local TF weighting today; one server call away from neural. */
const embed = (text) => {
  const toks = tokenize(text);
  const v = {};
  toks.forEach((t) => { v[t] = (v[t] || 0) + 1; });
  const norm = Math.sqrt(Object.values(v).reduce((a, b) => a + b * b, 0)) || 1;
  Object.keys(v).forEach((k) => { v[k] = v[k] / norm; });
  return v;
};
const cosine = (a, b) => {
  let dot = 0;
  const [small, big] = Object.keys(a).length < Object.keys(b).length ? [a, b] : [b, a];
  Object.keys(small).forEach((k) => { if (big[k]) dot += small[k] * big[k]; });
  return dot;
};
/* idf boost so rare business terms outrank common filler */
function buildIndex(chunks) {
  const df = {};
  chunks.forEach((c) => { new Set(tokenize(c.text + " " + c.heading)).forEach((t) => { df[t] = (df[t] || 0) + 1; }); });
  const N = Math.max(chunks.length, 1);
  return chunks.map((c) => {
    const v = embed(c.text + " " + c.heading + " " + c.heading);
    Object.keys(v).forEach((t) => { v[t] = v[t] * (1 + Math.log(N / (1 + (df[t] || 0)))); });
    const norm = Math.sqrt(Object.values(v).reduce((a, b) => a + b * b, 0)) || 1;
    Object.keys(v).forEach((t) => { v[t] = v[t] / norm; });
    return { ...c, vec: v };
  });
}

const KB_STATUS = ["Queued", "Fetching", "Parsing", "Chunking", "Embedding", "Indexing", "Indexed", "Failed", "Stale"];
const KB_TYPES = ["PDF", "Document", "FAQ", "Website page", "Website crawl", "Product catalog", "Plain text"];
const FRESHNESS = { fresh: 30, due: 60 };   // days
const kbAge = (src) => Math.round((Date.now() - new Date(src.indexedAt || src.createdAt).getTime()) / 86400000);
const kbFreshness = (src) => {
  if (src.status !== "Indexed") return src.status === "Failed" ? "Failed refresh" : "Not indexed";
  const age = kbAge(src);
  return age <= FRESHNESS.fresh ? "Fresh" : age <= FRESHNESS.due ? "Due for refresh" : "Stale";
};

/* permission scoped retrieval — the agent's grant list is applied BEFORE search */
function retrieve(query, { sources, agent, topK = 4, threshold = 0.12 } = {}) {
  const allowedIds = agent
    ? sources.filter((s2) => (agent.knowledge || []).includes(s2.name) || (agent.knowledge || []).includes(s2.id)).map((s2) => s2.id)
    : sources.map((s2) => s2.id);
  const pool = sources.filter((s2) => allowedIds.includes(s2.id) && s2.status === "Indexed" && !s2.archived);
  const denied = sources.filter((s2) => !allowedIds.includes(s2.id) && !s2.archived);
  if (!pool.length) return { hits: [], allowed: 0, denied: denied.length, confidence: 0, reason: agent ? `${agent.name} has no indexed knowledge sources granted.` : "No indexed sources." };
  const chunks = pool.flatMap((s2) => (s2.chunks || []).map((c) => ({ ...c, srcId: s2.id, srcName: s2.name, srcType: s2.type, priority: s2.priority || 3, fresh: kbFreshness(s2) })));
  const indexed = buildIndex(chunks);
  const q = embed(query);
  const scored = indexed.map((c) => {
    let score = cosine(q, c.vec);
    score = score * (1 + (4 - Math.min(c.priority, 4)) * 0.06);          // authority nudge
    if (c.fresh === "Stale") score = score * 0.85;                        // stale content ranks lower
    return { ...c, score };
  }).sort((a, b) => b.score - a.score).slice(0, topK).filter((c) => c.score > 0);
  const top = scored[0];
  const confidence = top ? Math.min(1, top.score / 0.45) : 0;
  const hits = scored.filter((c) => c.score >= threshold);
  return { hits, allowed: pool.length, denied: denied.length, confidence,
    reason: hits.length ? "" : `Nothing in ${agent ? agent.name + "'s" : "the"} approved sources is relevant enough to answer this.` };
}

/* conflicting facts across sources: same subject, different number */
const CONFLICT_PATTERNS = [
  { id: "refund", label: "refund window", re: /refund[^.]{0,40}?(\d+)\s*(day|days|hours)/i },
  { id: "cancel", label: "cancellation window", re: /cancel[^.]{0,40}?(\d+)\s*(day|days|hour|hours)/i },
  { id: "delivery", label: "delivery time", re: /deliver[^.]{0,40}?(\d+)\s*(day|days|week|weeks)/i },
  { id: "warranty", label: "warranty period", re: /warrant[^.]{0,40}?(\d+)\s*(month|months|year|years)/i },
];
function findConflicts(sources) {
  const out = [];
  CONFLICT_PATTERNS.forEach((p) => {
    const found = [];
    sources.filter((s2) => !s2.archived && s2.status === "Indexed").forEach((s2) => {
      (s2.chunks || []).forEach((c) => {
        const m = c.text.match(p.re);
        if (m) found.push({ src: s2, chunk: c, value: m[1] + " " + m[2] });
      });
    });
    const values = [...new Set(found.map((f) => f.value.replace(/s$/, "")))];
    if (values.length > 1) out.push({ topic: p.label, values, found });
  });
  return out;
}

/* health computed from the real corpus */
function knowledgeHealth(sources, gaps) {
  const live = sources.filter((s2) => !s2.archived);
  const indexed = live.filter((s2) => s2.status === "Indexed");
  const stale = indexed.filter((s2) => kbFreshness(s2) === "Stale").length;
  const failed = live.filter((s2) => s2.status === "Failed").length;
  const conflicts = findConflicts(live).length;
  const answered = gaps.filter((g) => g.answered).length;
  const coverage = gaps.length ? Math.round((answered / gaps.length) * 100) : (indexed.length ? 100 : 0);
  let score = 100;
  if (!live.length) score = 0;
  score -= stale * 8; score -= failed * 12; score -= conflicts * 10;
  score -= Math.round((100 - coverage) * 0.35);
  score = Math.max(0, Math.min(100, score));
  return { score, coverage, stale, failed, conflicts, indexed: indexed.length, total: live.length,
    level: score >= 80 ? "Healthy" : score >= 55 ? "Needs attention" : "Critical" };
}

