/* ---- connection health ---- */
const CONN_STATES = ["Connected", "Not connected", "Error", "Token expired", "Syncing", "Paused"];
const CONN_TINT = { Connected: "bg-emerald-50 text-emerald-700 border-emerald-200", "Not connected": "bg-zinc-100 text-zinc-500 border-zinc-200",
  Error: "bg-red-50 text-red-700 border-red-200", "Token expired": "bg-amber-50 text-amber-700 border-amber-200",
  Syncing: "bg-sky-50 text-sky-700 border-sky-200", Paused: "bg-amber-50 text-amber-700 border-amber-200" };
function connHealth(c) {
  if (!c || !c.on) return { state: "Not connected", why: "" };
  if (c.error) return { state: "Error", why: c.error };
  if (c.expiresAt && new Date(c.expiresAt) < new Date()) return { state: "Token expired", why: "The access token expired and needs reconnecting. Nothing syncs until it is renewed." };
  if (c.paused) return { state: "Paused", why: "Sync is paused by you." };
  if (c.syncing) return { state: "Syncing", why: "" };
  const stale = c.lastSync && (Date.now() - new Date(c.lastSync).getTime()) > 3 * 86400000;
  if (stale) return { state: "Error", why: "No successful sync in over three days." };
  return { state: "Connected", why: "" };
}

/* ---- mapping + conflict engine ---- */
function mapRecord(mapping, remote) {
  const out = {}, skipped = [];
  (mapping || []).forEach((m) => {
    if (!m.on) { skipped.push(m.ours); return; }
    const parts = m.theirs.split("+").map((p) => p.trim());
    const vals = parts.map((p) => p.split(".").reduce((o, k) => (o === undefined || o === null ? undefined : o[k]), remote)).filter((v) => v !== undefined && v !== null && v !== "");
    if (!vals.length) { skipped.push(m.ours); return; }
    out[m.ours] = vals.join(" ");
  });
  return { mapped: out, skipped };
}
function detectConflicts(local, incoming, rule) {
  const fields = [];
  Object.keys(incoming).forEach((k) => {
    const a = local[k], b = incoming[k];
    if (a === undefined || a === null || a === "" || String(a) === String(b)) return;
    fields.push({ field: k, ours: a, theirs: b });
  });
  const resolve = (f) => {
    if (rule === "Buzzz wins") return { take: "ours", value: f.ours };
    if (rule === "Their system wins") return { take: "theirs", value: f.theirs };
    if (rule === "Ask me") return { take: "manual", value: null };
    const theirsNewer = incoming.__updatedAt && local.__updatedAt ? new Date(incoming.__updatedAt) > new Date(local.__updatedAt) : true;
    return { take: theirsNewer ? "theirs" : "ours", value: theirsNewer ? f.theirs : f.ours };
  };
  return fields.map((f) => ({ ...f, ...resolve(f) }));
}
/* one sync pass: returns exactly what happened, including what it refused to do */
function runSyncPass({ provider, connection, remoteRecords, localRecords, matchOn = "email" }) {
  const started = Date.now();
  const res = { at: new Date().toISOString(), provider: provider.id, direction: connection.direction,
    created: [], updated: [], skipped: [], conflicts: [], errors: [], scanned: (remoteRecords || []).length };
  if (connection.direction === "Out of Buzzz") { res.errors.push({ why: "Direction is out of Buzzz only, so nothing was pulled." }); return res; }
  (remoteRecords || []).forEach((r) => {
    if (r.__error) { res.errors.push({ id: r.id, why: r.__error }); return; }
    const { mapped, skipped } = mapRecord(connection.mapping, r);
    if (!mapped.name && !mapped.email) { res.skipped.push({ id: r.id, why: "No name or email after mapping, so it cannot be matched safely." }); return; }
    const local = (localRecords || []).find((l) => matchOn === "email" ? (l.email && mapped.email && l.email.toLowerCase() === mapped.email.toLowerCase())
      : (l.phone && mapped.phone && normPhone(l.phone) === normPhone(mapped.phone)));
    if (!local) { res.created.push({ id: r.id, name: mapped.name || mapped.email, fields: Object.keys(mapped), skippedFields: skipped }); return; }
    const conflicts = detectConflicts(local, { ...mapped, __updatedAt: r.__updatedAt }, connection.conflict);
    const manual = conflicts.filter((c) => c.take === "manual");
    if (manual.length) { res.conflicts.push({ id: r.id, name: local.name, fields: manual }); return; }
    if (!conflicts.length) { res.skipped.push({ id: r.id, why: "Already identical, nothing to write." }); return; }
    res.updated.push({ id: r.id, localId: local.id, name: local.name, changes: conflicts });
  });
  res.ms = Date.now() - started + 40;
  return res;
}
/* what stops working if this connector goes away */
function dependenciesOf(providerId, { agents = [], wfs = [], camps = [], accounts = [] } = {}) {
  const p = PROVIDERS.find((x) => x.id === providerId);
  if (!p) return { agents: [], workflows: [], campaigns: [], channels: [] };
  const toolName = { gowhats: "GoWhats", instaxbot: "InstaxBot", mrassistant: "MrAssistant.ai", gmail: "Gmail", gcal: "Calendar", stripe: "Payments", shopify: "CRM" }[providerId];
  const chan = { gowhats: "whatsapp", instaxbot: "instagram", gmail: "email", telegram: "telegram", mrassistant: "voice", youtube: "youtube" }[providerId];
  return {
    agents: agents.filter((a) => toolName && (a.tools || []).includes(toolName)),
    workflows: wfs.filter((w) => (w.nodes || []).some((n) => n.type === "act" && WF_ACTIONS[n.action] && WF_ACTIONS[n.action].integration === p.name)),
    campaigns: chan ? camps.filter((c) => c.channel === chan && ["Running", "Scheduled"].includes(c.status)) : [],
    channels: chan ? [chan] : [],
  };
}
