/* which starters make sense for this business */
function suggestCdmCampaigns(bp) {
  const out = [];
  const ind = (bp && bp.profile && bp.profile.industry) || null;
  const goals = (bp && bp.goals) || [];
  if (bp && bp.appointments && bp.appointments.relevant) out.push("booking");
  if (ind === "hospitality") out.push("menu");
  if (["retail", "furniture", "pharmacy"].includes(ind)) out.push("pricelist");
  if (["healthcare", "salon", "fitness", "wellness", "veterinary", "education", "legal", "accounting", "services", "realestate"].includes(ind)) out.push("pricelist");
  if (goals.includes("leads") || goals.includes("sales")) out.push("leadmagnet");
  if (!out.length) out.push("leadmagnet");
  return [...new Set(out)].slice(0, 3);
}

/* ==================================================================== */
/* GOOGLE API CLIENT                                                     */
/* The browser never holds Google credentials. Every call goes to the    */
/* BUZZZ API, which is the only place a client secret or refresh token   */
/* may exist. When no API is configured this reports that plainly rather */
/* than pretending a meeting was created.                                */
/* ==================================================================== */

/* Read the API base from a global rather than import.meta: the artifact runner
   evaluates this file as a plain script, where import.meta is a parse error.
   Set window.BUZZZ_API_BASE in index.html, or inject it at build time. */
const API_BASE = (typeof globalThis !== "undefined" && globalThis.BUZZZ_API_BASE) ||
  (typeof import.meta !== "undefined" && (import.meta.env?.VITE_API_URL || import.meta.env?.VITE_API_BASE_URL || import.meta.env?.VITE_API_BASE)) ||
  "http://localhost:5000";

async function apiCall(path, { method = "GET", body, timeoutMs = 15000 } = {}) {
  const apiBase = API_BASE || "http://localhost:5000";
  const ctrl = new AbortController();
  const timer = setTimeout(() => ctrl.abort(), timeoutMs);
  try {
    let token = null;
    try {
      const s = JSON.parse(localStorage.getItem("buzzz_session") || "{}");
      token = s.token;
    } catch (e) {}
    const headers = { "content-type": "application/json" };
    if (token) {
      headers["authorization"] = `Bearer ${token}`;
      headers["x-session-token"] = token;
    }
    const res = await fetch(`${apiBase}${path}`, {
      method, credentials: "include", signal: ctrl.signal,
      headers,
      body: body ? JSON.stringify(body) : undefined,
    });
    const data = await res.json().catch(() => ({}));
    if (!res.ok) return { ok: false, status: res.status, code: data.code || "error", message: data.message || `Request failed (${res.status})`, retryable: !!data.retryable };
    return { ok: true, status: res.status, data };
  } catch (e) {
    const aborted = e && e.name === "AbortError";
    return { ok: false, status: 0, code: aborted ? "timeout" : "network",
      message: aborted ? "Request timed out." : "Could not reach the BUZZZ API.", retryable: true };
  } finally { clearTimeout(timer); }
}

const googleApi = {
  status: () => apiCall("/api/v1/google/status"),
  connect: () => apiCall("/api/v1/google/connect", { method: "POST" }),
  disconnect: () => apiCall("/api/v1/google/disconnect", { method: "POST" }),
  freeBusy: (b) => apiCall("/api/v1/google/freebusy", { method: "POST", body: b }),
  createMeeting: (id) => apiCall(`/api/v1/google/appointments/${id}/meeting`, { method: "POST" }),
  moveMeeting: (id, b) => apiCall(`/api/v1/google/appointments/${id}/meeting`, { method: "PATCH", body: b }),
  cancelMeeting: (id) => apiCall(`/api/v1/google/appointments/${id}/meeting`, { method: "DELETE" }),
};

/* ==================================================================== */
/* VIRTUAL APPOINTMENTS                                                  */
/* Meeting links come from Google through the API. Nothing here invents  */
/* a URL: an appointment without a real link is shown as unfinished.     */
/* ==================================================================== */

const APPT_TYPES = [
  { id: "in_person", label: "In person" },
  { id: "virtual", label: "Virtual" },
  { id: "phone", label: "Phone" },
  { id: "other", label: "Other" },
];
/* none → pending → ready, or failed. "ready" is the only state that may be
   presented to a customer as a confirmed meeting. */
const MEETING_STATES = ["none", "pending", "ready", "failed", "cancelled"];

const isVirtual = (a) => (a && a.type) === "virtual";
const meetingReady = (a) => isVirtual(a) && a.meetingState === "ready" && !!a.meetUrl;

/* A virtual appointment can only be confirmed once the meeting really exists. */
function canConfirmAppt(a) {
  if (!isVirtual(a)) return { ok: true };
  if (a.meetingState === "failed") return { ok: false, reason: a.meetingError || "The meeting could not be created" };
  if (!a.meetUrl) return { ok: false, reason: "Waiting for Google to create the meeting" };
  return { ok: true };
}
/* Only accept a link that is actually a Google Meet URL, so a bad API response
   or a hand typed value can never reach a customer. */
const MEET_URL = /^https:\/\/meet\.google\.com\/[a-z]{3}-[a-z]{4}-[a-z]{3}(\?.*)?$/i;
function acceptMeetLink(url) {
  return MEET_URL.test(String(url || "").trim()) ? String(url).trim() : null;
}

/* The message a customer receives. Returns null rather than a message with a
   missing link, because a confirmation without a join link is worse than none. */
function meetingMessage(a, { contactName, business, when } = {}) {
  if (isVirtual(a) && !meetingReady(a)) return null;
  const lines = [];
  lines.push(`${contactName ? "Hi " + contactName + ", y" : "Y"}our appointment is confirmed for ${when || ""}.`.replace(/\s+\./, "."));
  if (meetingReady(a)) lines.push(`Join here: ${a.meetUrl}`);
  if (a.timeZone) lines.push(`Times shown in ${a.timeZone}.`);
  lines.push(`We look forward to speaking with you${business ? ", " + business : ""}.`);
  return lines.join("\n");
}

/* Reminder plan. Offsets are minutes before the start. Anything already in the
   past is not scheduled, and the same offset is never scheduled twice. */
const DEFAULT_REMINDERS = [1440, 60, 15];
function planReminders(a, { offsets = DEFAULT_REMINDERS, channel = "whatsapp", now = Date.now(), existing = [] } = {}) {
  const start = new Date(a.start).getTime();
  const seen = new Set(existing.map((r) => `${r.offset}:${r.channel}`));
  const out = [];
  [...new Set(offsets)].sort((x, y) => y - x).forEach((off) => {
    const key = `${off}:${channel}`;
    if (seen.has(key)) return;
    const at = start - off * 60000;
    if (at <= now) return;
    seen.add(key);
    out.push({ offset: off, channel, sendAt: new Date(at).toISOString(), status: "scheduled" });
  });
  return out;
}
/* Rescheduling moves the pending reminders and drops any that are now in the
   past; reminders already sent are left alone as a record. */
function reshiftReminders(reminders, newStartISO, now = Date.now()) {
  const start = new Date(newStartISO).getTime();
  return (reminders || []).map((r) => {
    if (r.status !== "scheduled") return r;
    const at = start - r.offset * 60000;
    return at <= now ? { ...r, status: "cancelled" } : { ...r, sendAt: new Date(at).toISOString() };
  });
}
const cancelReminders = (reminders) => (reminders || []).map((r) => (r.status === "scheduled" ? { ...r, status: "cancelled" } : r));

/* Double booking check across BUZZZ appointments and Google busy blocks. */
function apptConflicts(candidate, appts, busy = []) {
  const s = new Date(candidate.start).getTime();
  const e = s + (candidate.durMin || 30) * 60000;
  const overlaps = (as, ae) => s < ae && as < e;
  const clashes = [];
  (appts || []).forEach((a) => {
    if (a.id === candidate.id) return;
    if (a.status === "Cancelled") return;
    if (candidate.staffId && a.staffId !== candidate.staffId) return;
    const as = new Date(a.start).getTime();
    if (overlaps(as, as + (a.durMin || 30) * 60000)) clashes.push({ kind: "appointment", with: a.id, title: a.title });
  });
  (busy || []).forEach((b) => {
    const bs = new Date(b.start).getTime(), be = new Date(b.end).getTime();
    if (overlaps(bs, be)) clashes.push({ kind: "calendar", start: b.start, end: b.end });
  });
  return clashes;
}

/* Timezones: store UTC, show the viewer's zone, and say which zone when the
   customer and the business are not in the same one. */
function fmtInZone(iso, timeZone, opts = {}) {
  try {
    return new Intl.DateTimeFormat(undefined, {
      dateStyle: opts.dateStyle || "medium", timeStyle: opts.timeStyle || "short", timeZone,
    }).format(new Date(iso));
  } catch { return new Date(iso).toLocaleString(); }
}
function zoneNote(businessTz, customerTz) {
  if (!customerTz || !businessTz || customerTz === businessTz) return null;
  return `Shown in ${businessTz}. The customer is in ${customerTz}.`;
}

/* Virtual appointment analytics, counted from records rather than invented. */
function virtualStats(appts) {
  const v = (appts || []).filter(isVirtual);
  const by = (s) => v.filter((a) => a.status === s).length;
  const completed = by("Completed"), noShow = by("No show");
  const attended = completed + noShow;
  return {
    total: v.length, upcoming: v.filter((a) => new Date(a.start) > new Date() && a.status !== "Cancelled").length,
    completed, cancelled: by("Cancelled"), noShow,
    rescheduled: v.filter((a) => (a.rescheduleCount || 0) > 0).length,
    failed: v.filter((a) => a.meetingState === "failed").length,
    /* null rather than zero when nothing has happened yet, so an empty
       workspace does not read as a 0% attendance rate */
    attendanceRate: attended ? Math.round((completed / attended) * 100) : null,
  };
}

/* The ordered steps an agent must complete before it may claim success. */
const VIRTUAL_STEPS = ["availability", "staff", "appointment", "calendar", "meet", "link", "confirmation", "reminders", "crm", "audit"];
function bookingOutcome(done) {
  const missing = VIRTUAL_STEPS.filter((s) => !done.includes(s));
  return { ok: missing.length === 0, missing,
    /* an agent that stops early must say so rather than report a booking */
    message: missing.length === 0 ? "Booked and confirmed"
      : `Not completed: ${missing[0]} failed, so the customer has not been told the meeting is confirmed.` };
}

