/* PUBLIC SITE AND AUTHENTICATION GATE                                   */
/* A visitor sees the marketing site. Onboarding only exists behind an   */
/* account, and an onboarded user never sees it again. The server        */
/* decides the destination; this only renders it.                        */
/* ==================================================================== */

/* Session shape: null = signed out. The real token lives in an http only
   cookie set by the API, never in JavaScript. */
/* ---- demo account ----
   There is no auth server in this build, so a real login cannot be checked.
   Rather than fake a signed in state silently, the demo is an explicit,
   clearly labelled account that only works while no API is configured. The
   moment BUZZZ_API_BASE is set, this path is dead and the server decides. */
const DEMO_EMAIL = "demo@buzzzbuzzz.com";
const DEMO_PASSWORD = "buzzz-demo-2026";
/* Two staff logins, because the roles are genuinely different. The operator
   can look; the owner can grant write access into a client workspace and
   suspend one, which are the two actions that need the highest bar. */
const DEMO_STAFF_EMAIL = "ops@buzzzbuzzz.com";
const DEMO_STAFF_PASSWORD = "buzzz-ops-2026";
const OWNER_EMAIL = "owner@buzzzbuzzz.com";
const OWNER_PASSWORD = "buzzz-owner-2026";
const DEMO_AVAILABLE = !API_BASE;
const demoSession = (screen) => ({
  demo: true,
  user: { id: "demo-user", email: DEMO_EMAIL, name: "Demo account", emailVerified: true },
  workspaces: [{ workspaceId: "demo-ws", role: "owner", onboardingComplete: screen === "dashboard" }],
  next: screen === "dashboard" ? { screen: "dashboard", workspaceId: "demo-ws" }
                               : { screen: "onboarding", workspaceId: "demo-ws" },
});

const authApi = {
  signUp: (body) => apiCall("/api/v1/auth/signup", { method: "POST", body }),
  logIn: async (body) => {
    let result;
    const email = String((body && body.email) || "").trim().toLowerCase();
    const pass = String((body && body.password) || "");
    if (email === DEMO_EMAIL && pass === DEMO_PASSWORD) {
      result = { ok: true, data: demoSession("dashboard") };
    } else {
      result = await apiCall("/api/v1/auth/login", { method: "POST", body });
      if (!result.ok && DEMO_AVAILABLE && result.code === "no_api") {
        result = { ok: false, code: "invalid_credentials", status: 0,
          message: `Use the demo account: ${DEMO_EMAIL} / ${DEMO_PASSWORD}` };
      }
    }
    if (result.ok && result.data) {
      try { localStorage.setItem("buzzz_session", JSON.stringify(result.data)); } catch (e) {}
    }
    return result;
  },
  logOut: async () => {
    try { localStorage.removeItem("buzzz_session"); } catch (e) {}
    try {
      const apiBase = typeof API_BASE !== "undefined" && API_BASE ? API_BASE : "http://localhost:5000";
      await fetch(`${apiBase}/api/v1/auth/logout`, { method: "POST", credentials: "include" });
    } catch (e) {}
    return { ok: true };
  },
  session: async () => {
    let localData = null;
    try {
      const raw = localStorage.getItem("buzzz_session");
      if (raw) localData = JSON.parse(raw);
    } catch (e) {}

    if (localData && localData.token) {
      try {
        const remote = await apiCall("/api/v1/auth/session");
        if (remote.ok && remote.data && remote.data.user) {
          const merged = { ...remote.data, token: localData.token };
          try { localStorage.setItem("buzzz_session", JSON.stringify(merged)); } catch (e) {}
          return { ok: true, data: merged };
        }
      } catch (e) {}
    }

    if (localData && (localData.user || localData.demo)) {
      return { ok: true, data: localData };
    }

    return { ok: false, code: "no_session", message: "no active session" };
  },
  resetRequest: (body) => apiCall("/api/v1/auth/reset", { method: "POST", body }),
  demoSignUp: () => {
    const data = demoSession("onboarding");
    try { localStorage.setItem("buzzz_session", JSON.stringify(data)); } catch (e) {}
    return Promise.resolve({ ok: true, data });
  },
};

