/* ---- the channel litany ----
   Martin repeats "Text Martin. Call Martin. Email Martin." as oversized
   headings. The same shape states BUZZZ's actual surface area: the customer
   picks the channel, and the same workforce answers on all of them. */
const CHANNEL_LITANY = [
  ["WhatsApp", "A message at 11pm gets an answer at 11pm."],
  ["Instagram", "A comment becomes a conversation, then a booking."],
  ["Email", "Threads read and answered against the same record."],
  ["Call", "Picked up, transcribed, written back to the customer."],
  ["SMS", "Reminders and confirmations that actually arrive."],
  ["Web chat", "The visitor who would otherwise have left."],
];

function ChannelLitany() {
  const [active, setActive] = useState(0);
  const allowed = useMotionAllowed();
  const litanyRef = useRef(null);
  useVisibleInterval(litanyRef, () => setActive((n) => (n + 1) % CHANNEL_LITANY.length), 2600, allowed);
  return (
    <div className="grid gap-1.5" ref={litanyRef}>
      {CHANNEL_LITANY.map(([ch, line], i) => (
        <button key={ch} onMouseEnter={() => setActive(i)} onClick={() => setActive(i)} data-cursor="hear"
          className="text-center group" style={{ color: INK }}>
          <div className="bz-display text-[30px] sm:text-[44px] leading-[1.06] tracking-[-0.035em] font-bold transition-colors duration-300 flex items-center gap-3 justify-center"
            style={{ color: i === active ? INK : "#9A9AA0" }}>
            <ChannelBadge name={ch} size={i === active ? 20 : 16} />
            {ch} BUZZZ.
          </div>
          <div className="overflow-hidden transition-all duration-500"
            style={{ maxHeight: i === active ? 40 : 0, opacity: i === active ? 1 : 0 }}>
            <div className="text-[13.5px] pb-2" style={{ color: MUTE }}>{line}</div>
          </div>
        </button>
      ))}
    </div>
  );
}

