function MiniApp() {
  const cur = useDemoCurrency();
  const [view, setView] = useState("Inbox");
  const [sel, setSel] = useState("m1");
  const [step, setStep] = useState(0);
  const allowed = useMotionAllowed();
  const convo = MINI_CONVOS.find((c) => c.id === sel) || MINI_CONVOS[0];
  const thread = MINI_THREADS[sel];

  /* the work ticks in after the reply, which is the point being made */
  useEffect(() => {
    setStep(0);
    if (!allowed) { setStep(thread.did.length); return; }
    let n = 0;
    const t = setInterval(() => { n += 1; setStep(n); if (n >= thread.did.length) clearInterval(t); }, 620);
    return () => clearInterval(t);
  }, [sel, allowed]);

  const appRef = useRef(null);
  useVisibleInterval(appRef, () => setSel((cur) =>
    MINI_CONVOS[(MINI_CONVOS.findIndex((c) => c.id === cur) + 1) % MINI_CONVOS.length].id), 7200, allowed);

  const bubble = (kind, text, i) => {
    const mine = kind === "ai" || kind === "hum";
    return (
      <div key={i} className={`flex ${mine ? "justify-end" : "justify-start"}`}>
        <div className="rounded-lg px-3 py-2 text-[11px] leading-snug max-w-[86%]"
          style={mine
            ? { background: kind === "ai" ? RED : "#E4E4E7", color: kind === "ai" ? "#fff" : INK, borderBottomRightRadius: 3 }
            : { background: "#F4F4F5", color: INK, borderBottomLeftRadius: 3 }}>
          {kind === "ai" && <span className="opacity-80 mr-1">BUZZZ AI</span>}
          {kind === "hum" && <span className="opacity-60 mr-1">You</span>}
          {text}
        </div>
      </div>
    );
  };

  return (
    <div className="h-full flex text-left" ref={appRef} style={{ color: INK }}>
      {/* nav rail */}
      <div className="w-[74px] shrink-0 flex flex-col" style={{ borderRight: `1px solid ${LINE}`, background: "#FCFCFC" }}>
        <div className="h-7 shrink-0 flex items-center gap-1.5 px-3" style={{ borderBottom: `1px solid ${LINE}` }}>
          <Logo mark height={15} />
        </div>
        <div className="flex flex-col gap-0.5 pt-2">
        {MINI_NAV.map(([label, Icon]) => {
          /* Inbox and CRM are real views here; the rest are shown for context
             and are deliberately not clickable rather than dead buttons */
          const live = label === "Inbox" || label === "CRM";
          const on = view === label;
          return (
            <button key={label} onClick={() => live && setView(label)} data-cursor={live ? "open" : undefined}
              className="flex items-center gap-1.5 px-2 py-1.5 rounded-md mx-1 text-left transition-colors"
              style={on ? { background: RED_WASH, color: RED } : { color: live ? INK : MUTE, opacity: live ? 1 : 0.5 }}>
              <Icon size={12} />
              <span className="text-[10px] font-medium">{label}</span>
            </button>
          );
        })}
        </div>
      </div>

      {view === "CRM" ? <MiniCrm /> : <>
      {/* conversation list */}
      <div className="w-[30%] shrink-0 flex flex-col overflow-hidden" style={{ borderRight: `1px solid ${LINE}` }}>
        <div className="h-7 shrink-0 flex items-center gap-1.5 px-3" style={{ borderBottom: `1px solid ${LINE}` }}>
          <span className="text-[10.5px] font-semibold">All conversations</span>
          <span className="text-[9.5px] px-1 rounded-full" style={{ background: RED_WASH, color: RED }}>3</span>
        </div>
        {MINI_CONVOS.map((c) => (
          <button key={c.id} onClick={() => setSel(c.id)} data-cursor="open"
            className="w-full text-left px-3 py-2 transition-colors"
            style={{ borderBottom: `1px solid ${LINE}`, background: c.id === sel ? RED_WASH : "transparent" }}>
            <div className="flex items-center gap-1">
              <span className="text-[11px] font-semibold truncate flex-1">{c.who}</span>
              <span className="text-[9.5px]" style={{ color: MUTE }}>{c.when}</span>
              {c.unread > 0 && <span className="w-1 h-1 rounded-full" style={{ background: RED }} />}
            </div>
            <div className="text-[10px] truncate mt-0.5" style={{ color: MUTE }}>{c.last}</div>
            <div className="flex items-center gap-1 mt-1">
              <ChannelBadge name={c.channel} size={11} withLabel />
              {c.ai && <span className="text-[11px] px-1 rounded-full" style={{ background: RED_WASH, color: RED }}>AI</span>}
            </div>
          </button>
        ))}
      </div>

      {/* the thread */}
      <div className="flex-1 min-w-0 flex flex-col">
        <div className="h-7 shrink-0 flex items-center gap-1.5 px-3" style={{ borderBottom: `1px solid ${LINE}` }}>
          <span className="w-5 h-5 rounded-full flex items-center justify-center text-[9px] text-white font-bold" style={{ background: REDGRAD }}>
            {convo.who.charAt(0)}
          </span>
          <span className="text-[11px] font-semibold truncate">{convo.who}</span>
          <ChannelBadge name={convo.channel} size={10} withLabel />
          <div className="flex-1" />
          <span className="text-[11px] px-1 rounded-full" style={{ background: RED_WASH, color: RED }}>Level 3</span>
        </div>
        <div className="flex-1 min-h-0 px-3 py-2 space-y-1 overflow-hidden">
          {thread.msgs.map(([k, t], i) =>
            bubble(k, String(t).replace("{p14}", demoMoney(14, cur)).replace("{p72}", demoMoney(72, cur)), i))}
        </div>
        <div className="px-3 py-2" style={{ borderTop: `1px solid ${LINE}` }}>
          <div className="text-[9.5px] mb-1" style={{ color: MUTE }}>What BUZZZ did</div>
          {thread.did.map((d, n) => (
            <div key={d} className="flex items-center gap-1 text-[10px] py-0.5"
              style={{ opacity: n < step ? 1 : 0.18, transition: "opacity .4s ease" }}>
              <span className="w-3.5 h-3.5 rounded-full flex items-center justify-center shrink-0"
                style={{ background: n < step ? RED : "#E7E5E4" }}>
                <Check size={7} color="#fff" />
              </span>
              {d}
            </div>
          ))}
        </div>
      </div>

      {/* the customer record, which is the point: one thread, one record */}
      <div className="w-[24%] shrink-0 hidden md:flex flex-col" style={{ borderLeft: `1px solid ${LINE}`, background: "#FCFCFC" }}>
        <div className="h-7 shrink-0 flex items-center gap-1.5 px-3" style={{ borderBottom: `1px solid ${LINE}` }}>
          <span className="text-[9.5px] uppercase tracking-wider" style={{ color: MUTE }}>Customer</span>
        </div>
        <div className="px-3 pt-2">
        <div className="text-[11px] font-semibold truncate">{convo.who}</div>
        <div className="mt-2 space-y-1.5">
          {[["Stage", thread.crm.stage], ["Value", demoMoney(thread.crm.value, cur)], ["Source", thread.crm.source]].map(([k, v]) => (
            <div key={k}>
              <div className="text-[11px]" style={{ color: MUTE }}>{k}</div>
              <div className="text-[10px] font-medium">{v}</div>
            </div>
          ))}
          <div>
            <div className="text-[11px]" style={{ color: MUTE }}>Tags</div>
            <span className="text-[11px] px-1 rounded-full inline-block mt-0.5" style={{ background: RED_WASH, color: RED }}>{thread.crm.tag}</span>
          </div>
        </div>
        <div className="mt-2 pt-1.5" style={{ borderTop: `1px solid ${LINE}` }}>
          <div className="text-[11px]" style={{ color: MUTE }}>Next</div>
          <div className="text-[10px] font-medium">Reminder in 24h</div>
        </div>
        </div>
      </div>
      </>}
    </div>
  );
}

