    if (typeof sessionStorage !== "undefined") {
      const flashUser = sessionStorage.getItem("buzzz_auth_flash");
      if (flashUser) {
        try { sessionStorage.removeItem("buzzz_auth_flash"); } catch (e) {}
        flash(`Successfully signed in with Google as ${flashUser}!`);
      }
    }

    if (typeof window !== "undefined" && window.location.search) {
      const params = new URLSearchParams(window.location.search);
      if (params.get("linkedin") === "connected") {
        const user = params.get("user") || "LinkedIn User";
        flash(`LinkedIn account connected successfully as ${user}!`);
        window.history.replaceState({}, document.title, window.location.pathname);
      } else if (params.get("linkedin") === "error") {
        const msg = params.get("msg") || "LinkedIn authorization failed";
        flash(`LinkedIn connection error: ${msg}`, "err");
        window.history.replaceState({}, document.title, window.location.pathname);
      } else if (params.get("google") === "connected") {
        const user = params.get("user") || "Google Account";
        if (user && user !== "Google Account") {
          setConns((prev) => ({
            ...prev,
            gmail: { ...prev.gmail, on: true, account: user },
          }));
        }
        flash(`Google email account connected successfully as ${user}!`);
        syncGoogleConnectionStatus();
        window.history.replaceState({}, document.title, window.location.pathname);
      } else if (params.get("google") === "error") {
        const msg = params.get("msg") || "Google authorization failed";
        flash(`Google connection error: ${msg}`, "err");
        window.history.replaceState({}, document.title, window.location.pathname);
      } else if (params.get("auth") === "success") {
        const token = params.get("token");
        const user = params.get("user") || "User";
        if (token) {
          const sessionPayload = {
            demo: false,
            user: { id: `usr_${Date.now()}`, email: user, name: user.split("@")[0] || "User" },
            token,
            workspaces: [{ workspaceId: "ws_default", role: "owner", onboardingComplete: true }],
            next: { screen: "dashboard", workspaceId: "ws_default" },
          };
          try { localStorage.setItem("buzzz_session", JSON.stringify(sessionPayload)); } catch (e) {}
        }
        flash(`Successfully signed in with Google as ${user}!`);
        window.history.replaceState({}, document.title, window.location.pathname);
      } else if (params.get("auth") === "error") {
        const msg = params.get("msg") || "Google sign in failed";
        flash(`Google sign in error: ${msg}`, "err");
        window.history.replaceState({}, document.title, window.location.pathname);
      }
    }

    return () => window.removeEventListener("focus", onFocus);
