/* Suggested, never imposed: the caller shows this and lets the user change it. */
function suggestLocale({ country, browserLangs = [], tz } = {}) {
  const reg = REGIONS[country] || null;
  /* Walk the user's own preference order, not the region's, so a Tamil speaker
     in Singapore is offered Tamil rather than the country's first language. */
  const wanted = (browserLangs || []).map((l) => String(l).split("-")[0]);
  const match = reg
    ? (wanted.find((w) => reg.langs.some((l) => String(l).split("-")[0] === w)) || reg.langs[0])
    : (wanted.find((l) => LANGS[l]) || "en");
  return { suggested: true, country: country || null, region: reg ? reg.region : null,
    language: LANGS[match] ? match : "en", timezone: (reg && reg.tz) || tz || "UTC",
    currency: (reg && reg.currency) || "INR", options: reg ? reg.langs : ["en"] };
}

