/* Fallback chain: exact locale, then base language, then English. A missing
   key returns readable English, never undefined or the raw key. */
function translate(key, lang = "en", vars = {}) {
  const base = (LANGS[lang] || {}).base || String(lang).split("-")[0];
  const chain = [lang, base, "en"];
  let raw;
  for (const c of chain) {
    if (CATALOGS[c] && CATALOGS[c][key] !== undefined) { raw = CATALOGS[c][key]; break; }
  }
  /* last resort: turn the key into something a human can still read */
  if (raw === undefined) raw = String(key).split(".").pop().replace(/([a-z])([A-Z])/g, "$1 $2").replace(/^./, (m) => m.toUpperCase());
  return interpolate(raw, vars);
}
/* Placeholders survive translation; an unknown one is left visible rather than
   printed as "undefined", so a broken string is obvious instead of silent. */
function interpolate(text, vars = {}) {
  return String(text).replace(/\{\{\s*(\w+)\s*\}\}/g, (m, name) =>
    vars[name] !== undefined && vars[name] !== null ? String(vars[name]) : m);
}
const makeTranslator = (lang) => (key, vars) => translate(key, lang, vars);

/* ---- catalog health, for the admin screen and CI ---- */
function catalogReport(lang) {
  const ref = Object.keys(CATALOGS.en);
  const has = CATALOGS[lang] || {};
  const missing = ref.filter((k) => has[k] === undefined);
  const extra = Object.keys(has).filter((k) => CATALOGS.en[k] === undefined);
  const placeholderIssues = [];
  ref.forEach((k) => {
    if (has[k] === undefined) return;
    const want = (String(CATALOGS.en[k]).match(/\{\{\s*\w+\s*\}\}/g) || []).map((x) => x.replace(/\s/g, "")).sort();
    const got = (String(has[k]).match(/\{\{\s*\w+\s*\}\}/g) || []).map((x) => x.replace(/\s/g, "")).sort();
    if (want.join() !== got.join()) placeholderIssues.push({ key: k, expected: want, found: got });
  });
  return { lang, total: ref.length, translated: ref.length - missing.length,
    percent: Math.round(((ref.length - missing.length) / ref.length) * 100),
    missing, extra, placeholderIssues };
}
const catalogCoverage = () => Object.keys(CATALOGS).map(catalogReport).sort((a, b) => b.percent - a.percent);

/* ---- who gets which language ----
   Staff see their own language; customers receive theirs. These are different
   questions and are answered separately. */
function resolveLanguage({ customer, agent, user, workspace, fallback = "en" } = {}, purpose = "ui") {
  const order = purpose === "customer"
    ? [customer, agent, workspace, user]     // outbound: the customer comes first
    : [user, workspace, fallback];           // interface: the person looking at it
  return order.find((l) => l && LANGS[l]) || fallback;
}

/* ---- detection ----
   Script ranges identify the writing system; an explicit request always wins.
   Language is never inferred from a name or a location. */
const SCRIPTS = [
  [/[\u0B80-\u0BFF]/, "ta"], [/[\u0900-\u097F]/, "hi"], [/[\u0D00-\u0D7F]/, "ml"],
  [/[\u0C00-\u0C7F]/, "te"], [/[\u0C80-\u0CFF]/, "kn"], [/[\u0980-\u09FF]/, "bn"],
  [/[\u0A80-\u0AFF]/, "gu"], [/[\u0A00-\u0A7F]/, "pa"], [/[\u0600-\u06FF]/, "ar"],
  [/[\u0590-\u05FF]/, "he"], [/[\u4E00-\u9FFF]/, "zh"], [/[\u3040-\u30FF]/, "ja"],
  [/[\uAC00-\uD7AF]/, "ko"], [/[\u0E00-\u0E7F]/, "th"], [/[\u0400-\u04FF]/, "ru"],
  [/[\u0370-\u03FF]/, "el"], [/[\u1200-\u137F]/, "am"],
];
const ASK_LANG = /\b(?:reply|respond|write|talk|speak|message)\s+(?:to\s+me\s+)?in\s+([a-z\u00c0-\u024f]+)/i;
const NAME_TO_CODE = Object.keys(LANGS).reduce((a, c) => { a[LANGS[c].name.toLowerCase()] = c; a[LANGS[c].native.toLowerCase()] = c; return a; }, { mandarin: "zh", chinese: "zh", tamil: "ta", hindi: "hi", malay: "ms", arabic: "ar", spanish: "es", french: "fr", german: "de" });

function detectLanguage(text) {
  const t = String(text || "");
  const asked = t.match(ASK_LANG);
  if (asked) {
    const code = NAME_TO_CODE[asked[1].toLowerCase()];
    /* an explicit request is a confirmed preference, not a guess */
    if (code) return { lang: code, confidence: "explicit", source: "asked" };
  }
  for (const [re, code] of SCRIPTS) if (re.test(t)) return { lang: code, confidence: "high", source: "script" };
  if (/^[\s\w\p{P}]+$/u.test(t) && t.trim()) return { lang: "en", confidence: "low", source: "latin script" };
  return { lang: null, confidence: "none", source: null };
}
/* Only an explicit request or a confident script match is stored. */
function rememberLanguage(contact, detection) {
  if (!detection || !["explicit", "high"].includes(detection.confidence)) return contact;
  if (contact && contact.languageLocked && detection.confidence !== "explicit") return contact;
  return { ...contact, preferredLanguage: detection.lang,
    languageLocked: detection.confidence === "explicit",
    languageSource: detection.source };
}

/* ---- formatting: locale decides shape, data stays structured ---- */
function fmtDateI18n(d, lang = "en", country) {
  const date = new Date(d);
  /* an unparseable date must never take a screen down */
  if (isNaN(date.getTime())) return String(d ?? "");
  try { return new Intl.DateTimeFormat(country ? `${lang}-${country}` : lang, { dateStyle: "medium" }).format(date); }
  catch { return date.toISOString().slice(0, 10); }
}
function fmtNumberI18n(n, lang = "en") {
  try { return new Intl.NumberFormat(lang).format(n); } catch { return String(n); }
}
/* Formatting is not conversion: the amount is shown in its own currency. */
function fmtMoneyI18n(amount, currency = "INR", lang = "en-IN") {
  try { return new Intl.NumberFormat(lang, { style: "currency", currency }).format(amount); }
  catch { return `₹${amount}`; }
}

/* ---- campaigns: one campaign, many languages ---- */
function localiseAudience(contacts, { defaultLang = "en", enabled = true } = {}) {
  if (!enabled) return [{ lang: defaultLang, contacts: contacts || [] }];
  const groups = {};
  (contacts || []).forEach((c) => {
    const l = (c.preferredLanguage && LANGS[c.preferredLanguage]) ? c.preferredLanguage : defaultLang;
    (groups[l] = groups[l] || []).push(c);
  });
  return Object.keys(groups).map((lang) => ({ lang, contacts: groups[lang] }));
}

