const makeT = (locale) => (key) => (STRINGS[locale] && STRINGS[locale][key]) || STRINGS.en[key] || key;
const localeDir = (locale) => (LOCALES[locale] || LOCALES.en).dir;
const fmtDateLocale = (d, locale) => new Date(d).toLocaleDateString(locale === "en" ? "en-GB" : locale, { day: "numeric", month: "short", year: "numeric" });
const fmtNumberLocale = (n, locale) => Number(n).toLocaleString(locale === "en" ? "en-GB" : locale);

/* ---- routing queues and shifts ---- */
const QUEUES_INIT = []; // TODO_BACKEND
const SHIFTS_INIT = []; // TODO_BACKEND
const DAY_NAMES = ["Sun", "Mon", "Tue", "Wed", "Thu", "Fri", "Sat"];
function onDuty(shifts, when = new Date()) {
  const day = DAY_NAMES[when.getDay()];
  const mins = when.getHours() * 60 + when.getMinutes();
  return shifts.filter((s2) => {
    if (!s2.days.includes(day)) return false;
    const [sh, sm] = s2.start.split(":").map(Number), [eh, em] = s2.end.split(":").map(Number);
    const st = sh * 60 + sm, en = eh * 60 + em;
    return en > st ? mins >= st && mins < en : mins >= st || mins < en; // handles overnight
  }).map((s2) => s2.user);
}
/* pick a queue by channel and intent, then a person who is actually working */
function routeToQueue(conversation, { queues, shifts, counts = {}, when = new Date() }) {
  const match = queues.find((q) =>
    (!q.channels.length || q.channels.includes(conversation.channel)) &&
    (!q.intents.length || q.intents.some((i) => (conversation.intent || "").toLowerCase().includes(i))));
  if (!match) return { queue: null, assignee: null, why: "No queue matches this channel and intent." };
  const duty = onDuty(shifts, when).filter((u) => match.members.includes(u));
  if (!duty.length) return { queue: match, assignee: null, offHours: true,
    why: `${match.name} has nobody on shift right now, so this waits or escalates to ${match.fallback}.` };
  const pick = match.strategy === "load"
    ? [...duty].sort((a, b) => (counts[a] || 0) - (counts[b] || 0))[0]
    : [...duty].sort((a, b) => (counts[a] || 0) - (counts[b] || 0) || a.localeCompare(b))[0];
  return { queue: match, assignee: pick, slaMinutes: match.slaMinutes,
    why: `${match.name} queue, ${pick} is on shift with ${counts[pick] || 0} open.` };
}
/* two people opening the same conversation is how customers get double replies */
function collisionOn(conversationId, viewers, me) {
  const others = (viewers[conversationId] || []).filter((v) => v.user !== me && Date.now() - v.at < 30000);
  return others.length ? { collision: true, who: others.map((o) => o.user), why: `${others.map((o) => o.user).join(" and ")} ${others.length > 1 ? "are" : "is"} also viewing this.` } : { collision: false };
}

/* ---- recurring appointments ---- */
const RECUR_FREQ = ["daily", "weekly", "monthly"];
function expandRecurrence(rule, { from = new Date(), limit = 25 } = {}) {
  if (!rule || !rule.freq) return [];
  const out = [];
  const start = new Date(rule.startsAt);
  const until = rule.until ? new Date(rule.until) : null;
  const count = rule.count || limit;
  let cursor = new Date(start), guard = 0;
  while (out.length < Math.min(count, limit) && guard++ < 500) {
    if (until && cursor > until) break;
    const day = DAY_NAMES[cursor.getDay()];
    const matchesDay = rule.freq !== "weekly" || !rule.byDay || rule.byDay.includes(day);
    if (cursor >= start && matchesDay && !(rule.skip || []).includes(cursor.toISOString().slice(0, 10))) out.push(new Date(cursor));
    if (rule.freq === "daily") cursor.setDate(cursor.getDate() + (rule.interval || 1));
    else if (rule.freq === "weekly") cursor.setDate(cursor.getDate() + 1);
    else if (rule.freq === "monthly") cursor.setMonth(cursor.getMonth() + (rule.interval || 1));
    else break;
  }
  return out;
}

/* ==================================================================== */
/* REVENUE OBJECTS: products, quotes, sequences, forecasting             */
/* A deal with a single number cannot be quoted, discounted or taxed.    */
/* These give money the structure a real sales process needs.            */
/* ==================================================================== */

const PRODUCT_KINDS = ["Subscription", "One off", "Service", "Usage"];
const BILLING_PERIODS = { once: { label: "one off", months: 0 }, monthly: { label: "a month", months: 1 }, quarterly: { label: "a quarter", months: 3 }, annual: { label: "a year", months: 12 } };

const PRODUCTS_INIT = []; // TODO_BACKEND

/* line item maths in minor units, so nothing rounds badly */
function lineTotal(item, product) {
  const p = product || {};
  const unit = item.unitPrice !== undefined && item.unitPrice !== null ? item.unitPrice : (p.price || 0);
  const qty = Math.max(0, item.qty || 0);
  const gross = unit * qty;
  const discount = item.discountPct ? Math.round(gross * (item.discountPct / 100)) : 0;
  const net = gross - discount;
  const taxRate = item.taxRate !== undefined ? item.taxRate : (p.taxRate || 0);
  const tax = Math.round(net * (taxRate / 100));
  const months = (BILLING_PERIODS[item.period || p.period || "once"] || {}).months || 0;
  return { unit, qty, gross, discount, net, tax, total: net + tax, months,
    cost: (p.cost || 0) * qty, margin: net - (p.cost || 0) * qty };
}
function quoteTotals(quote, products) {
  const lines = (quote.items || []).map((it) => ({ item: it, calc: lineTotal(it, products.find((p) => p.id === it.productId)) }));
  const sum = (f) => lines.reduce((a, l) => a + f(l.calc), 0);
  const net = sum((c) => c.net), tax = sum((c) => c.tax), cost = sum((c) => c.cost);
  /* recurring revenue is what a subscription business actually runs on */
  const mrr = lines.reduce((a, l) => a + (l.calc.months ? Math.round(l.calc.net / l.calc.months) : 0), 0);
  const oneOff = lines.reduce((a, l) => a + (l.calc.months ? 0 : l.calc.net), 0);
  return { lines, gross: sum((c) => c.gross), discount: sum((c) => c.discount), net, tax, total: net + tax,
    cost, margin: net - cost, marginPct: net ? Math.round(((net - cost) / net) * 100) : null,
    mrr, arr: mrr * 12, oneOff, itemCount: lines.length };
}
const QUOTE_STATUS = ["Draft", "Sent", "Viewed", "Accepted", "Declined", "Expired"];
const QUOTE_TINT = { Draft: "bg-zinc-100 text-zinc-600 border-zinc-200", Sent: "bg-sky-50 text-sky-700 border-sky-200",
  Viewed: "bg-violet-50 text-violet-700 border-violet-200", Accepted: "bg-emerald-50 text-emerald-700 border-emerald-200",
  Declined: "bg-red-50 text-red-700 border-red-200", Expired: "bg-zinc-100 text-zinc-400 border-zinc-200" };

/* a quote cannot be sent if it breaks pricing policy; the discount ceiling is real */
function validateQuote(quote, products, { maxDiscountPct = 10, minMarginPct = 20 } = {}) {
  const t = quoteTotals(quote, products);
  const errs = [], warns = [];
  if (!quote.contactId) errs.push("Attach the quote to a contact.");
  if (!t.itemCount) errs.push("Add at least one line item.");
  t.lines.forEach((l) => {
    if ((l.item.discountPct || 0) > maxDiscountPct)
      errs.push(`${(products.find((p) => p.id === l.item.productId) || {}).name || "A line"} is discounted ${l.item.discountPct}%, above the ${maxDiscountPct}% ceiling. This needs approval.`);
    if (l.calc.qty <= 0) errs.push("Every line needs a quantity above zero.");
  });
  if (t.marginPct !== null && t.marginPct < minMarginPct) warns.push(`Margin is ${t.marginPct}%, below the ${minMarginPct}% target.`);
  if (quote.expiresAt && new Date(quote.expiresAt) < new Date()) warns.push("The expiry date is in the past.");
  return { errs, warns, ok: errs.length === 0, totals: t };
}

