/* which step is due for an enrolled contact, and why it might have stopped */
function sequenceDue(enrollment, seq, { now = Date.now() } = {}) {
  if (!seq || !enrollment) return { due: null, reason: "not enrolled" };
  if (enrollment.status !== "active") return { due: null, reason: enrollment.status };
  const elapsedDays = Math.floor((now - new Date(enrollment.startedAt).getTime()) / 86400000);
  const next = seq.steps.find((st) => !(enrollment.done || []).includes(st.id));
  if (!next) return { due: null, reason: "completed" };
  if (next.day > elapsedDays) return { due: null, reason: `step ${next.id} is due on day ${next.day}, it is day ${elapsedDays}`, next, waitDays: next.day - elapsedDays };
  return { due: next, reason: `day ${next.day} step is due`, elapsedDays };
}
const seqStop = (enrollment, why) => ({ ...enrollment, status: "stopped", stoppedWhy: why, stoppedAt: new Date().toISOString() });

/* ---- forecasting and assignment ---- */
function forecastPipeline(deals, { quotas = {}, stageWeights = null } = {}) {
  const open = deals.filter((d) => !["Won", "Lost"].includes(d.stage));
  const won = deals.filter((d) => d.stage === "Won");
  const weightOf = (d) => stageWeights && stageWeights[d.stage] !== undefined ? stageWeights[d.stage] / 100 : (d.prob ?? 50) / 100;
  const byOwner = {};
  const add = (owner, key, v) => { byOwner[owner] = byOwner[owner] || { owner, closed: 0, weighted: 0, open: 0, count: 0 }; byOwner[owner][key] += v; };
  won.forEach((d) => add(d.owner || "Unassigned", "closed", d.value));
  open.forEach((d) => { add(d.owner || "Unassigned", "weighted", Math.round(d.value * weightOf(d))); add(d.owner || "Unassigned", "open", d.value); add(d.owner || "Unassigned", "count", 1); });
  const rows = Object.values(byOwner).map((r) => {
    const quota = quotas[r.owner] || 0;
    const projected = r.closed + r.weighted;
    return { ...r, quota, projected, attainment: quota ? Math.round((projected / quota) * 100) : null, gap: quota ? quota - projected : null };
  }).sort((a, b) => b.projected - a.projected);
  return { rows, closed: won.reduce((a, d) => a + d.value, 0),
    weighted: open.reduce((a, d) => a + Math.round(d.value * weightOf(d)), 0),
    openTotal: open.reduce((a, d) => a + d.value, 0), openCount: open.length,
    bestCase: won.reduce((a, d) => a + d.value, 0) + open.reduce((a, d) => a + d.value, 0) };
}
/* fair distribution instead of everything landing on whoever is fastest */
function assignOwner(rule, { team = [], counts = {}, contact = null }) {
  const eligible = team.filter((u) => u !== "Unassigned");
  if (!eligible.length) return { owner: "Unassigned", why: "No one is available to assign to." };
  if (rule.mode === "round_robin") {
    const sorted = [...eligible].sort((a, b) => (counts[a] || 0) - (counts[b] || 0) || a.localeCompare(b));
    return { owner: sorted[0], why: `Round robin: ${sorted[0]} has the fewest open (${counts[sorted[0]] || 0}).` };
  }
  if (rule.mode === "territory" && contact) {
    const match = (rule.territories || []).find((t) => (t.match || []).some((m) => (contact.location || "").toLowerCase().includes(m.toLowerCase())));
    if (match) return { owner: match.owner, why: `${contact.location} falls in ${match.owner}'s territory.` };
    return { owner: eligible[0], why: `No territory matched ${contact.location || "an unknown location"}, so it went to the default owner.` };
  }
  if (rule.mode === "load" ) {
    const sorted = [...eligible].sort((a, b) => (counts[a] || 0) - (counts[b] || 0));
    return { owner: sorted[0], why: `Lightest workload: ${counts[sorted[0]] || 0} open records.` };
  }
  return { owner: rule.owner || eligible[0], why: "Fixed assignment rule." };
}

