function validateSubmission(form, values) {
  const errs = {};
  (form.fields || []).forEach((f) => {
    const v = (values[f.id] || "").trim();
    if (f.required && !v) errs[f.id] = `${f.label} is required.`;
    else if (v && f.kind === "email" && !/^[^@\s]+@[^@\s]+\.[^@\s]+$/.test(v)) errs[f.id] = "That does not look like an email address.";
    else if (v && f.kind === "phone" && normPhone(v).length < 7) errs[f.id] = "That phone number looks too short.";
  });
  return { ok: Object.keys(errs).length === 0, errs };
}
