/* AGENT LIBRARY                                                         */
/* A template is a complete package: identity, permissions, guardrails,  */
/* escalation, channels, knowledge and real workflow graphs. Deployment  */
/* is transactional and rolls back cleanly if any part fails.            */
/* ==================================================================== */

const LIB_CATEGORIES = ["Recommended", "Reception", "Sales", "Support", "Appointments", "Lead qualification", "Follow up", "Marketing", "Operations", "Finance"];
const LIB_INDUSTRIES = ["Healthcare", "Real estate", "Retail", "Hospitality", "Professional services", "Education", "Automotive", "Any industry"];

/* helper: build a workflow graph for a template so deployment produces real automation */
const tplFlow = (id, name, trigger, steps) => {
  const nodes = [{ id: "t1", type: "trigger", x: 320, y: 40, label: trigger }];
  const edges = [];
  let prev = "t1", y = 170;
  steps.forEach((st, i) => {
    const nid = "n" + (i + 1);
    nodes.push({ id: nid, x: 320, y, ...st });
    edges.push({ id: "e" + i, from: prev, h: st.fromHandle || "out", to: nid });
    prev = nid; y += 130;
  });
  nodes.push({ id: "end", type: "end", x: 320, y, label: "Done", endState: "Completed" });
  edges.push({ id: "eEnd", from: prev, h: "out", to: "end" });
  return { id, name, nodes, edges, status: "Draft", active: false, version: 1, runs: 0, runsLog: [], versions: [] };
};

