/* AI AGENTS                                                           */
/* ------------------------------------------------------------------ */


const HEALTH_TINT = { Ready: "bg-emerald-50 text-emerald-700 border-emerald-200", Warning: "bg-amber-50 text-amber-700 border-amber-200", "Action required": "bg-red-50 text-red-700 border-red-200" };
const AG_STATUS_TINT = { Active: "bg-emerald-50 text-emerald-700 border-emerald-200", Paused: "bg-amber-50 text-amber-700 border-amber-200", Draft: "bg-zinc-100 text-zinc-600 border-zinc-200", Archived: "bg-zinc-100 text-zinc-400 border-zinc-200" };

function AgentsView() {
  const { T, dk, selAgent, setSelAgent, agents, agentEdit, setAgentEdit, autonomy, setConfirm, setAgents, flash, log, convs, calls, appts, deals, tasks } = useApp();
  const [q, setQ] = useState(""); const [sf, setSf] = useState(""); const [sel, setSel] = useState([]);
  const [compare, setCompare] = useState(false);
  if (agentEdit) return <AgentBuilder />;
  if (selAgent) return <AgentDetail id={selAgent} />;

  /* every metric below is counted from real platform records */
  const statsFor = (a) => ({
    convs: convs.filter((v) => v.agent === agentFullName(a) || v.agent === a.name).length,
    calls: calls.filter((k) => (k.agent || "").startsWith(a.name)).length,
    appts: appts.filter((x) => x.source === "Chat AI" || x.source === "Voice AI").length && a.type === "appointment" ? appts.filter((x) => ["Chat AI", "Voice AI"].includes(x.source)).length : 0,
    deals: a.type === "sales" ? deals.length : 0,
    tasks: tasks.filter((t) => t.ai).length && ["followup", "support"].includes(a.type) ? tasks.filter((t) => t.ai).length : 0,
    acts: (a.activity || []).length,
  });
  const list = agents.filter((a) => (!sf || a.status === sf) && (!q.trim() || (a.name + " " + a.title + " " + a.role).toLowerCase().includes(q.toLowerCase())));

  return (
    <div className="h-full flex flex-col min-h-0">
      <div className={`shrink-0 px-6 pt-5 border-b ${T.border} ${T.panel}`}>
        <div className="flex items-start gap-3 flex-wrap">
          <div>
            <h1 className="text-xl font-semibold bz-display tracking-tight">Your AI workforce</h1>
            <p className={`text-[13px] mt-1 max-w-xl ${T.sub}`}>Create, govern and monitor the digital employees that run your business. Workspace autonomy ceiling is Level {autonomy}.</p>
          </div>
          <div className="flex-1" />
          <button onClick={() => setCompare(!compare)} className={`h-9 px-3 rounded-xl border text-xs font-semibold ${T.chip} ${T.hover}`}>{compare ? "Roster" : "Compare"}</button>
          <button onClick={() => setAgentEdit("new")} className="h-9 px-3.5 rounded-xl text-xs font-semibold text-white inline-flex items-center gap-1.5" style={{ background: BRAND }}><Plus size={13} /> Create agent</button>
        </div>
        <div className="flex items-center gap-2 py-3 flex-wrap">
          <div className={`h-9 flex items-center gap-2 px-3 rounded-xl flex-1 max-w-xs ${T.input}`}>
            <Search size={13} className={T.faint} /><input value={q} onChange={(e) => setQ(e.target.value)} placeholder="Search your team…" className="flex-1 bg-transparent text-xs outline-none" />
          </div>
          <select value={sf} onChange={(e) => setSf(e.target.value)} className={`h-8 px-2.5 rounded-lg text-[11px] outline-none ${T.input}`}><option value="">Any status</option>{AGENT_STATUS.map((x) => <option key={x}>{x}</option>)}</select>
          {sel.length > 0 && (<>
            <span className="text-[11px] font-semibold">{sel.length} selected</span>
            <button onClick={() => setConfirm({ text: `Pause ${sel.length} agents?`, detail: "Their conversations wait for a human until you reactivate them.", yes: "Pause", onYes: () => { setAgents((ag) => ag.map((a) => sel.includes(a.id) ? { ...a, status: "Paused" } : a)); log("You", "Agents paused", sel.length + " agents"); flash(sel.length + " agents paused"); setSel([]); } })}
              className={`h-8 px-2.5 rounded-lg border text-[11px] font-medium ${T.chip}`}>Pause</button>
            <button onClick={() => { setAgents((ag) => ag.map((a) => sel.includes(a.id) ? { ...a, status: "Active" } : a)); flash(sel.length + " activated"); setSel([]); }} className={`h-8 px-2.5 rounded-lg border text-[11px] font-medium ${T.chip}`}>Activate</button>
            <button onClick={() => setConfirm({ text: `Archive ${sel.length} agents?`, detail: "Their past conversations, calls and activity stay linked to them for the record.", yes: "Archive", onYes: () => { setAgents((ag) => ag.map((a) => sel.includes(a.id) ? { ...a, status: "Archived" } : a)); flash("Archived"); setSel([]); } })}
              className={`h-8 px-2.5 rounded-lg border text-[11px] font-medium ${T.chip}`}>Archive</button>
          </>)}
        </div>
      </div>

      <div className="flex-1 overflow-y-auto bz-scroll p-6">
        {compare ? (
          <div className={`rounded-2xl overflow-x-auto ${T.card}`}>
            <table className="w-full text-xs">
              <thead><tr className={`${T.faint} border-b ${T.border}`}>
                <th className="px-4 h-9 text-left font-semibold uppercase tracking-wider text-[10px]">Capability</th>
                {agents.filter((a) => a.status !== "Archived").map((a) => <th key={a.id} className="px-3 h-9 text-center font-semibold">{a.name}</th>)}
              </tr></thead>
              <tbody className={`divide-y ${T.divide}`}>
                {["Autonomy", "Channels", "Health", ...Object.keys(ACTIONS)].map((row) => (
                  <tr key={row}>
                    <td className={`px-4 py-2 ${["Autonomy", "Channels", "Health"].includes(row) ? "font-semibold" : T.sub}`}>{ACTIONS[row] ? ACTIONS[row].label : row}</td>
                    {agents.filter((a) => a.status !== "Archived").map((a) => {
                      if (row === "Autonomy") return <td key={a.id} className="px-3 text-center font-semibold">L{Math.min(a.autonomy, autonomy)}</td>;
                      if (row === "Channels") return <td key={a.id} className="px-3 text-center"><div className="flex justify-center gap-0.5">{(a.channels || []).slice(0, 4).map((c) => <Brand key={c} id={c === "email" ? "gmail" : c === "webchat" ? "google" : c} size={11} />)}</div></td>;
                      if (row === "Health") { const h = agentHealth(a, autonomy); return <td key={a.id} className="px-3 text-center"><span className={`inline-block w-2 h-2 rounded-full ${h.level === "Ready" ? "bg-emerald-500" : h.level === "Warning" ? "bg-amber-500" : "bg-red-500"}`} /></td>; }
                      const r = canAgentDo(a, row, { ceiling: autonomy });
                      return <td key={a.id} className="px-3 text-center" title={r.why}>{r.ok ? <Check size={13} className="text-emerald-500 inline" /> : <X size={12} className={`inline ${T.faint}`} />}</td>;
                    })}
                  </tr>
                ))}
              </tbody>
            </table>
            <p className={`text-[10px] p-3 ${T.faint}`}>A tick means the agent genuinely passes the permission, tool, autonomy and ceiling checks for that action right now. Hover for the reason behind a cross.</p>
          </div>
        ) : (
          <div className="grid grid-cols-1 md:grid-cols-2 xl:grid-cols-3 gap-3">
            {list.map((a) => {
              const h = agentHealth(a, autonomy);
              const st = statsFor(a);
              return (
                <div key={a.id} className={`rounded-2xl p-4 ${T.card} group ${a.status === "Archived" ? "opacity-60" : ""}`}>
                  <div className="flex items-start gap-2.5">
                    <button onClick={() => setSel(sel.includes(a.id) ? sel.filter((x) => x !== a.id) : [...sel, a.id])} className="mt-1">
                      {sel.includes(a.id) ? <CheckCircle2 size={14} style={{ color: BRAND }} /> : <Circle size={13} className={T.faint} />}
                    </button>
                    <div className="w-9 h-9 rounded-xl grid place-items-center text-white shrink-0" style={{ background: a.status === "Active" ? BRAND : "#a1a1aa" }}><Bot size={16} /></div>
                    <div className="flex-1 min-w-0">
                      <button onClick={() => setSelAgent(a.id)} className="text-sm font-semibold hover:underline underline-offset-2 text-left">{a.name}</button>
                      <div className={`text-[11px] ${T.faint}`}>{a.title}</div>
                    </div>
                    <div className="flex flex-col items-end gap-1">
                      <Pill c={AG_STATUS_TINT[a.status]}>{a.status}</Pill>
                      <span className={`text-[10px] font-semibold ${T.faint}`}>Level {Math.min(a.autonomy, autonomy)}</span>
                    </div>
                  </div>
                  <p className={`text-[11px] mt-2.5 leading-relaxed line-clamp-2 ${T.sub}`}>{a.purpose || a.role}</p>
                  <div className="flex items-center gap-1 mt-2.5">
                    {(a.channels || []).map((c) => <Brand key={c} id={c === "email" ? "gmail" : c === "webchat" ? "google" : c} size={13} />)}
                    <span className={`text-[10px] ml-1 ${T.faint}`}>{(a.tools || []).length} tools · {Object.values(a.perms || {}).filter(Boolean).length} permissions</span>
                  </div>
                  <div className={`grid grid-cols-3 gap-2 mt-3 pt-3 border-t text-center ${T.border}`}>
                    {[["Conversations", st.convs], ["Calls", st.calls], ["Actions", st.acts]].map(([k, v]) => (
                      <div key={k}><div className="text-[13px] font-semibold bz-display tabular-nums">{v}</div><div className={`text-[9px] ${T.faint}`}>{k}</div></div>
                    ))}
                  </div>
                  <div className="flex items-center gap-1.5 mt-3">
                    <Pill c={HEALTH_TINT[h.level]}>{h.level}</Pill>
                    <div className="flex-1" />
                    <div className="flex gap-1 opacity-0 group-hover:opacity-100 transition-opacity">
                      <button title="Edit" onClick={() => setAgentEdit(a.id)} className={`p-1.5 rounded-lg ${T.hover}`}><Pencil size={12} /></button>
                      <button title="Duplicate" onClick={() => { const c = JSON.parse(JSON.stringify(a)); c.id = "a" + Date.now(); c.name = a.name + " copy"; c.status = "Paused"; c.activity = []; c.versions = []; setAgents((ag) => [...ag, c]); log("You", "Agent duplicated", c.name); flash("Duplicated as a paused draft so it cannot act by accident"); }} className={`p-1.5 rounded-lg ${T.hover}`}><Layers size={12} /></button>
                      <button title="Archive" onClick={() => setConfirm({ text: "Archive " + a.name + "?", detail: "Past conversations, calls and activity stay attached to this agent so history stays readable.", yes: "Archive", onYes: () => { setAgents((ag) => ag.map((x) => x.id === a.id ? { ...x, status: "Archived" } : x)); log("You", "Agent archived", a.name); flash("Archived"); } })} className={`p-1.5 rounded-lg ${T.hover}`}><X size={12} /></button>
                    </div>
                  </div>
                </div>
              );
            })}
          </div>
        )}
      </div>
    </div>
  );
}

const AUTONOMY_LEVELS = [
  { l: 0, name: "Suggest only", d: "Analyzes, drafts and recommends. Sends nothing and executes nothing." },
  { l: 1, name: "Approval required", d: "Prepares messages and actions; a human approves before anything happens." },
  { l: 2, name: "Low risk automation", d: "Replies to basic questions, tags contacts, adds notes and creates tasks on its own." },
  { l: 3, name: "Business operations", d: "Books appointments, updates the CRM, qualifies leads, starts workflows and sends approved communications." },
  { l: 4, name: "Full agentic operations", d: "Creates deals, places calls, launches campaigns and issues payment links where explicitly permitted. Destructive actions still wait for a human." },
];

/* ---------- sandbox with real action simulation ---------- */
function TestChat({ agent, onClose }) {
  const { T, dk, autonomy, groundedAnswer } = useApp();
  const [msgs, setMsgs] = useState([{ from: "sys", text: `Sandbox for ${agent.name}. Real prompt, real permissions, real autonomy. Nothing here touches customers or your data.` }]);
  const [txt, setTxt] = useState("");
  const [busy, setBusy] = useState(false);
  const endRef = useRef(null);
  useEffect(() => { endRef.current && endRef.current.scrollIntoView({ behavior: "smooth" }); }, [msgs]);

  const SCENARIOS = [
    ["Normal question", "What are your opening hours?"],
    ["Pricing", "How much does the enterprise plan cost?"],
    ["Booking", "Book me tomorrow at 3."],
    ["Guardrail", "Give me a 30% discount."],
    ["Refund", "I want a refund, this is unacceptable."],
    ["Asks for a human", "Just put me through to a real person."],
    ["Out of scope", "What do you think about the election?"],
  ];

  const respond = (q) => {
    const out = [];
    const esc = escalationCheck(agent, q);
    /* what would this agent try to do? */
    let action = null, draft = "";
    if (/book|appointment|tomorrow at|slot/i.test(q)) { action = "CAN_BOOK_APPOINTMENT"; draft = "I have Thursday 11:00 or Friday 15:00 open. Shall I hold one for you?"; }
    else if (/price|cost|quote|plan/i.test(q)) {
      const g = groundedAnswer(q, agent);
      action = "CAN_SEND_WHATSAPP"; draft = g.text;
      if (g.cite) out.push({ from: "cite", text: `Answered from ${g.cite.source}${g.cite.heading ? " · " + g.cite.heading : ""}`, stale: g.cite.fresh !== "Fresh" });
      else out.push({ from: "cite", fallback: true, text: `${agent.name} has no approved pricing source, so it declined instead of inventing a number.` });
    }
    else if (/discount|off\b|cheaper/i.test(q)) { action = "CAN_SEND_WHATSAPP"; draft = "I can do 30% off if that helps close this today."; }
    else if (/refund|money back/i.test(q)) { action = "CAN_ISSUE_REFUND"; draft = "I have started the refund; you will see it in 3 to 5 business days."; }
    else if (/deal|purchase|buy|order/i.test(q)) { action = "CAN_CREATE_DEAL"; draft = "Great, I will set this up as an opportunity and send the paperwork."; }
    else if (/human|real person|manager/i.test(q)) { action = null; draft = "Of course, connecting you to a teammate now with the full context."; }
    else if (/election|politic|weather|joke/i.test(q)) { action = null; draft = "That is outside what I can help with, but I am happy with anything about your account or our services."; }
    else {
      const g = groundedAnswer(q, agent);
      action = "CAN_SEND_WHATSAPP";
      draft = g.text;
      if (g.cite) out.push({ from: "cite", text: `Answered from ${g.cite.source}${g.cite.heading ? " · " + g.cite.heading : ""}${g.cite.page ? " · page " + g.cite.page : ""}`, stale: g.cite.fresh !== "Fresh" });
      else out.push({ from: "cite", fallback: true, text: `No approved source covered that, so ${agent.name} declined rather than guessing. It is now logged as a knowledge gap.` });
    }

    /* guardrails run on the draft before anything else */
    const broke = guardrailCheck(agent, draft);
    if (broke.length) {
      out.push({ from: "guard", text: `Guardrail triggered: “${broke[0].rule}”. The draft ${broke[0].why}, so it was blocked and rewritten.` });
      draft = /discount/i.test(draft) ? "I cannot authorize a discount above 10%, but I can apply 10% today and ask my manager about anything beyond that." : "Let me get that confirmed by a colleague before I put it in writing.";
    }
    out.push({ from: "ai", text: draft });

    if (action) {
      const r = canAgentDo(agent, action, { ceiling: autonomy });
      out.push({ from: "action", label: ACTIONS[action].label, risk: ACTIONS[action].risk, ok: r.ok, needsApproval: !!r.needsApproval, why: r.why });
    }
    if (esc.length) out.push({ from: "esc", text: `${esc.join(" and ")}. Handing to ${(agent.escalation || {}).who || "your team"} with ${((agent.escalation || {}).include || ["the transcript"]).join(", ").toLowerCase()}.` });
    return out;
  };

  const send = (preset) => {
    const q = (preset || txt).trim();
    if (!q || busy) return;
    setTxt(""); setMsgs((m) => [...m, { from: "you", text: q }]); setBusy(true);
    setTimeout(() => { setMsgs((m) => [...m, ...respond(q)]); setBusy(false); }, 600);
  };

  return (
    <Modal title={`Sandbox · ${agent.name}`} onClose={onClose} wide>
      <div className="flex flex-wrap gap-1.5 mb-3">
        {SCENARIOS.map(([l, q]) => <button key={l} onClick={() => send(q)} className={`h-7 px-2.5 rounded-full border text-[10px] font-medium ${T.chip} ${T.hover}`}>{l}</button>)}
      </div>
      <div className={`h-80 overflow-y-auto bz-scroll rounded-xl p-3 space-y-2 ${T.softcard}`}>
        {msgs.map((m, i) => {
          if (m.from === "sys") return <div key={i} className={`text-center text-[10px] ${T.faint}`}>{m.text}</div>;
          if (m.from === "guard") return <div key={i} className="rounded-xl border border-amber-200 bg-amber-50 text-amber-800 p-2.5 text-[11px] flex gap-2"><Shield size={13} className="shrink-0 mt-0.5" /> {m.text}</div>;
          if (m.from === "esc") return <div key={i} className="rounded-xl border border-sky-200 bg-sky-50 text-sky-800 p-2.5 text-[11px] flex gap-2"><Users size={13} className="shrink-0 mt-0.5" /> {m.text}</div>;
          if (m.from === "cite") return <div key={i} className={`rounded-xl border p-2.5 text-[11px] flex gap-2 ${m.fallback ? "border-amber-200 text-amber-700" : T.border + " " + T.sub}`}><FileText size={12} className="shrink-0 mt-0.5" /> {m.text}{m.stale ? " · this source is overdue for a refresh" : ""}</div>;
          if (m.from === "action") return (
            <div key={i} className={`rounded-xl border p-2.5 text-[11px] ${m.ok ? "border-emerald-200" : "border-red-200"} ${dk ? "" : "bg-white"}`}>
              <div className="flex items-center gap-2">
                <Zap size={12} className={m.ok ? "text-emerald-600" : "text-red-500"} />
                <span className="font-semibold">Action · {m.label}</span>
                <Pill c={RISK_TINT[m.risk]}>{m.risk}</Pill>
                <span className={`ml-auto font-semibold ${m.ok ? "text-emerald-600" : m.needsApproval ? "text-amber-600" : "text-red-500"}`}>{m.ok ? "Allowed" : m.needsApproval ? "Approval required" : "Blocked"}</span>
              </div>
              <p className={`mt-1 ${T.sub}`}>{m.why}</p>
              {!m.ok && <p className={`mt-0.5 text-[10px] ${T.faint}`}>In production this would stop here, so nothing was executed.</p>}
            </div>
          );
          return (
            <div key={i} className={`flex ${m.from === "you" ? "justify-end" : "justify-start"}`}>
              <div className={`max-w-[78%] px-3 py-2 rounded-2xl text-[11px] leading-relaxed ${m.from === "you" ? "text-white" : dk ? "bg-zinc-800" : "bg-white border border-zinc-100"}`} style={m.from === "you" ? { background: "#18181b" } : {}}>{m.text}</div>
            </div>
          );
        })}
        {busy && <div className={`text-[10px] ${T.faint}`}>{agent.name} is thinking…</div>}
        <div ref={endRef} />
      </div>
      <div className="flex gap-2 mt-3">
        <input value={txt} onChange={(e) => setTxt(e.target.value)} onKeyDown={(e) => e.key === "Enter" && send()} placeholder="Talk to the agent as a customer…" className={inputCls(T)} />
        <button onClick={() => send()} className="px-3.5 rounded-xl text-white" style={{ background: BRAND }}><Send size={13} /></button>
      </div>
      <p className={`text-[10px] mt-2 ${T.faint}`}>Every action the agent attempts is checked against its real permissions, tools, channels and the Level {autonomy} workspace ceiling, then shown above with the reason.</p>
    </Modal>
  );
}

/* ---------- agent builder: sectioned, simple + advanced ---------- */
function AgentBuilder() {
  const { T, dk, agents, setAgents, agentEdit, setAgentEdit, setSelAgent, autonomy, flash, log, kb, trail, gate } = useApp();
  const editing = agentEdit !== "new" ? agents.find((a) => a.id === agentEdit) : null;
  const blank = {
    id: "a" + Date.now(), name: "", title: "", type: "custom", status: "Draft", autonomy: 1, allowDestructive: false,
    role: "", purpose: "", dept: "", tone: "Professional", tones: ["Professional"], langs: ["English"], channels: [],
    goals: [], tools: ["CRM"], perms: permsFor(["CAN_READ_CRM"]), rules: [], knowledge: [], memory: ["Current conversation"],
    escalation: { when: ["Customer asks for a human"], who: "Jordan Lee", include: ["Transcript", "AI summary", "CRM record", "Reason"] },
    instr: { objective: "", responsibilities: "", dos: "", donts: "", success: "" },
    conv: 0, res: 0, esc: 0, cvr: 0, csat: 0, rt: "—", versions: [], activity: [], created: new Date().toISOString().slice(0, 10),
  };
  const [f, setF] = useState(editing ? JSON.parse(JSON.stringify({ ...blank, ...editing, instr: editing.instr || blank.instr })) : blank);
  const [sec, setSec] = useState("Identity");
  const [advanced, setAdvanced] = useState(false);
  const [testing, setTesting] = useState(false);
  const [goalIn, setGoalIn] = useState(""); const [ruleIn, setRuleIn] = useState("");
  const set = (k, v) => setF((x) => ({ ...x, [k]: v }));
  const health = agentHealth(f, autonomy);

  const compiled = `You are ${f.name || "an assistant"}, the ${f.title || f.type} for this business.
PURPOSE: ${f.purpose || f.role}
RESPONSIBILITIES: ${f.instr.responsibilities || f.role}
TONE: ${(f.tones || []).join(", ")}. ${f.instr.dos ? "ALWAYS: " + f.instr.dos : ""}
${f.instr.donts ? "NEVER: " + f.instr.donts : ""}
RULES: ${(f.rules || []).join(" | ") || "none set"}
ESCALATE WHEN: ${((f.escalation || {}).when || []).join(", ") || "never"} → ${(f.escalation || {}).who || "the team"}
LANGUAGES: ${(f.langs || []).join(", ")}. Reply in the customer's language when you can.
SUCCESS: ${f.instr.success || (f.goals || []).join(", ") || "resolve the request"}`;

  const save = (activate) => {
    if (!editing && !gate("agents", agents.filter((a) => a.status !== "Archived").length).ok) return;
    if (activate && health.level === "Action required") { flash(health.issues.find((i) => i.lvl === "error").t, "err"); setSec(health.issues[0].t.includes("channel") ? "Channels" : health.issues[0].t.includes("tool") ? "Tools" : health.issues[0].t.includes("permission") ? "Permissions" : "Identity"); return; }
    if (f.autonomy > autonomy) { flash(`Your workspace allows a maximum autonomy of Level ${autonomy}. Raise the ceiling in Settings first.`, "err"); setSec("Autonomy"); return; }
    const rec = { ...f, status: activate ? "Active" : (editing ? f.status : "Draft") };
    if (editing) {
      const version = { id: Date.now(), at: new Date().toLocaleString([], { month: "short", day: "numeric", hour: "2-digit", minute: "2-digit" }), who: "Jordan Lee",
        snap: { autonomy: editing.autonomy, tools: editing.tools, perms: editing.perms, rules: editing.rules, channels: editing.channels, role: editing.role } };
      rec.versions = [version, ...(editing.versions || [])].slice(0, 10);
      setAgents((ag) => ag.map((a) => a.id === editing.id ? rec : a));
      trail("Agent updated", f.name, "L" + editing.autonomy + " · " + (editing.tools || []).length + " tools", "L" + f.autonomy + " · " + f.tools.length + " tools");
      log("You", activate ? "Agent activated" : "Agent updated", f.name);
      flash(activate ? f.name + " is live" : "Saved");
      setAgentEdit(null); setSelAgent(editing.id);
    } else {
      setAgents((ag) => [...ag, rec]);
      trail("Agent created", f.name, "", rec.status);
      log("You", activate ? "Agent created and activated" : "Agent saved as draft", f.name);
      flash(activate ? f.name + " is live" : "Saved as a draft so it cannot act yet");
      setAgentEdit(null); setSelAgent(rec.id);
    }
  };

  const SECTIONS = ["Identity", "Role", "Personality", "Knowledge", "Tools", "Permissions", "Autonomy", "Guardrails", "Escalation", "Channels", "Review"];
  const chipRow = (items, selected, onToggle, dark) => (
    <div className="flex flex-wrap gap-1.5">
      {items.map((it) => {
        const val = typeof it === "string" ? it : it.id;
        const label = typeof it === "string" ? it : it.name;
        const on = selected.includes(val);
        return <button key={val} onClick={() => onToggle(val, on)} className={`h-8 px-3 rounded-full border text-[11px] font-medium ${on ? "text-white border-transparent" : `${T.chip} ${T.hover}`}`} style={on ? { background: dark ? "#18181b" : BRAND } : {}}>{label}</button>;
      })}
    </div>
  );
  const listEditor = (key, items, input, setInput, ph, Icon2, cls) => (
    <div>
      <div className="space-y-1.5 mb-2">
        {items.map((g, i) => (
          <div key={i} className={`flex items-center gap-2 px-3 py-2 rounded-xl text-xs ${T.softcard}`}>
            <Icon2 size={12} className={cls} /><span className="flex-1">{g}</span>
            <button onClick={() => set(key, items.filter((_, j) => j !== i))} className={T.faint}><X size={12} /></button>
          </div>
        ))}
      </div>
      <div className="flex gap-2">
        <input value={input} onChange={(e) => setInput(e.target.value)} onKeyDown={(e) => { if (e.key === "Enter" && input.trim()) { set(key, [...items, input.trim()]); setInput(""); } }} placeholder={ph} className={inputCls(T)} />
        <button onClick={() => { if (input.trim()) { set(key, [...items, input.trim()]); setInput(""); } }} className={`px-3 rounded-xl border text-xs font-semibold ${T.chip} ${T.hover}`}>Add</button>
      </div>
    </div>
  );

  return (
    <div className="h-full flex flex-col min-h-0">
      <div className={`h-14 shrink-0 flex items-center gap-3 px-4 border-b ${T.border} ${T.panel}`}>
        <button onClick={() => setAgentEdit(null)} className={`p-2 rounded-full ${T.hover}`}><ArrowLeft size={15} /></button>
        <input value={f.name} onChange={(e) => set("name", e.target.value)} placeholder="Agent name" className={`px-3 py-1.5 rounded-xl text-sm font-semibold outline-none w-44 ${T.input}`} />
        <input value={f.title} onChange={(e) => set("title", e.target.value)} placeholder="Job title" className={`px-3 py-1.5 rounded-xl text-xs outline-none w-40 ${T.input}`} />
        <Pill c={HEALTH_TINT[health.level]}>{health.level}</Pill>
        <div className="flex-1" />
        <button onClick={() => setAdvanced(!advanced)} className={`h-9 px-3 rounded-xl border text-xs font-semibold ${T.chip} ${T.hover}`}>{advanced ? "Simple mode" : "Advanced"}</button>
        <button onClick={() => f.name.trim() ? setTesting(true) : flash("Name the agent first", "err")} className={`h-9 px-3 rounded-xl border text-xs font-semibold inline-flex items-center gap-1.5 ${T.chip} ${T.hover}`}><PlayCircle size={13} /> Test</button>
        <button onClick={() => save(false)} className={`h-9 px-3 rounded-xl border text-xs font-semibold ${T.chip} ${T.hover}`}>Save draft</button>
        <button onClick={() => save(true)} className="h-9 px-4 rounded-xl text-xs font-semibold text-white" style={{ background: BRAND }}>Activate</button>
      </div>

      <div className="flex-1 flex min-h-0">
        <div className={`w-52 shrink-0 border-r ${T.border} ${T.panel} p-3 overflow-y-auto bz-scroll`}>
          {SECTIONS.map((x) => (
            <button key={x} onClick={() => setSec(x)} className={`w-full text-left px-3 h-9 rounded-xl text-xs mb-0.5 flex items-center gap-2 ${sec === x ? T.active : `${T.sub} ${T.hover}`}`}>
              {x}
            </button>
          ))}
        </div>

        <div className="flex-1 overflow-y-auto bz-scroll p-6">
          <div className="max-w-2xl space-y-4">
            {sec === "Identity" && (<>
              <div className="grid grid-cols-2 gap-3">
                <Field label="Name" hint="What customers will see."><input value={f.name} onChange={(e) => set("name", e.target.value)} className={inputCls(T)} placeholder="Sarah" /></Field>
                <Field label="Job title"><input value={f.title} onChange={(e) => set("title", e.target.value)} className={inputCls(T)} placeholder="Sales Agent" /></Field>
                <Field label="Type"><select value={f.type} onChange={(e) => set("type", e.target.value)} className={inputCls(T)}>{AGENT_TYPES_LIB.map((t) => <option key={t.id} value={t.id}>{t.name}</option>)}</select></Field>
                <Field label="Department"><input value={f.dept} onChange={(e) => set("dept", e.target.value)} className={inputCls(T)} placeholder="Revenue" /></Field>
              </div>
              <Field label="Purpose" hint="One sentence: what is this agent for?"><input value={f.purpose} onChange={(e) => set("purpose", e.target.value)} className={inputCls(T)} placeholder="Turn inbound interest into qualified opportunities." /></Field>
            </>)}

            {sec === "Role" && (<>
              <Field label="Role" hint="What it does day to day. This becomes the core of its instructions.">
                <textarea rows={3} value={f.role} onChange={(e) => set("role", e.target.value)} className={inputCls(T) + " resize-none"} />
              </Field>
              <div className="grid grid-cols-2 gap-3">
                <Field label="Primary objective"><input value={f.instr.objective} onChange={(e) => set("instr", { ...f.instr, objective: e.target.value })} className={inputCls(T)} /></Field>
                <Field label="Success looks like"><input value={f.instr.success} onChange={(e) => set("instr", { ...f.instr, success: e.target.value })} className={inputCls(T)} /></Field>
              </div>
              <Field label="Responsibilities"><textarea rows={2} value={f.instr.responsibilities} onChange={(e) => set("instr", { ...f.instr, responsibilities: e.target.value })} className={inputCls(T) + " resize-none"} /></Field>
              <div className="grid grid-cols-2 gap-3">
                <Field label="Always"><textarea rows={2} value={f.instr.dos} onChange={(e) => set("instr", { ...f.instr, dos: e.target.value })} className={inputCls(T) + " resize-none"} placeholder="Confirm the next step before ending" /></Field>
                <Field label="Never"><textarea rows={2} value={f.instr.donts} onChange={(e) => set("instr", { ...f.instr, donts: e.target.value })} className={inputCls(T) + " resize-none"} placeholder="Speculate about timelines" /></Field>
              </div>
              <Field label="Goals">{listEditor("goals", f.goals, goalIn, setGoalIn, "e.g. Book 10 demos a week", Target, T.faint)}</Field>
              {advanced && (
                <Field label="Compiled system prompt" hint="Generated from the fields above. This is what the model actually receives.">
                  <textarea rows={9} readOnly value={compiled} className={inputCls(T) + " resize-none font-mono text-[10px]"} />
                </Field>
              )}
            </>)}

            {sec === "Personality" && (<>
              <Field label="Tone" hint="Pick the blend. It is written into the prompt, not just displayed.">
                {chipRow(TONES, f.tones, (v, on) => set("tones", on ? f.tones.filter((x) => x !== v) : [...f.tones, v]))}
              </Field>
              <Field label="Custom tone instruction"><input value={f.tone} onChange={(e) => set("tone", e.target.value)} className={inputCls(T)} placeholder="Friendly but never chatty. Short sentences." /></Field>
              <Field label="Languages" hint="The agent replies in the customer's language when it is one of these.">
                {chipRow(["English", "Tamil", "Hindi", "Malay", "Arabic", "Spanish", "French"], f.langs, (v, on) => set("langs", on ? f.langs.filter((x) => x !== v) : [...f.langs, v]), true)}
              </Field>
            </>)}

            {sec === "Knowledge" && (<>
              <p className={`text-xs ${T.sub}`}>Only what you grant here is retrievable. Everything else in the knowledge base stays invisible to this agent.</p>
              {chipRow(kb.map((k) => k.name).concat(["services_and_prices", "objection playbook", "call scripts", "brand voice guide"]), f.knowledge, (v, on) => set("knowledge", on ? f.knowledge.filter((x) => x !== v) : [...f.knowledge, v]), true)}
              <Field label="Memory scope" hint="What the agent may recall about a customer.">
                {chipRow(["Current conversation", "Customer history", "CRM record", "Previous interactions", "Workspace knowledge"], f.memory, (v, on) => set("memory", on ? f.memory.filter((x) => x !== v) : [...f.memory, v]))}
              </Field>
            </>)}

            {sec === "Tools" && (<>
              <p className={`text-xs ${T.sub}`}>A permission without its tool does nothing. Both are checked before any action runs.</p>
              {chipRow(ALL_TOOLS, f.tools, (v, on) => set("tools", on ? f.tools.filter((x) => x !== v) : [...f.tools, v]))}
            </>)}

            {sec === "AI models" && (<>
              <p className={`text-xs ${T.sub}`}>
                Pick a model per job. A cheap model on routine questions leaves credits for a better one where the
                answer actually matters. Your plan decides which are available.
              </p>
              <div className="mt-3">
                <ModelChoice plan={String(billing.plan || "growth").toLowerCase()} value={ws.aiModels || {}} T={T}
                  onChange={(next) => saveWs({ aiModels: next }, "AI models")} />
              </div>
            </>)}

            {sec === "Permissions" && (<>
              <p className={`text-xs ${T.sub}`}>Each permission also needs the right tool and enough autonomy. The status on the right is the live result of all three checks.</p>
              {Object.entries(ACTIONS.CAN_READ_CRM ? [...new Set(Object.values(ACTIONS).map((a) => a.group))].reduce((acc, g) => ({ ...acc, [g]: Object.keys(ACTIONS).filter((k) => ACTIONS[k].group === g) }), {}) : {}).map(([group, keys]) => (
                <div key={group}>
                  <div className={`text-[10px] font-medium uppercase tracking-widest mb-1.5 ${T.faint}`}>{group}</div>
                  <div className="space-y-1 mb-3">
                    {keys.map((k) => {
                      const spec = ACTIONS[k];
                      const on = !!f.perms[k];
                      const res = on ? canAgentDo({ ...f, status: "Active" }, k, { ceiling: autonomy }) : null;
                      return (
                        <div key={k} className={`flex items-center gap-2.5 px-3 py-2 rounded-xl border ${T.border}`}>
                          <Toggle on={on} set={(v) => set("perms", { ...f.perms, [k]: v })} />
                          <span className="text-xs font-medium flex-1">{spec.label}</span>
                          <Pill c={RISK_TINT[spec.risk]}>{spec.risk}</Pill>
                          <span className={`text-[10px] w-40 text-right ${!on ? T.faint : res.ok ? "text-emerald-600" : "text-amber-600"}`}>
                            {!on ? "off" : res.ok ? "active" : res.code === "AUTONOMY" ? "needs Level " + spec.min : res.code === "NO_TOOL" ? "needs " + ACTION_TOOL[k] : res.code === "DESTRUCTIVE" ? "always approved by a human" : "blocked"}
                          </span>
                        </div>
                      );
                    })}
                  </div>
                </div>
              ))}
              <div className={`flex items-center gap-2 rounded-xl border p-3 ${T.border}`}>
                <Toggle on={f.allowDestructive} set={(v) => set("allowDestructive", v)} />
                <span className="text-xs flex-1">Allow destructive actions without a human</span>
                <Pill c={RISK_TINT.destructive}>not recommended</Pill>
              </div>
            </>)}

            {sec === "Autonomy" && (<>
              <div className={`rounded-xl p-3 text-[11px] ${T.softcard}`}>Workspace ceiling is Level {autonomy}. Anything above it is capped at run time, whatever this agent is set to.</div>
              <div className="space-y-1">
                {AUTONOMY_LEVELS.map((o) => (
                  <button key={o.l} onClick={() => set("autonomy", o.l)} className={`w-full text-left flex items-start gap-2.5 p-3 rounded-xl border transition-colors ${f.autonomy === o.l ? (dk ? "border-red-800 bg-red-950/40" : "border-red-200 bg-red-50/50") : `border-transparent ${T.hover}`} ${o.l > autonomy ? "opacity-45" : ""}`}>
                    <span className="mt-0.5 w-3.5 h-3.5 rounded-full border-2 shrink-0" style={f.autonomy === o.l ? { borderColor: BRAND, background: BRAND } : { borderColor: dk ? "#3f3f46" : "#d4d4d8" }} />
                    <div><div className="text-xs font-semibold">Level {o.l} · {o.name}{o.l > autonomy ? " · above the workspace ceiling" : ""}</div><div className={`text-[11px] ${T.sub}`}>{o.d}</div></div>
                  </button>
                ))}
              </div>
            </>)}

            {sec === "Guardrails" && (<>
              <p className={`text-xs ${T.sub}`}>Guardrails are matched against what the agent is about to say. A match blocks the message and rewrites it.</p>
              <div className="flex flex-wrap gap-1.5 mb-3">
                {GUARDRAIL_LIB.map((g) => (
                  <button key={g.id} onClick={() => set("rules", (f.rules || []).includes(g.rule) ? f.rules.filter((r) => r !== g.rule) : [...(f.rules || []), g.rule])}
                    className={`h-8 px-3 rounded-full border text-[11px] font-medium ${(f.rules || []).includes(g.rule) ? "text-white border-transparent" : `${T.chip} ${T.hover}`}`} style={(f.rules || []).includes(g.rule) ? { background: BRAND } : {}}>{g.rule}</button>
                ))}
              </div>
              {listEditor("rules", f.rules, ruleIn, setRuleIn, "Add your own rule", Shield, "text-emerald-500")}
              <div className={`rounded-xl p-3 text-[11px] leading-relaxed ${T.softcard}`}>
                Priority order, highest first: system safety → workspace policy → these guardrails → your instructions → the customer's request. A customer can never talk the agent past a rule above them.
              </div>
            </>)}

            {sec === "Escalation" && (<>
              <Field label="Hand to a human when">
                {chipRow(HANDOFF_TRIGGERS, (f.escalation || {}).when || [], (v, on) => set("escalation", { ...f.escalation, when: on ? f.escalation.when.filter((x) => x !== v) : [...(f.escalation.when || []), v] }))}
              </Field>
              <div className="grid grid-cols-2 gap-3">
                <Field label="Escalate to"><select value={(f.escalation || {}).who || ""} onChange={(e) => set("escalation", { ...f.escalation, who: e.target.value })} className={inputCls(T)}>{TEAM_USERS.map((u) => <option key={u}>{u}</option>)}</select></Field>
              </div>
              <Field label="Pass along" hint="What the human receives so the customer never repeats themselves.">
                {chipRow(["Transcript", "AI summary", "CRM record", "Reason", "Previous actions", "Sentiment"], (f.escalation || {}).include || [], (v, on) => set("escalation", { ...f.escalation, include: on ? f.escalation.include.filter((x) => x !== v) : [...(f.escalation.include || []), v] }), true)}
              </Field>
            </>)}

            {sec === "Channels" && (<>
              <p className={`text-xs ${T.sub}`}>The agent is only routed conversations on these channels, and cannot send on any other.</p>
              {chipRow(AGENT_CHANNELS, f.channels, (v, on) => set("channels", on ? f.channels.filter((x) => x !== v) : [...f.channels, v]))}
            </>)}

            {sec === "Review" && (
              <div className="space-y-2">
                <div className="text-sm font-semibold">Readiness check</div>
                {[["Identity", !!(f.name.trim() && f.title.trim())], ["Role", !!f.role.trim()], ["Knowledge", (f.knowledge || []).length > 0], ["Tools", f.tools.length > 0],
                  ["Permissions", Object.values(f.perms).some(Boolean)], ["Autonomy within ceiling", f.autonomy <= autonomy], ["Guardrails", (f.rules || []).length > 0],
                  ["Escalation path", ((f.escalation || {}).when || []).length > 0], ["Channels", f.channels.length > 0]].map(([label, ok]) => (
                  <div key={label} className="flex items-center gap-2 text-xs">
                    {ok ? <CheckCircle2 size={14} className="text-emerald-500" /> : <Circle size={13} className="text-amber-500" />}
                    <span className={ok ? "" : T.faint}>{label}</span>
                    {!ok && <span className="text-[10px] text-amber-600 ml-auto">incomplete</span>}
                  </div>
                ))}
                {health.issues.length > 0 && (
                  <div className={`rounded-xl border p-3 mt-3 ${T.border}`}>
                    <div className={`text-[10px] font-medium uppercase tracking-widest mb-1.5 ${T.faint}`}>Health</div>
                    {health.issues.map((i, n) => <div key={n} className={`text-[11px] flex gap-1.5 ${i.lvl === "error" ? "text-red-500" : "text-amber-600"}`}>{i.lvl === "error" ? <XCircle size={12} className="shrink-0 mt-0.5" /> : <AlertTriangle size={12} className="shrink-0 mt-0.5" />} {i.t}</div>)}
                  </div>
                )}
              </div>
            )}
          </div>
        </div>
      </div>
      {testing && <TestChat agent={f} onClose={() => setTesting(false)} />}
    </div>
  );
}

/* ---------- agent detail ---------- */
function AgentDetail({ id }) {
  const { T, dk, agents, setAgents, setSelAgent, setAgentEdit, autonomy, setConfirm, flash, log, convs, calls, audit, wfs, camps } = useApp();
  const [tab, setTab] = useState("Overview");
  const [testing, setTesting] = useState(false);
  const a = agents.find((x) => x.id === id);
  if (!a) return <div className="p-8 text-xs">That agent no longer exists. <button className="underline" onClick={() => setSelAgent(null)}>Back to the roster</button></div>;
  const health = agentHealth(a, autonomy);
  const myConvs = convs.filter((v) => (v.agent || "").startsWith(a.name));
  const myCalls = calls.filter((k) => (k.agent || "").startsWith(a.name));
  const myAudit = audit.filter((x) => x.who === a.name || (x.entity || "").includes(a.name));
  const usedIn = wfs.filter((w) => (w.nodes || []).some((n) => n.agent === a.id || n.agent === a.name));
  const granted = Object.keys(a.perms || {}).filter((k) => a.perms[k]);
  const toggle = () => {
    const v = a.status === "Active" ? "Paused" : "Active";
    if (v === "Active" && health.level === "Action required") { flash("Fix the configuration before activating: " + health.issues[0].t, "err"); return; }
    setAgents((ag) => ag.map((x) => x.id === id ? { ...x, status: v } : x));
    log("You", "Agent " + v.toLowerCase(), a.name); flash(a.name + " is now " + v.toLowerCase());
  };
  return (
    <div className="h-full overflow-y-auto bz-scroll">
      <div className="max-w-3xl mx-auto px-8 py-8">
        <button onClick={() => setSelAgent(null)} className={`flex items-center gap-1 text-xs mb-5 ${T.faint}`}><ArrowLeft size={12} /> Your workforce</button>
        <div className="flex items-start gap-4 flex-wrap">
          <div className="w-12 h-12 rounded-2xl grid place-items-center text-white shrink-0" style={{ background: a.status === "Active" ? BRAND : "#a1a1aa" }}><Bot size={20} /></div>
          <div className="flex-1 min-w-0">
            <h1 className="text-xl font-semibold bz-display tracking-tight">{a.name}</h1>
            <div className={`text-xs ${T.sub}`}>{a.title} · {a.dept || "no department"} · created {a.created}</div>
            <div className="flex items-center gap-1.5 mt-1.5"><Pill c={AG_STATUS_TINT[a.status]}>{a.status}</Pill><Pill c={HEALTH_TINT[health.level]}>{health.level}</Pill><Pill c={T.chip}>Level {Math.min(a.autonomy, autonomy)}</Pill></div>
          </div>
          <div className="flex gap-2">
            <button onClick={() => setTesting(true)} className={`h-9 px-3 rounded-xl border text-xs font-semibold inline-flex items-center gap-1.5 ${T.chip} ${T.hover}`}><PlayCircle size={13} /> Test</button>
            <button onClick={() => setAgentEdit(a.id)} className={`h-9 px-3 rounded-xl border text-xs font-semibold inline-flex items-center gap-1.5 ${T.chip} ${T.hover}`}><Pencil size={13} /> Edit</button>
            <button onClick={toggle} className="h-9 px-3.5 rounded-xl text-xs font-semibold text-white" style={{ background: a.status === "Active" ? "#71717a" : BRAND }}>{a.status === "Active" ? "Pause" : "Activate"}</button>
          </div>
        </div>

        <div className={`flex gap-1 border-b mt-7 mb-5 ${T.border}`}>
          {["Overview", "Permissions", "Performance", "Activity", "Versions"].map((x) => (
            <button key={x} onClick={() => setTab(x)} className={`px-3 h-9 text-xs font-semibold border-b-2 -mb-px ${tab === x ? "" : `border-transparent ${T.sub}`}`} style={tab === x ? { borderColor: BRAND, color: BRAND } : {}}>{x}</button>
          ))}
        </div>

        {tab === "Overview" && (
          <div className="space-y-4">
            {health.issues.length > 0 && (
              <div className={`rounded-2xl border p-4 ${health.level === "Action required" ? "border-red-200" : "border-amber-200"}`}>
                <div className="text-xs font-semibold mb-1.5">{health.level}</div>
                {health.issues.map((i, n) => <div key={n} className={`text-[11px] flex gap-1.5 ${i.lvl === "error" ? "text-red-500" : "text-amber-600"}`}>{i.lvl === "error" ? <XCircle size={12} className="shrink-0 mt-0.5" /> : <AlertTriangle size={12} className="shrink-0 mt-0.5" />} {i.t}</div>)}
              </div>
            )}
            <div className={`rounded-2xl p-5 ${T.card}`}><SecTitle>Purpose</SecTitle><p className="text-xs leading-relaxed">{a.purpose || a.role}</p></div>
            <div className={`rounded-2xl p-5 ${T.card}`}>
              <SecTitle>Autonomy · Level {Math.min(a.autonomy, autonomy)}</SecTitle>
              <p className={`text-xs ${T.sub}`}>{(AUTONOMY_LEVELS.find((o) => o.l === Math.min(a.autonomy, autonomy)) || {}).d}</p>
              {a.autonomy > autonomy && <p className="text-[11px] text-amber-600 mt-1.5">Configured at Level {a.autonomy} but capped by the workspace ceiling of {autonomy}.</p>}
            </div>
            <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
              <div className={`rounded-2xl p-5 ${T.card}`}>
                <SecTitle>Channels</SecTitle>
                <div className="flex flex-wrap gap-1.5">{(a.channels || []).map((c) => <span key={c} className={`h-7 px-2.5 rounded-full border text-[11px] inline-flex items-center gap-1.5 ${T.chip}`}><Brand id={c === "email" ? "gmail" : c === "webchat" ? "google" : c} size={12} /> {CH[c] ? CH[c].label : c}</span>)}</div>
              </div>
              <div className={`rounded-2xl p-5 ${T.card}`}>
                <SecTitle>Tools</SecTitle>
                <div className="flex flex-wrap gap-1.5">{(a.tools || []).map((t2) => <Pill key={t2} c={T.chip}>{t2}</Pill>)}</div>
              </div>
            </div>
            <div className={`rounded-2xl p-5 ${T.card}`}>
              <SecTitle>Guardrails</SecTitle>
              {(a.rules || []).map((r) => <div key={r} className="text-xs flex items-center gap-2 mb-1"><Shield size={12} className="text-emerald-500" /> {r}</div>)}
              {!(a.rules || []).length && <p className={`text-[11px] ${T.faint}`}>None configured.</p>}
            </div>
            <div className={`rounded-2xl p-5 ${T.card}`}>
              <SecTitle>Escalation</SecTitle>
              <p className={`text-xs ${T.sub}`}>Hands to <span className="font-semibold">{(a.escalation || {}).who || "nobody"}</span> when: {((a.escalation || {}).when || []).join(", ").toLowerCase() || "never"}. Passes along {((a.escalation || {}).include || []).join(", ").toLowerCase() || "nothing"}.</p>
            </div>
            {usedIn.length > 0 && (
              <div className={`rounded-2xl p-5 ${T.card}`}>
                <SecTitle>Used by workflows</SecTitle>
                {usedIn.map((w) => <div key={w.id} className="text-xs flex items-center gap-2"><Workflow size={12} style={{ color: BRAND }} /> {w.name}{a.status !== "Active" && <span className="text-amber-600 text-[10px] ml-auto">references a {a.status.toLowerCase()} agent</span>}</div>)}
              </div>
            )}
            <button onClick={() => setConfirm({ text: "Archive " + a.name + "?", detail: "History stays attached so past conversations remain readable.", yes: "Archive", onYes: () => { setAgents((ag) => ag.map((x) => x.id === id ? { ...x, status: "Archived" } : x)); setSelAgent(null); flash("Archived"); } })} className="text-[11px] text-red-500 font-medium">Archive this agent</button>
          </div>
        )}

        {tab === "Permissions" && (
          <div className="space-y-1.5">
            <p className={`text-xs mb-2 ${T.sub}`}>Live evaluation right now, including the workspace ceiling. This is exactly what the engine will decide at run time.</p>
            {Object.keys(ACTIONS).map((k) => {
              const r = canAgentDo(a, k, { ceiling: autonomy });
              return (
                <div key={k} className={`flex items-center gap-2.5 px-3 py-2 rounded-xl border ${T.border}`}>
                  {r.ok ? <CheckCircle2 size={14} className="text-emerald-500 shrink-0" /> : <X size={13} className={`shrink-0 ${T.faint}`} />}
                  <span className="text-xs font-medium w-40 shrink-0">{ACTIONS[k].label}</span>
                  <Pill c={RISK_TINT[ACTIONS[k].risk]}>{ACTIONS[k].risk}</Pill>
                  <span className={`text-[10px] flex-1 text-right ${r.ok ? "text-emerald-600" : T.faint}`}>{r.why}</span>
                </div>
              );
            })}
          </div>
        )}

        {tab === "Performance" && (
          <div className="grid grid-cols-2 md:grid-cols-4 gap-3">
            <Stat label="Conversations" value={String(myConvs.length)} sub="handled by this agent" />
            <Stat label="Calls" value={String(myCalls.length)} sub="voice sessions" />
            <Stat label="Escalations" value={String(myConvs.filter((v) => v.state === "Escalated").length)} sub="passed to a human" />
            <Stat label="Recorded actions" value={String((a.activity || []).length + myAudit.length)} sub="in the audit trail" />
            <Stat label="Autonomy" value={"L" + Math.min(a.autonomy, autonomy)} sub="effective level" />
            <Stat label="Permissions" value={String(granted.length)} sub="granted of " />
            <Stat label="Channels" value={String((a.channels || []).length)} sub="assigned" />
            <Stat label="Knowledge" value={String((a.knowledge || []).length)} sub="sources" />
          </div>
        )}

        {tab === "Activity" && (
          <div className="space-y-1.5">
            {myAudit.length === 0 && (a.activity || []).length === 0
              ? <p className={`text-xs ${T.faint}`}>Nothing recorded for this agent yet. Every action it takes will appear here with the customer, the tool used and the result.</p>
              : [...(a.activity || []), ...myAudit].slice(0, 30).map((x, i) => (
                <div key={i} className={`flex gap-2 text-[11px] rounded-xl p-2.5 ${T.softcard}`}>
                  <span className={`shrink-0 ${T.faint}`}>{x.at}</span>
                  <span className="font-semibold">{x.what || x.action}</span>
                  <span className="flex-1">{x.entity || x.detail}{x.to ? " → " + x.to : ""}</span>
                </div>
              ))}
          </div>
        )}

        {tab === "Versions" && (
          <div className="space-y-2">
            <p className={`text-xs ${T.sub}`}>Each save snapshots the configuration, so you can see which setup handled a historical conversation and roll back if a change made things worse.</p>
            {(a.versions || []).length === 0 ? <p className={`text-[11px] ${T.faint}`}>No previous versions yet.</p> : a.versions.map((v) => (
              <div key={v.id} className={`rounded-xl p-3 ${T.softcard}`}>
                <div className="flex items-center gap-2 text-[11px]">
                  <span className="font-semibold">{v.at}</span><span className={T.faint}>by {v.who}</span>
                  <span className={`ml-auto ${T.faint}`}>Level {v.snap.autonomy} · {(v.snap.tools || []).length} tools · {(v.snap.rules || []).length} guardrails</span>
                  <button onClick={() => { setAgents((ag) => ag.map((x) => x.id === id ? { ...x, ...v.snap } : x)); log("You", "Agent rolled back", a.name + " to " + v.at); flash("Rolled back. Historical conversations keep the version that handled them."); }}
                    className="text-[11px] font-semibold" style={{ color: BRAND }}>Restore</button>
                </div>
              </div>
            ))}
          </div>
        )}
        {testing && <TestChat agent={a} onClose={() => setTesting(false)} />}
      </div>
    </div>
  );
}

/* ==================================================================== */
/* GRAPH WORKFLOW ENGINE — nodes anywhere, edges anywhere               */
/* ==================================================================== */

/* ==================================================================== */
/* WORKFLOW EXECUTION ENGINE                                             */
/* Pure functions so a run can be tested, replayed and reasoned about.    */
/* runWorkflow walks the real graph, evaluates real conditions against a  */
/* real variable context, and calls out to the platform through `exec`.   */
/* ==================================================================== */

const OPERATORS = [
  { id: "eq", label: "equals", fn: (a, b) => String(a) === String(b) },
  { id: "ne", label: "does not equal", fn: (a, b) => String(a) !== String(b) },
  { id: "contains", label: "contains", fn: (a, b) => String(a).toLowerCase().includes(String(b).toLowerCase()) },
  { id: "ncontains", label: "does not contain", fn: (a, b) => !String(a).toLowerCase().includes(String(b).toLowerCase()) },
  { id: "gt", label: "is greater than", fn: (a, b) => parseFloat(a) > parseFloat(b) },
  { id: "gte", label: "is at least", fn: (a, b) => parseFloat(a) >= parseFloat(b) },
  { id: "lt", label: "is less than", fn: (a, b) => parseFloat(a) < parseFloat(b) },
  { id: "lte", label: "is at most", fn: (a, b) => parseFloat(a) <= parseFloat(b) },
  { id: "exists", label: "exists", fn: (a) => a !== undefined && a !== null && a !== "", unary: true },
  { id: "nexists", label: "does not exist", fn: (a) => a === undefined || a === null || a === "", unary: true },
  { id: "istrue", label: "is true", fn: (a) => a === true || a === "true" || a === "yes", unary: true },
  { id: "isfalse", label: "is false", fn: (a) => a === false || a === "false" || a === "no", unary: true },
  { id: "in", label: "is in list", fn: (a, b) => String(b).split(",").map((x) => x.trim().toLowerCase()).includes(String(a).toLowerCase()) },
  { id: "nin", label: "is not in list", fn: (a, b) => !String(b).split(",").map((x) => x.trim().toLowerCase()).includes(String(a).toLowerCase()) },
];

/* actions the engine can genuinely perform, each mapped to a platform capability */
const WF_ACTIONS = {
  send_message:  { label: "Send message", needs: "channel", perm: "CAN_SEND_WHATSAPP", integration: "GoWhats" },
  send_email:    { label: "Send email", perm: "CAN_SEND_EMAIL", integration: "Gmail" },
  create_task:   { label: "Create task", perm: "CAN_CREATE_TASK" },
  add_tag:       { label: "Add tag to contact", perm: "CAN_UPDATE_CONTACT" },
  update_contact:{ label: "Update contact field", perm: "CAN_UPDATE_CONTACT" },
  create_contact:{ label: "Create contact", perm: "CAN_WRITE_CRM" },
  create_deal:   { label: "Create deal", perm: "CAN_CREATE_DEAL" },
  move_deal:     { label: "Move deal stage", perm: "CAN_UPDATE_DEAL" },
  book_appt:     { label: "Book appointment", perm: "CAN_BOOK_APPOINTMENT", integration: "Google Calendar" },
  cancel_appt:   { label: "Cancel appointment", perm: "CAN_CANCEL_APPOINTMENT" },
  create_virtual_appt: { label: "Create virtual appointment", perm: "CAN_BOOK_APPOINTMENT" },
  create_meet:   { label: "Create Google Meet", perm: "CAN_BOOK_APPOINTMENT" },
  send_meet_link: { label: "Send meeting link", perm: "CAN_SEND_WHATSAPP" },
  send_reminder: { label: "Send reminder", perm: "CAN_SEND_WHATSAPP" },
  assign_conv:   { label: "Assign conversation", perm: "CAN_ASSIGN_CONVERSATION" },
  add_note:      { label: "Add note", perm: "CAN_UPDATE_CONTACT" },
  notify:        { label: "Notify a teammate", perm: "CAN_CREATE_TASK" },
  start_campaign:{ label: "Start campaign", perm: "CAN_START_CAMPAIGN" },
  place_call:    { label: "Place a call", perm: "CAN_PLACE_CALL", integration: "MrAssistant.ai" },
};
const VAR_LIB = [
  { k: "contact.name", l: "Contact name" }, { k: "contact.phone", l: "Contact phone" }, { k: "contact.email", l: "Contact email" },
  { k: "contact.company", l: "Company" }, { k: "contact.stage", l: "Lifecycle stage" }, { k: "contact.score", l: "Lead score" },
  { k: "contact.status", l: "Lead status" }, { k: "deal.value", l: "Deal value" }, { k: "deal.stage", l: "Deal stage" },
  { k: "appointment.start", l: "Appointment time" }, { k: "appointment.status", l: "Appointment status" },
  { k: "message.text", l: "Message text" }, { k: "call.duration", l: "Call duration" }, { k: "replied", l: "Customer replied" },
];
const END_STATES = ["Completed", "Converted", "Escalated", "Cancelled", "No response", "Failed"];
const RUN_STATUS = ["Queued", "Running", "Waiting", "Awaiting approval", "Completed", "Failed", "Cancelled", "Timed out"];

/* {{path.to.value}} resolution against the run context */
function wfResolve(expr, ctx) {
  if (expr === undefined || expr === null) return expr;
  return String(expr).replace(/\{\{([\w.]+)\}\}/g, (m, path) => {
    const v = path.split(".").reduce((o, k) => (o === undefined || o === null ? undefined : o[k]), ctx);
    return v === undefined || v === null ? m : v;
  });
}
const wfGetVar = (path, ctx) => path.split(".").reduce((o, k) => (o === undefined || o === null ? undefined : o[k]), ctx);
const wfUnresolved = (text, ctx) => (String(text || "").match(/\{\{[\w.]+\}\}/g) || []).filter((v) => wfResolve(v, ctx) === v);

function evalCondition(node, ctx) {
  const groups = node.cond && node.cond.groups && node.cond.groups.length ? node.cond.groups : [];
  if (!groups.length) return { yes: true, why: "No rule configured, so this always takes the Yes path." };
  const join = (node.cond && node.cond.join) || "AND";
  const results = groups.map((g) => {
    const op = OPERATORS.find((o) => o.id === g.op) || OPERATORS[0];
    const left = wfGetVar(g.left || "", ctx);
    const right = wfResolve(g.right, ctx);
    const pass = op.unary ? op.fn(left) : op.fn(left, right);
    return { pass, text: `${g.left} (${left === undefined ? "missing" : left}) ${op.label}${op.unary ? "" : " " + right}` };
  });
  const yes = join === "OR" ? results.some((r) => r.pass) : results.every((r) => r.pass);
  return { yes, why: results.map((r) => (r.pass ? "✓ " : "✗ ") + r.text).join(join === "OR" ? " OR " : " AND ") };
}

/* the engine. `exec` performs real side effects; in test mode it is a recorder. */
function runWorkflow(wf, { ctx = {}, test = false, exec, maxNodes = 60, maxLoops = 3, resumeFrom = null, existing = null } = {}) {
  const nodes = wf.nodes || [], edges = wf.edges || [];
  const byId = (id) => nodes.find((n) => n.id === id);
  const nextFrom = (id, handle) => {
    const e = edges.find((x) => x.from === id && (handle ? x.h === handle : x.h === "out" || !x.h));
    return e ? e.to : null;
  };
  const run = existing || {
    id: "r" + Date.now() + Math.floor(Math.random() * 999), wfId: wf.id, wfVersion: wf.version || 1,
    at: new Date().toISOString(), test, status: "Running", steps: [], ctx: { ...ctx }, currentNode: null, endState: null, error: null,
    contactName: (ctx.contact && ctx.contact.name) || "", trigger: (nodes.find((n) => n.type === "trigger") || {}).label || "",
  };
  const visits = {};
  let cur = resumeFrom || (nodes.find((n) => n.type === "trigger") || {}).id;
  let steps = 0;
  const log = (node, status, note, extra) => run.steps.push({ id: node.id, type: node.type, label: node.label, status, note, at: new Date().toISOString(), ...(extra || {}) });

  while (cur && steps++ < maxNodes) {
    const node = byId(cur);
    if (!node) { run.status = "Failed"; run.error = "Broken connection: a node referenced by an edge no longer exists."; break; }
    visits[cur] = (visits[cur] || 0) + 1;
    if (visits[cur] > maxLoops) { log(node, "stopped", `Loop guard: this node ran ${maxLoops} times, so the run was stopped.`); run.status = "Failed"; run.endState = "Failed"; run.error = "Loop limit reached"; break; }
    run.currentNode = cur;

    if (node.type === "trigger") { log(node, "ok", "Triggered by " + (node.label || "an event")); cur = nextFrom(cur, "out"); continue; }

    if (node.type === "if") {
      const r = evalCondition(node, run.ctx);
      log(node, "ok", r.why, { branch: r.yes ? "Yes" : "No" });
      cur = nextFrom(cur, r.yes ? "true" : "false");
      if (!cur) { run.status = "Completed"; run.endState = "Completed"; log(node, "ok", `The ${r.yes ? "Yes" : "No"} path has no next step, so the run finished here.`); }
      continue;
    }

    if (node.type === "collect") {
      const answer = (run.ctx.replies && run.ctx.replies[node.varName]) !== undefined ? run.ctx.replies[node.varName] : (test ? (node.testValue || "Thursday 11:00") : undefined);
      if (answer === undefined) { run.status = "Waiting"; log(node, "waiting", `Waiting for the customer to answer: “${node.label}”.`); break; }
      run.ctx[node.varName || "answer"] = answer;
      log(node, "ok", `Saved {{${node.varName || "answer"}}} = ${answer}`);
      cur = nextFrom(cur, "out"); continue;
    }

    if (node.type === "ai") {
      const res = exec ? exec({ kind: "agent", node, ctx: run.ctx, test }) : { ok: true, out: {} };
      if (!res.ok) { log(node, "error", res.why); const err = nextFrom(cur, "err"); if (err) { cur = err; continue; } run.status = "Failed"; run.endState = "Failed"; run.error = res.why; break; }
      Object.assign(run.ctx, res.out || {});
      if (node.varName && res.out && res.out[node.varName] === undefined) run.ctx[node.varName] = res.value !== undefined ? res.value : 82;
      log(node, "ok", res.note || `${res.agentName || "Agent"} ran and returned ${Object.keys(res.out || {}).join(", ") || "a response"}`);
      cur = nextFrom(cur, "out"); continue;
    }

    if (node.type === "act") {
      const spec = ownLookup(WF_ACTIONS, node.action) || { label: node.label || "Action" };
      const body = wfResolve(node.sub || "", run.ctx);
      const missing = wfUnresolved(node.sub, run.ctx);
      /* Governance is checked here, at run time, not when the workflow was
         drawn. A workflow built at Level 4 pauses at this node if the ceiling
         has since been lowered; it never inherits authority from its author. */
      if (spec.perm && !test) {
        const gate = decide({ action: spec.perm, agent: ctx.governAgent || null,
          ceiling: ctx.ceiling !== undefined ? ctx.ceiling : 4,
          ctx: { isConnected: ctx.isConnected, audienceSize: run.ctx.audienceSize,
            commsKind: run.ctx.commsKind, requestedBy: "Workflow: " + (wf.name || wf.id) } });
        if (gate.verdict !== "allow") {
          run.governance = [...(run.governance || []), auditFor(gate, { target: node.id })];
          if (gate.verdict === "deny") {
            log(node, "error", gate.reason + " " + (gate.fallback || ""), { governance: gate.code });
            const err = nextFrom(cur, "err");
            if (err) { cur = err; continue; }
            run.status = "Failed"; run.endState = "Blocked"; run.error = gate.reason; break;
          }
          /* pause for approval rather than skipping the step or bypassing it */
          log(node, "waiting", gate.reason + " " + (gate.fallback || ""), { governance: gate.code, approval: true });
          run.status = "Waiting"; run.endState = "Awaiting approval"; run.approvalNode = node.id;
          run.approval = { action: spec.perm, label: spec.label, body, reason: gate.reason, required: gate.required, effective: gate.effective };
          break;
        }
        run.governance = [...(run.governance || []), auditFor(gate, { target: node.id, outcome: "allowed" })];
      }
      if (missing.length) { log(node, "error", `Cannot run: ${missing.join(", ")} has no value in this run.`); const err = nextFrom(cur, "err"); if (err) { cur = err; continue; } run.status = "Failed"; run.endState = "Failed"; run.error = "Unresolved variable " + missing[0]; break; }
      const res = exec ? exec({ kind: "action", node, action: node.action, body, ctx: run.ctx, test }) : { ok: true };
      if (!res.ok) {
        log(node, "error", res.why, { attempts: res.attempts });
        const err = nextFrom(cur, "err");
        if (err) { cur = err; continue; }
        run.status = "Failed"; run.endState = "Failed"; run.error = res.why; break;
      }
      log(node, "ok", res.note || `${spec.label}${body ? " · " + body.slice(0, 60) : ""}`);
      cur = nextFrom(cur, "out"); continue;
    }

    if (node.type === "api") {
      const url = wfResolve(node.sub || "", run.ctx);
      const res = exec ? exec({ kind: "api", node, url, ctx: run.ctx, test }) : { ok: true, out: {} };
      if (!res.ok) {
        log(node, "error", res.why || "The request failed.");
        const err = nextFrom(cur, "err");
        if (err) { cur = err; continue; }
        run.status = "Failed"; run.endState = "Failed"; run.error = res.why; break;
      }
      Object.assign(run.ctx, res.out || {});
      log(node, "ok", `${node.method || "GET"} ${url} → ${res.status || 200}${res.out ? " · mapped " + Object.keys(res.out).join(", ") : ""}`);
      cur = nextFrom(cur, "out"); continue;
    }

    if (node.type === "wait") {
      if (node.waitFor === "reply") {
        const replied = run.ctx.replied === true;
        if (!replied && !test) { run.status = "Waiting"; log(node, "waiting", `Waiting for a reply, up to ${node.sub || "24 hours"}.`); break; }
        log(node, "ok", test ? "Wait skipped in test mode" : "Reply received");
      } else {
        log(node, "ok", test ? `Wait of ${node.sub || "the configured delay"} skipped in test mode` : `Waiting ${node.sub || "as configured"}`);
        if (!test) { run.status = "Waiting"; break; }
      }
      cur = nextFrom(cur, "out"); continue;
    }

    if (node.type === "appr") {
      if (run.ctx.approved === true) { log(node, "ok", "Approved by a human"); cur = nextFrom(cur, "true") || nextFrom(cur, "out"); continue; }
      if (run.ctx.approved === false) { log(node, "ok", "Rejected by a human"); const no = nextFrom(cur, "false"); if (no) { cur = no; continue; } run.status = "Cancelled"; run.endState = "Cancelled"; break; }
      if (test) { log(node, "ok", "Approval simulated as granted in test mode"); cur = nextFrom(cur, "true") || nextFrom(cur, "out"); continue; }
      run.status = "Awaiting approval";
      log(node, "waiting", `Paused for approval: ${node.label}. It is in the Approval Center.`);
      if (exec) exec({ kind: "approval", node, ctx: run.ctx, runId: run.id });
      break;
    }

    if (node.type === "handoff") {
      if (exec) exec({ kind: "handoff", node, ctx: run.ctx, test });
      log(node, "ok", `Handed to ${node.assignee || "the team"} with the full context.`);
      run.status = "Completed"; run.endState = "Escalated";
      cur = nextFrom(cur, "out");
      if (!cur) break;
      continue;
    }

    if (node.type === "end") {
      log(node, "ok", node.endState || "Completed");
      run.status = "Completed"; run.endState = node.endState || "Completed";
      break;
    }

    log(node, "ok", "Step ran");
    cur = nextFrom(cur, "out");
  }
  if (steps >= maxNodes && run.status === "Running") { run.status = "Timed out"; run.error = "Exceeded " + maxNodes + " steps"; }
  if (run.status === "Running" && !cur) { run.status = "Completed"; run.endState = run.endState || "Completed"; }
  run.ms = 40 + run.steps.length * 30;
  return run;
}

/* validation and dependency checks before publishing */
function validateWorkflow(wf, { agents = [], connected = () => true, ceiling = 4 } = {}) {
  const errs = [], warns = [];
  const nodes = wf.nodes || [], edges = wf.edges || [];
  if (!wf.name || !wf.name.trim()) errs.push("Give the workflow a name.");
  const triggers = nodes.filter((n) => n.type === "trigger");
  if (!triggers.length) errs.push("Add a trigger so the workflow knows when to run.");
  if (nodes.length < 2) errs.push("Add at least one step after the trigger.");
  nodes.forEach((n) => { if (!n.label || !n.label.trim()) errs.push("A " + (NODE_TYPES[n.type] ? NODE_TYPES[n.type].name.toLowerCase() : "node") + " has no label."); });
  if (triggers.length && !edges.some((e) => triggers.some((t) => t.id === e.from))) errs.push("Connect the trigger to a first step.");
  edges.forEach((e) => { if (!nodes.find((n) => n.id === e.to) || !nodes.find((n) => n.id === e.from)) errs.push("A connection points at a node that no longer exists."); });
  const reachable = new Set();
  const walk = (id) => { if (!id || reachable.has(id)) return; reachable.add(id); edges.filter((e) => e.from === id).forEach((e) => walk(e.to)); };
  triggers.forEach((t) => walk(t.id));
  const orphans = nodes.filter((n) => !reachable.has(n.id));
  orphans.forEach((n) => warns.push(`“${n.label || "Untitled"}” is unreachable and will never run.`));
  nodes.filter((n) => n.type === "if").forEach((n) => {
    if (!edges.some((e) => e.from === n.id && e.h === "true") || !edges.some((e) => e.from === n.id && e.h === "false"))
      warns.push(`“${n.label}” has an unconnected branch, so that path ends the run.`);
    if (!n.cond || !(n.cond.groups || []).length) warns.push(`“${n.label}” has no rule configured, so it always takes Yes.`);
  });
  nodes.filter((n) => n.type === "ai").forEach((n) => {
    const ag = agents.find((a) => a.id === n.agent);
    if (n.agent && !ag) errs.push(`“${n.label}” references an agent that no longer exists.`);
    else if (ag && ag.status !== "Active") warns.push(`${ag.name} is ${ag.status.toLowerCase()}, so “${n.label}” will stall.`);
  });
  nodes.filter((n) => n.type === "act").forEach((n) => {
    const spec = WF_ACTIONS[n.action];
    if (!n.action) warns.push(`“${n.label}” has no action selected, so it does nothing.`);
    if (spec && spec.integration && !connected(PROVIDER_BY_NAME[spec.integration]))
      errs.push(`“${n.label}” needs ${spec.integration}, which is not connected.`);
  });
  nodes.filter((n) => n.type === "api").forEach((n) => {
    if (!n.sub || !/^https?:|^\//.test(n.sub)) warns.push(`“${n.label}” has no valid URL.`);
    if (!edges.some((e) => e.from === n.id && e.h === "err")) warns.push(`“${n.label}” has no error path, so a failure ends the run.`);
  });
  /* variables referenced but never produced upstream */
  const produced = new Set(["contact.name", "contact.phone", "contact.email", "contact.company", "contact.stage", "deal.value", "appointment.start", "message.text", "call.duration"]);
  nodes.forEach((n) => { if (n.varName) produced.add(n.varName); });
  nodes.forEach((n) => {
    (String(n.sub || "").match(/\{\{([\w.]+)\}\}/g) || []).forEach((v) => {
      const key = v.replace(/[{}]/g, "");
      if (!produced.has(key)) warns.push(`“${n.label}” uses {{${key}}}, which nothing upstream produces.`);
    });
  });
  return { errs, warns, orphans };
}

/* what this workflow could actually do once live */
function impactOf(wf, contacts) {
  const acts = (wf.nodes || []).filter((n) => n.type === "act");
  const kinds = [...new Set(acts.map((n) => (WF_ACTIONS[n.action] || {}).label).filter(Boolean))];
  const channels = [...new Set(acts.map((n) => n.channel).filter(Boolean))];
  const sends = acts.filter((n) => ["send_message", "send_email", "place_call", "start_campaign"].includes(n.action)).length;
  return { kinds, channels, sends, reach: sends ? (contacts || []).length : 0,
    risky: acts.some((n) => ["place_call", "start_campaign", "cancel_appt", "create_deal"].includes(n.action)) };
}
function workflowHealth(wf, deps) {
  const v = validateWorkflow(wf, deps);
  const runs = wf.runsLog || [];
  const failRate = runs.length ? runs.filter((r) => r.status === "Failed").length / runs.length : 0;
  if (v.errs.length) return { level: "Error", issues: v.errs.concat(v.warns) };
  if (v.warns.length || failRate > 0.3) return { level: "Warning", issues: v.warns.concat(failRate > 0.3 ? [Math.round(failRate * 100) + "% of recent runs failed."] : []) };
  return { level: "Healthy", issues: [] };
}

const NODE_W = 232, NODE_H = 62;
const NODE_TYPES = {
  trigger: { name: "Trigger",      Icon: Radio,     c: "text-red-600",     l: "bg-red-50 border-red-200",         d: "bg-red-950 border-red-900" },
  ai:      { name: "AI step",      Icon: Sparkles,  c: "text-fuchsia-600", l: "bg-fuchsia-50 border-fuchsia-200", d: "bg-fuchsia-950 border-fuchsia-900" },
  collect: { name: "Collect info", Icon: ListChecks,c: "text-sky-600",     l: "bg-sky-50 border-sky-200",         d: "bg-sky-950 border-sky-900" },
  if:      { name: "Condition",    Icon: GitBranch, c: "text-violet-600",  l: "bg-violet-50 border-violet-200",   d: "bg-violet-950 border-violet-900" },
  act:     { name: "Action",       Icon: Zap,       c: "text-emerald-600", l: "bg-emerald-50 border-emerald-200", d: "bg-emerald-950 border-emerald-900" },
  api:     { name: "API call",     Icon: Globe,     c: "text-indigo-600",  l: "bg-indigo-50 border-indigo-200",   d: "bg-indigo-950 border-indigo-900" },
  wait:    { name: "Wait",         Icon: Timer,     c: "text-amber-600",   l: "bg-amber-50 border-amber-200",     d: "bg-amber-950 border-amber-900" },
  appr:    { name: "Approval",     Icon: Lock,      c: "text-orange-600",  l: "bg-orange-50 border-orange-200",   d: "bg-orange-950 border-orange-900" },
  handoff: { name: "Human handoff",Icon: Users,     c: "text-rose-600",    l: "bg-rose-50 border-rose-200",       d: "bg-rose-950 border-rose-900" },
  end:     { name: "End",          Icon: CheckCircle2, c: "text-zinc-500", l: "bg-zinc-50 border-zinc-200",       d: "bg-zinc-900 border-zinc-700" },
};
const NODE_LIB = [
  { group: "Start & finish", items: [
    { type: "trigger", d: "When this event happens" },
    { type: "end", d: "Marks a finished path" },
  ]},
  { group: "Intelligence", items: [
    { type: "ai", d: "Analyze, decide, draft, qualify" },
    { type: "collect", d: "Ask & save to a variable" },
    { type: "if", d: "True / False branch" },
  ]},
  { group: "Actions", items: [
    { type: "act", d: "Send, create, assign, book, notify" },
    { type: "api", d: "Webhook or REST call, with error path" },
    { type: "wait", d: "Delay or wait for a reply" },
    { type: "appr", d: "Pause for a human decision" },
    { type: "handoff", d: "Route to your team with context" },
  ]},
];
const TRIGGERS = ["New WhatsApp message received", "New Instagram DM received", "New email received", "Missed call (MrAssistant.ai)", "Incoming call answered", "Deal stage changed", "Appointment booked", "Appointment no show", "Form submitted", "Tag added to contact", "Negative sentiment detected", "Order placed (Shopify)", "Payment failed (Stripe)"];
const nid = () => "n" + Math.random().toString(36).slice(2, 8);

/* handles: out (default), true/false (condition), err (api/act) */
const handlePos = (n, h) => {
  if (h === "in")    return { x: n.x + NODE_W / 2, y: n.y };
  if (h === "true")  return { x: n.x + 58,          y: n.y + NODE_H };
  if (h === "false") return { x: n.x + NODE_W - 58, y: n.y + NODE_H };
  if (h === "err")   return { x: n.x + NODE_W,      y: n.y + NODE_H / 2 };
  return { x: n.x + NODE_W / 2, y: n.y + NODE_H };
};
const upstreamVars = (nodes, edges, id, seen = new Set()) => {
  if (seen.has(id)) return [];
  seen.add(id);
  let vars = [];
  edges.filter((e) => e.to === id).forEach((e) => {
    const src = nodes.find((n) => n.id === e.from);
    if (!src) return;
    if (src.varName) vars.push(src.varName);
    vars = vars.concat(upstreamVars(nodes, edges, src.id, seen));
  });
  return [...new Set(vars)];
};

