/* ---- fuzzy matching so a typo does not defeat the whole conversation ---- */
function editDistance(a, b) {
  if (Math.abs(a.length - b.length) > 3) return 99;
  const prev = Array(b.length + 1).fill(0).map((_, i) => i);
  for (let i = 1; i <= a.length; i++) {
    const cur = [i];
    for (let j = 1; j <= b.length; j++)
      cur[j] = Math.min(prev[j] + 1, cur[j - 1] + 1, prev[j - 1] + (a[i - 1] === b[j - 1] ? 0 : 1));
    for (let j = 0; j <= b.length; j++) prev[j] = cur[j];
  }
  return prev[b.length];
}
/* a word matches a signal if it contains it, or is one or two typos away */
function fuzzyHit(words, term) {
  const t = term.trim();
  if (t.includes(" ")) return null;                       // phrases handled by direct containment
  const tol = t.length >= 8 ? 2 : t.length >= 5 ? 1 : 0;
  if (!tol) return null;
  const found = words.find((w) => w.length >= t.length - 2 && editDistance(w, t) <= tol);
  return found ? { word: found, term: t } : null;
}

/* ---- what the person is doing with this turn, beyond the topic ---- */
const SPEECH_ACTS = [
  { id: "greeting", re: /^\s*(hi|hey|hello|yo|good (morning|afternoon|evening)|namaste|salaam|hola)\b/i },
  { id: "correction", re: /\b(no,?\s|not really|actually|i meant|thats wrong|that's wrong|wrong|incorrect|rather)\b/i },
  { id: "confirm", re: /^\s*(yes|yeah|yep|correct|right|exactly|thats right|that's right|spot on|ok|okay|sure|perfect)\b/i },
  { id: "decline", re: /\b(no thanks|not now|later|skip|maybe later|not interested)\b/i },
  { id: "unsure", re: /\b(not sure|dunno|don'?t know|no idea|whatever|you decide|anything|up to you|surprise me)\b/i },
  { id: "frustrated", re: /\b(annoying|frustrat|useless|stupid|waste of time|hate|angry|fed up|ridiculous)\b/i },
  { id: "impatient", re: /\b(hurry|quick|just do it|get on with|skip the questions|fast)\b/i },
  { id: "question", re: /\?\s*$|^(what|how|why|when|where|who|can|could|do|does|is|are|will|would|should)\b/i },
  { id: "smalltalk", re: /\b(how are you|whats up|what's up|who are you|are you a (bot|robot|human|real))\b/i },
  { id: "gratitude", re: /\b(thanks|thank you|cheers|appreciate)\b/i },
];
const detectActs = (text) => SPEECH_ACTS.filter((a) => a.re.test(text || "")).map((a) => a.id);
/* negation matters: "we do not do retail" must not classify as retail */
function stripNegated(text) {
  return String(text || "").replace(/\b(?:not|no longer|don'?t|do not|doesn'?t|never|isn'?t|aren'?t|except|apart from|other than)\b[^.,;!?]{0,40}/gi, " ");
}
/* things people mention that are useful even when we did not ask */
const LOCATION_RE = /\b(?:in|from|based in|located in|serving)\s+([A-Z][a-zA-Z]+(?:\s+[A-Z][a-zA-Z]+){0,2})\b/;
const COUNTRY_HINTS = { singapore: "SG", india: "IN", chennai: "IN", mumbai: "IN", delhi: "IN", bangalore: "IN", bengaluru: "IN",
  dubai: "AE", uae: "AE", "abu dhabi": "AE", london: "GB", uk: "GB", "united kingdom": "GB", usa: "US", "united states": "US",
  america: "US", australia: "AU", sydney: "AU", nigeria: "NG", lagos: "NG", kenya: "KE", nairobi: "KE", brazil: "BR",
  malaysia: "MY", indonesia: "ID", philippines: "PH", japan: "JP", tokyo: "JP", germany: "DE", france: "FR", spain: "ES", uganda: "UG", kampala: "UG" };
const LANG_HINTS = { english: "en", tamil: "ta", hindi: "hi", arabic: "ar", french: "fr", spanish: "es", portuguese: "pt",
  japanese: "ja", malay: "ms", mandarin: "zh", bahasa: "id" };
const TOOL_HINTS = ["hubspot","salesforce","zoho","pipedrive","freshworks","shopify","woocommerce","stripe","razorpay",
  "calendly","google calendar","outlook","gmail","slack","notion","excel","spreadsheet","tally","quickbooks","xero","zendesk","intercom"];

function extractLocation(text) {
  const hay = String(text || "").toLowerCase();
  for (const [k, cc] of Object.entries(COUNTRY_HINTS)) if (hay.includes(k)) return { place: k, country: cc };
  const m = LOCATION_RE.exec(text || "");
  return m ? { place: m[1], country: null } : null;
}
const extractLanguages = (text) => { const hay = String(text || "").toLowerCase();
  return Object.entries(LANG_HINTS).filter(([k]) => hay.includes(k)).map(([, v]) => v); };
const extractTools = (text) => { const hay = String(text || "").toLowerCase();
  return TOOL_HINTS.filter((t) => hay.includes(t)); };
const extractHours = (text) => {
  const m = /\b(\d{1,2})(?::(\d{2}))?\s*(?:am|:00)?\s*(?:to|-|until|till)\s*(\d{1,2})(?::(\d{2}))?\s*(?:pm|am)?/i.exec(text || "");
  if (!m) return null;
  const to24 = (h, ampm) => { h = +h; if (/pm/i.test(ampm || "") && h < 12) h += 12; return h; };
  return { start: String(to24(m[1], "am")).padStart(2, "0") + ":" + (m[2] || "00"),
           end: String(to24(m[3], "pm")).padStart(2, "0") + ":" + (m[4] || "00") };
};

const industryLabel = (id) => INDUSTRY_LABEL[id] || INDUSTRY_LABEL_EXTRA[id] || (id ? String(id).replace(/_/g, " ") : "your line of work");
/* text after these markers names the CUSTOMER, not the business itself, so
   "we sell software to hospitals" is a software company, not a hospital */
const CUSTOMER_MARKER = /\b(?:sell(?:ing|s)?|serve|serving|supply(?:ing)?|provide|providing|market(?:ing)?|built?|building|software|delivery|deliver(?:ing)?|services?|solutions?)\s+(?:\w+\s+){0,3}?(?:to|for)\b|\bfor\s+\w+\s+(?:brands|companies|clients|businesses|firms)\b|\bour (?:clients?|customers?|users?) are\b|\bwe (?:work|partner) with\b/i;

function classifyIndustry(text) {
  const clean = stripNegated(text);
  const hay = norm(clean);
  const words = hay.trim().split(" ").filter((w) => w.length > 2);
  /* everything after the marker describes who they sell to */
  const mk = String(clean || "").match(CUSTOMER_MARKER);
  const custTail = mk ? norm(String(clean).slice(String(clean).toLowerCase().indexOf(mk[0].toLowerCase()) + mk[0].length)) : "";
  const scores = Object.entries(INDUSTRY_SIGNALS).map(([id, sig]) => {
    let score = 0; const matched = [];
    /* a multi word term like "law firm" is far more specific than a noun like
       "property", so specificity is weighted rather than treated as equal */
    sig.strong.forEach((w) => {
      if (hit(hay, w)) {
        /* a term that only appears in the customer clause is not their industry */
        if (custTail && hit(custTail, w) && !hit(norm(String(clean).slice(0, String(clean).toLowerCase().indexOf(mk[0].toLowerCase()))), w)) {
          score -= w.trim().includes(" ") ? 3 : 2; return;
        }
        score += w.trim().includes(" ") ? 5 : 3; matched.push(w.trim()); return;
      }
      const fz = fuzzyHit(words, w);
      if (fz) { score += 2; matched.push(fz.word + " (read as " + fz.term + ")"); }   // typo tolerance, scored lower than an exact hit
    });
    (sig.weak || []).forEach((w) => { if (hit(hay, w)) { score += w.trim().includes(" ") ? 2 : 1; matched.push(w.trim()); } });
    return { id, score, matched };
  }).filter((x) => x.score > 0).sort((a, b) => b.score - a.score);
  if (!scores.length) return { industry: null, confidence: 0, alternatives: [], matched: [],
    why: "Nothing in that description matched an industry I know, which is fine; I can work from what you do rather than a label." };
  const top = scores[0], second = scores[1];
  const margin = top.score - (second ? second.score : 0);
  /* a lone weak noun like "office" is not evidence of an industry; say so and ask */
  const hasStrong = top.matched.some((w) => (INDUSTRY_SIGNALS[top.id].strong || []).some((sw) => w.startsWith(sw.trim().slice(0, 5))));
  if (!hasStrong && top.score <= 2) return { industry: null, confidence: 0, alternatives: [], matched: [], multi: null,
    why: "Nothing in that clearly names an industry, so it is better to ask than to guess." };
  const confidence = Math.min(0.98, top.score / (top.score + 4) + (margin >= 3 ? 0.2 : 0));
  const label = (id) => INDUSTRY_LABEL[id] || INDUSTRY_LABEL_EXTRA[id] || id;
  return { industry: top.id, confidence, alternatives: scores.slice(1, 3).map((x) => x.id), matched: top.matched,
    /* when two industries are close, say so rather than pretending certainty */
    multi: second && margin <= 1 ? [top.id, second.id] : null,
    why: `"${top.matched.slice(0, 3).join('", "')}" points at ${label(top.id)}${second && margin < 3 ? `, though ${label(second.id)} is close` : ""}.` };
}
function extractGoals(text) {
  const hay = norm(text);
  return Object.entries(GOAL_SIGNALS).map(([id, words]) => ({ id, n: words.filter((w) => hit(hay, w)).length }))
    .filter((x) => x.n > 0).sort((a, b) => b.n - a.n).map((x) => x.id);
}
function extractChannels(text) {
  const clean = stripNegated(text);
  return Object.entries(CHANNEL_PATTERNS).filter(([, re2]) => re2.test(clean)).map(([id]) => id);
}
function extractSize(text) { const f = SIZE_SIGNALS.find((s2) => s2.re.test(text || "")); return f ? { id: f.id, label: f.label } : null; }
function extractVolume(text) {
  const m = String(text || "").match(VOLUME_RE);
  if (!m) return null;
  const n = parseInt(m[1], 10), per = m[2] || "month";
  const monthly = per === "day" ? n * 30 : per === "week" ? n * 4 : n;
  return { raw: n, per, monthly };
}
/* pull everything out of one sentence at once, so we never re-ask what was said */
function understand(text) {
  const cls = classifyIndustry(text);
  const acts = detectActs(text);
  return { text, industry: cls.industry, confidence: cls.confidence, alternatives: cls.alternatives, why: cls.why,
    multi: cls.multi, matched: cls.matched,
    goals: extractGoals(text), channels: extractChannels(text), size: extractSize(text), volume: extractVolume(text),
    location: extractLocation(text), languages: extractLanguages(text), tools: extractTools(text), hours: extractHours(text),
    /* deeper discovery: everything a consultant would pick up from the same sentence */
    name: extractBusinessName(text), model: extractModel(text), branches: extractBranches(text), team: extractTeam(text),
    leadSources: extractLeadSources(text), dealValue: extractDealValue(text), cycle: extractCycle(text),
    repetitive: extractRepetitive(text), supportTopics: extractSupportTopics(text),
    autonomyPref: extractAutonomyPref(text), knowledge: extractKnowledge(text),
    acts,
    isQuestion: acts.includes("question"), isUnsure: acts.includes("unsure"),
    isCorrection: acts.includes("correction"), isConfirm: acts.includes("confirm"),
    isFrustrated: acts.includes("frustrated"), isImpatient: acts.includes("impatient"),
    isGreeting: acts.includes("greeting"), isSmalltalk: acts.includes("smalltalk"),
    /* a description with no recognisable signal at all is worth treating differently
       from one we simply could not classify into a known industry */
    /* non Latin scripts are real language, not emptiness; only true blanks count */
    isEmpty: !String(text || "").trim().replace(/[^\p{L}\p{N}]/gu, "").length,
    /* the vowel test only applies to Latin script, otherwise Tamil and Arabic read as noise */
    isGibberish: (() => {
      const t = String(text || "").trim();
      const latinOnly = /^[\x00-\x7F]*$/.test(t);
      return latinOnly && t.length > 3 && !/[aeiou]/i.test(t.replace(/\s/g, ""));
    })(),
    /* a script we cannot parse for keywords is still a person trying to talk to us */
    nonLatin: /[^\x00-\x7F]/.test(String(text || "")) && !/[a-z]{3}/i.test(String(text || "")),
  };
}
/* the next question is whatever is still missing and matters most */
/* ==================================================================== */
/* BUSINESS DISCOVERY                                                    */
/* Extra extractors, an adaptive question bank and a blueprint. The bank */
/* is scored per business, so a clinic is asked about no shows and a shop */
/* is asked about returns; nothing is asked twice and nothing irrelevant  */
/* is asked at all.                                                      */
/* ==================================================================== */

const nrm = (t) => " " + String(t || "").toLowerCase().replace(/[^\p{L}\p{N}\s+@.-]/gu, " ").replace(/\s+/g, " ") + " ";
const anyOf = (t, list) => list.some((w) => nrm(t).includes(" " + w) || nrm(t).includes(w + " "));

/* --- who they sell to --- */
const extractModel = (t) => /\bb2b2c\b/i.test(t) ? "b2b2c"
  : /\bb2b\b|business(es)? (to|for)|wholesale|enterprise client|corporate client|other business/i.test(t) ? "b2b"
  : /\bb2c\b|consumer|walk ?in|general public|retail customer|individual/i.test(t) ? "b2c" : null;
const extractBranches = (t) => { const m = String(t || "").match(/(\d+)\s*(?:branch|outlet|location|clinic|store|studio|centre|center|showroom|site|chair|bay|room)s?\b/i); return m ? parseInt(m[1], 10) : null; };
const extractTeam = (t) => {
  const m = String(t || "").match(/(\d+)\s*(?:people|staff|employees?|agents?|reps?|team members?|dentists?|doctors?|therapists?|stylists?|trainers?|technicians?)\b/i);
  if (m) return parseInt(m[1], 10);
  if (/\b(just|only) me\b|myself|solo|one person|sole trader|freelance/i.test(t)) return 1;
  const w = String(t || "").match(/\b(two|three|four|five|six|seven|eight|nine|ten)\b/i);
  return w ? { two: 2, three: 3, four: 4, five: 5, six: 6, seven: 7, eight: 8, nine: 9, ten: 10 }[w[1].toLowerCase()] : null;
};
/* --- where leads come from --- */
const LEAD_SOURCE_SIGNALS = { website: /\bwebsite|web ?site|our site|landing page\b/i, whatsapp: /\bwhats ?app\b/i,
  instagram: /\binstagram|insta\b|\big\b|dms?\b/i, facebook: /\bfacebook|\bfb\b|messenger\b/i,
  phone: /\bphone|call(s|ing)?|hotline|landline\b/i, email: /\be ?mail|gmail|outlook\b/i,
  walkin: /\bwalk ?ins?|footfall|passing trade\b/i, ads: /\bads?\b|advertis|google ads|meta ads|ppc|paid\b/i,
  referral: /\breferr?als?|word of mouth|recommend/i, marketplace: /\bportal|marketplace|amazon|justdial|zomato|99acres\b/i };
const extractLeadSources = (t) => Object.entries(LEAD_SOURCE_SIGNALS).filter(([, re]) => re.test(String(t || ""))).map(([k]) => k);
/* --- deal shape --- */
const extractDealValue = (t) => { const m = String(t || "").match(/(?:average|typical|avg|around|about)?\s*(?:deal|order|ticket|sale|invoice|job|basket)?\s*(?:value|size|is|of)?\s*[₹$€£]\s?([\d,]+)\s*(k|lakh|crore|m)?/i);
  if (!m) return null; let n = parseInt(m[1].replace(/,/g, ""), 10);
  const mult = { k: 1e3, lakh: 1e5, crore: 1e7, m: 1e6 }[(m[2] || "").toLowerCase()]; return mult ? n * mult : n; };
const extractCycle = (t) => { const m = String(t || "").match(/(\d+)\s*(day|week|month)s?\b/i); return m ? { n: +m[1], unit: m[2].toLowerCase() } : null; };
/* --- operations --- */
const REPETITIVE = { follow_up: /follow ?up|chas(e|ing)|remind(ing)? (leads|customers)/i,
  reminders: /reminder|confirm(ation|ing)? (call|message)/i, order_updates: /order (update|status)|where is my order|tracking/i,
  payments: /payment reminder|invoice|overdue|collect(ion)?s?/i, feedback: /feedback|review request|survey/i,
  renewals: /renewal|expiry|subscription reminder/i, onboarding: /onboard(ing)?|welcome (message|pack)/i,
  data_entry: /data entry|typing|copy ?paste|spreadsheet|manual(ly)? (enter|updat)/i,
  scheduling: /schedul(e|ing)|book(ing)? (calls|slots)|calendar juggl/i };
const extractRepetitive = (t) => Object.entries(REPETITIVE).filter(([, re]) => re.test(String(t || ""))).map(([k]) => k);
/* --- support --- */
const extractSupportTopics = (t) => {
  const map = { pricing: /price|pricing|cost|quote|how much/i, availability: /availab|open|timing|hours|slot/i,
    order_status: /where is my order|status|tracking|delivery/i, returns: /return|refund|exchange|warranty/i,
    booking: /book|appointment|reschedul|cancel/i, technical: /not working|broken|issue|fault|error/i,
    payment: /payment|invoice|billing|receipt/i };
  return Object.entries(map).filter(([, re]) => re.test(String(t || ""))).map(([k]) => k);
};
/* --- autonomy preference, asked in plain language --- */
const extractAutonomyPref = (t) => {
  if (/approve|check first|review (it|them)|draft|suggest|see before|my approval/i.test(t)) return 1;
  /* routine is a narrower claim than full autonomy, so it is tested first */
  if (/routine|simple (stuff|things)|easy ones|straightforward/i.test(t)) return 2;
  if (/handle (it|them)|automatic|on its own|go ahead|don.?t ask|just do/i.test(t)) return 3;
  return null;
};
/* --- knowledge sources they mention --- */
const extractKnowledge = (t) => {
  const out = [];
  const url = String(t || "").match(/\b((?:https?:\/\/)?[a-z0-9-]+\.(?:com|net|org|io|co|in|sg|ae|uk|shop|store)(?:\.[a-z]{2})?(?:\/\S*)?)/i);
  if (url) out.push({ kind: "website", value: url[1] });
  if (/faq/i.test(t)) out.push({ kind: "faq" });
  if (/price list|pricing|rate card|menu|catalog(ue)?/i.test(t)) out.push({ kind: "pricing" });
  if (/polic(y|ies)|terms|refund policy|cancellation/i.test(t)) out.push({ kind: "policies" });
  if (/brochure|manual|guide|document|pdf/i.test(t)) out.push({ kind: "documents" });
  return out;
};
const extractBusinessName = (t) => {
  const m = String(t || "").match(/\b(?:we(?:'| a)?re|company|business|clinic|shop|store|firm|called|named)\s+([A-Z][\w&.'-]*(?:\s+[A-Z][\w&.'-]*){0,3})/);
  return m ? m[1].trim() : null;
};

/* does this business book time with customers at all? */
const APPOINTMENT_INDUSTRIES = ["healthcare","dental","salon","fitness","wellness","veterinary","automotive","realestate","education","legal","accounting","services","photography","childcare","petcare","coworking","hospitality"];
const usesAppointments = (f) => {
  if (f.appointments === false) return false;
  if (f.appointments === true) return true;
  return APPOINTMENT_INDUSTRIES.includes(f.industry);
};
const sellsProducts = (f) => ["retail","furniture","printing","pharmacy","manufacturing"].includes(f.industry);

/* ---- adaptive question bank ----
   Each entry declares what it fills, when it is relevant, and its discovery
   level. nextQuestion picks the highest value question that is relevant,
   unanswered and not inferable, so no two businesses get the same interview. */
const DISCOVERY = [
  /* level 1: identity, customers, goals, channels */
  { id: "industry", level: 1, filled: (f) => !!f.industry,
    ask: () => "What does your business do? Describe it however you like." },
  { id: "offering", level: 1, filled: (f) => !!f.offering,
    when: (f) => !!f.industry,
    ask: (f) => `What do customers actually pay you for, and who typically buys it?` },
  { id: "goals", level: 1, filled: (f) => (f.goals || []).length > 0,
    ask: (f) => {
      const ex = { healthcare: "missed calls, no shows, the front desk drowning",
        retail: "where is my order questions, abandoned baskets, returns",
        realestate: "portal enquiries going cold, chasing viewings",
        hospitality: "reservations by phone, no shows, table gaps",
        services: "quotes going quiet, chasing proposals",
        education: "admission enquiries, parent questions, follow ups",
        salon: "no shows, rebooking, filling quiet hours",
        fitness: "member retention, class bookings, lapsed members",
        automotive: "service bookings, test drive enquiries",
        nonprofit: "donor follow ups, volunteer coordination" }[f.industry];
      return ex ? `What is costing you the most right now? For a ${industryLabel(f.industry)} business it is often ${ex}.`
                : "What is costing you the most right now?";
    } },
  { id: "channels", level: 1, filled: (f) => (f.channels || []).length > 0,
    ask: () => "Where do customers reach you today?" },
  { id: "size", level: 1, filled: (f) => !!f.size || !!f.team,
    ask: () => "How many people are in the team?" },

  /* level 2: how the business actually runs, industry aware */
  { id: "leadflow", level: 2, filled: (f) => (f.leadSources || []).length > 0,
    ask: () => "Where do new enquiries usually come from, and roughly how many a week?" },
  { id: "appointments", level: 2, filled: (f) => f.apptDetail !== undefined,
    when: (f) => usesAppointments(f),
    ask: (f) => f.industry === "healthcare" ? "How do patients book today, and what happens when someone does not turn up?"
      : f.industry === "salon" ? "How do clients book, and what do you do about no shows?"
      : f.industry === "realestate" ? "How are viewings arranged, and who runs them?"
      : f.industry === "automotive" ? "How are test drives and service bookings handled today?"
      : "How do customers book time with you, and what happens when someone cancels late?" },
  { id: "orders", level: 2, filled: (f) => f.orderDetail !== undefined,
    when: (f) => sellsProducts(f) || f.industry === "hospitality",
    ask: (f) => sellsProducts(f) ? "What do customers ask most after ordering, and how do you handle returns?"
      : "How do orders and reservations reach you today?" },
  { id: "sales", level: 2, filled: (f) => f.salesDetail !== undefined,
    when: (f) => (f.goals || []).some((g) => ["sales","qualify","revenue","leads"].includes(g)) || f.model === "b2b",
    ask: () => "Walk me through what happens between a first enquiry and a sale, and how many follow ups it usually takes." },
  { id: "support", level: 2, filled: (f) => (f.supportTopics || []).length > 0 || f.supportDetail !== undefined,
    ask: () => "What do customers ask you over and over, and what must always reach a person instead?" },
  { id: "repetitive", level: 2, filled: (f) => (f.repetitive || []).length > 0,
    ask: () => "What repetitive work eats the most time in a normal week?" },

  /* level 3: configuration choices, only once the basics are known */
  { id: "autonomy", level: 3, filled: (f) => f.autonomyPref !== null && f.autonomyPref !== undefined,
    ask: () => "Would you rather BUZZZ drafted replies for you to approve, or handled the routine ones by itself?" },
  { id: "knowledge", level: 3, filled: (f) => (f.knowledge || []).length > 0,
    ask: () => "What should BUZZZ know about your business? A website, price list or FAQ is enough to start." },
  { id: "hours", level: 3, filled: (f) => !!f.hours || f.afterHours !== undefined,
    when: (f) => (f.goals || []).includes("speed") || (f.channels || []).length > 0,
    ask: () => "What are your usual hours, and what should happen to messages that arrive outside them?" },
];

/* how complete the picture is, per level */
function discoveryState(f) {
  const rel = DISCOVERY.filter((q) => !q.when || q.when(f));
  const byLevel = (n) => rel.filter((q) => q.level === n);
  const done = (list) => list.filter((q) => q.filled(f)).length;
  return { l1: { done: done(byLevel(1)), total: byLevel(1).length },
    l2: { done: done(byLevel(2)), total: byLevel(2).length },
    l3: { done: done(byLevel(3)), total: byLevel(3).length },
    asked: f.asked || [] };
}
/* the business blueprint assembled from everything learned */
function buildBlueprint(f) {
  const model = f.model || null;
  return {
    profile: { name: f.name || null, industry: f.industry || null, label: industryLabel(f.industry),
      offering: f.offering || null, model, locations: f.branches || null, team: f.team || f.size || null,
      location: f.location || null, languages: f.languages || [], hours: f.hours || null },
    customers: { sources: f.leadSources || [], topics: f.supportTopics || [], model },
    sales: { detail: f.salesDetail || null, dealValue: f.dealValue || null, cycle: f.cycle || null },
    support: { topics: f.supportTopics || [], escalate: f.escalate || null },
    appointments: usesAppointments(f) ? { relevant: true, detail: f.apptDetail || null } : { relevant: false },
    communication: { channels: f.channels || [], hours: f.hours || null, afterHours: f.afterHours || null },
    operations: { repetitive: f.repetitive || [] },
    goals: f.goals || [],
    knowledge: f.knowledge || [],
    integrations: f.tools || [],
    autonomy: f.autonomyPref || null,
  };
}
/* is there enough to build a workspace that will actually be useful? */
function blueprintReady(f) {
  const st = discoveryState(f);
  const essentials = st.l1.done >= st.l1.total;                 // identity, offering, goals, channels, team
  const operational = st.l2.done >= Math.min(3, st.l2.total);   // at least three operational answers
  return { ready: essentials && operational, state: st,
    missing: DISCOVERY.filter((q) => (!q.when || q.when(f)) && !q.filled(f) && q.level <= 2).map((q) => q.id) };
}

const ONBOARD_SLOTS = [
  { id: "industry", ask: "What does your business do? Describe it however you like.", filled: (f) => !!f.industry },
  { id: "goals",    ask: "What is costing you the most right now?", filled: (f) => (f.goals || []).length > 0 },
  { id: "channels", ask: "Where do customers reach you today?", filled: (f) => (f.channels || []).length > 0 },
  { id: "size",     ask: "How many people are in the team?", filled: (f) => !!f.size },
];
function nextQuestion(facts) {
  const f = facts || {};
  const asked = f.asked || [];
  /* relevant, unanswered, not already asked, and level appropriate:
     level 2 only opens once level 1 is complete, level 3 once level 2 is usable */
  const st = discoveryState(f);
  const maxLevel = st.l1.done < st.l1.total ? 1 : st.l2.done < Math.min(3, st.l2.total) ? 2 : 3;
  const pick = (lvl) => DISCOVERY.filter((q) =>
    q.level <= lvl && (!q.when || q.when(f)) && !q.filled(f) && !asked.includes(q.id));
  /* if everything at this level has been asked, open the next one rather than
     dead-ending on a slot the person chose not to answer */
  /* a hard ceiling so discovery stays a conversation, never a questionnaire:
     once the blueprint is usable, stop asking optional level 3 questions */
  const MAX_QUESTIONS = 9;
  if (asked.length >= MAX_QUESTIONS) return null;
  if (blueprintReady(f).ready && asked.length >= 7) return null;
  let candidates = pick(maxLevel);
  if (!candidates.length && maxLevel < 3) candidates = pick(maxLevel + 1);
  if (!candidates.length && maxLevel < 3) candidates = pick(3);
  if (!candidates.length) return null;
  /* prefer the lowest level, so identity is settled before configuration */
  candidates.sort((a, b) => a.level - b.level);
  const slot = candidates[0];
  return { ...slot, id: slot.id, ask: typeof slot.ask === "function" ? slot.ask(f) : slot.ask };
}

/* merge new understanding into what we already know, without losing anything */
function mergeFacts(facts, u) {
  const out = { ...facts,
    industry: facts.industry || u.industry,
    confidence: Math.max(facts.confidence || 0, u.confidence || 0),
    alternatives: u.alternatives && u.alternatives.length ? u.alternatives : facts.alternatives,
    goals: [...new Set([...(facts.goals || []), ...(u.goals || [])])],
    channels: [...new Set([...(facts.channels || []), ...(u.channels || [])])],
    size: facts.size || u.size, volume: facts.volume || u.volume,
    said: [...(facts.said || []), u.text].filter(Boolean),
  };
  /* deeper discovery: lists merge, scalars fill the first time, nothing is lost */
  ["leadSources", "repetitive", "supportTopics", "knowledge"].forEach((key) => {
    if ((u[key] || []).length) out[key] = [...new Set([...(out[key] || []), ...(u[key] || [])])];
  });
  ["name", "model", "branches", "team", "dealValue", "cycle", "autonomyPref", "hours", "location"].forEach((key) => {
    if (u[key] !== null && u[key] !== undefined && (out[key] === null || out[key] === undefined)) out[key] = u[key];
  });
  if (u.tools && u.tools.length) out.tools = [...new Set([...(out.tools || []), ...u.tools])];
  if (u.languages && u.languages.length) out.languages = [...new Set([...(out.languages || []), ...u.languages])];
  /* the question we just asked counts as answered, so it is never repeated */
  if (facts.pending) {
    out.asked = [...new Set([...(facts.asked || []), facts.pending])];
    const slot = DISCOVERY.find((q) => q.id === facts.pending);
    if (slot && !slot.filled(out) && String(u.text || "").trim().length > 2) {
      /* they answered in their own words; keep it so discovery advances rather than loops */
      const store = { offering: "offering", appointments: "apptDetail", orders: "orderDetail",
        sales: "salesDetail", support: "supportDetail", hours: "afterHours",
        leadflow: "leadflowDetail", repetitive: "repetitiveDetail", knowledge: "knowledgeDetail" }[facts.pending];
      if (store) out[store] = String(u.text).trim().slice(0, 240);
    }
    out.pending = null;
  }
  return out;
}

/* answer questions asked during onboarding instead of ignoring them */
/* What it can answer. Ordered, first match wins, so specific beats general. */
const ONBOARD_FAQ = [
  /* about the setup itself */
  { re: /how (long|much time)|how quick|time.*(take|need)/i, a: "About two minutes. I ask three or four things, then build your agents, workflows and CRM around your answers." },
  { re: /\b(skip|no questions|just build|do it for me|hurry)\b/i, a: "Happy to. Tell me in one line what your business does and I will make sensible choices for the rest, all of which you can change afterwards." },
  { re: /(change|edit|later|wrong|undo|redo|start over)/i, a: "Everything is editable afterwards, and you can rerun this setup from Settings. Agents arrive paused, so nothing reaches a customer until you activate them." },
  { re: /(what.*(you (need|ask))|why.*(ask|question))/i, a: "Only what changes the setup: what you do, what is hurting, where customers reach you, and roughly how big the team is. Nothing else." },

  /* commercial */
  { re: /(cost|price|pricing|how much|free|trial|charge|billing|subscri)/i, a: "Pricing is set per region rather than converted, and you can see your region's plans in Settings once you are in. Nothing in this setup commits you to anything." },
  { re: /(contract|cancel|lock.?in|commit|refund)/i, a: "You can change or cancel your plan from Settings. Nothing here signs you up to anything." },

  { re: /(migrat|import|move (my |our )?(data|contacts?)|move from|switch (from|over)|existing (crm|data)|spreadsheet|from (zoho|hubspot|salesforce|excel|sheets))/i,
    a: "You can import contacts from a CSV with column mapping and duplicate detection, and connect HubSpot, Salesforce or Zoho to sync rather than copy, so nothing is retyped." },
  /* trust and safety */
  { re: /(safe|secure|data|privacy|gdpr|compliance|where.*(stored|data)|encrypt)/i, a: "Your data stays in your workspace, provider keys are held server side, and every AI action is permission checked and written to an audit trail. You set the ceiling for what the AI may do on its own." },
  { re: /(hallucinat|make.*up|invent|wrong answer|accurate|lie)/i, a: "Agents answer from knowledge sources you approve. When nothing relevant is found they say so and hand to a human rather than guessing, and every answer carries the source it came from." },
  { re: /(control|approve|permission|autonomy|oversight|supervis)/i, a: "You set an autonomy ceiling for the whole workspace, then per agent permissions inside it. Anything above that limit waits in the Approval Center with the reason attached." },
  { re: /(human|takeover|take over|escalat|handover)/i, a: "Any conversation can be taken over instantly, and agents escalate on their own when someone is angry, asks for a person, or raises something outside their remit." },

  /* capability */
  { re: /(what can you do|what do you do|capab|features|help me with)/i, a: "I answer messages and calls, qualify leads, book appointments, chase quotes, run campaigns and keep the CRM current, all inside the limits you set." },
  { re: /(whatsapp|wa business)/i, a: "Yes, through GoWhats. Inbound and outbound, templates, media, and the conversation lands in the same inbox as everything else." },
  { re: /\b(calls?|calling|voice|phones?|telephone|ivr)\b/i, a: "Yes, through MrAssistant.ai. Inbound and outbound calls, with recordings, transcripts and a summary written back to the customer record." },
  { re: /(instagram|facebook|social|linkedin|tiktok)/i, a: "Instagram and Facebook messages and comments come into the same inbox, and you can plan and publish content from the Social section." },
  { re: /(email|gmail|outlook)/i, a: "Yes. Email sits alongside WhatsApp and calls in one inbox, so a customer is one conversation rather than three." },
  { re: /(sms|text message)/i, a: "Yes, SMS is supported as a channel for both replies and campaigns." },
  { re: /(website|web ?chat|widget|form)/i, a: "You get an embeddable form and web chat, and a submission creates the contact, assigns an owner and starts a follow up sequence automatically." },
  { re: /(appointment|booking|calendar|schedul)/i, a: "Yes. Real availability with staff hours, breaks, buffers and travel, plus reminders and confirmation chasing to cut no shows." },
  { re: /\b(quotes?|quotations?|proposals?|invoices?|invoicing|estimates?|billing document)\b/i, a: "You can build quotes from a price book with line items, discounts and tax. Invoicing itself is not built in yet, but an accepted quote closes its deal automatically and can hand off to your accounting tool." },
  { re: /(campaign|broadcast|bulk|blast|newsletter)/i, a: "Yes, with audience building from your real CRM data, opt out handling, quiet hours and per recipient delivery tracking." },
  { re: /(report|analytic|dashboard|metric|kpi)/i, a: "Every figure is computed from your records rather than sampled, including attribution, funnel drop off and cost per outcome." },
  { re: /(integrat|connect|api|zapier|webhook|shopify|woocommerce|hubspot|salesforce|zoho|stripe|razorpay|calendly|quickbooks|xero|zendesk|intercom|notion|slack|tally|pipedrive|freshworks)/i,
    a: "Yes. It connects to GoWhats, MrAssistant.ai, Google Calendar, Gmail, Stripe, Shopify, HubSpot and Salesforce, with field mapping and two way sync where the other side supports it, plus outbound webhooks for anything not on that list." },
  { re: /(team|user|seat|role|permission)/i, a: "Add as many teammates as your plan allows, each with a role that controls what they can see, edit and approve, down to individual field level." },
  { re: /(language|multilingual|tamil|hindi|arabic|spanish|french|translat)/i, a: "The interface runs in eight languages including Tamil, Hindi, Arabic and Japanese, and agents can be told which languages to reply in." },
  { re: /(mobile|app|ios|android|phone app)/i, a: "It runs in the browser on any device. A dedicated mobile app is not part of this setup." },
  { re: /(offline|internet)/i, a: "It needs an internet connection, since messages, calls and your data live in your workspace rather than on the device." },
  { re: /(multiple|several|two) (business|brand|location|branch|outlet)/i, a: "Yes. You can run several brands or locations, each with its own agents, numbers and knowledge, while reporting rolls up across them." },
  { re: /(currenc|multi.?currency|dollar|rupee|euro)/i, a: "Deals and quotes keep their own currency, and reports convert into your reporting currency at the rate captured on the record's date." },

  /* how it works underneath */
  { re: /(how.*(work|does it)|behind|under the hood|which (ai|model)|chatgpt|openai|claude)/i, a: "You bring your own AI provider key, so usage bills to you directly and you choose the model. Different tasks route to different models: fast ones for replies, stronger ones for analysis." },
  { re: /(train|learn|teach|knowledge|document|pdf|upload)/i, a: "You give agents documents, FAQs and policies, and they answer only from what you approve, with the source shown next to the answer." },
  { re: /(replace|job|staff|fire|redundan)/i, a: "Most people use it to absorb the repetitive work, the after hours messages, the chasing, the same five questions, so their team spends time on the conversations that need a person." },

  /* meta */
  { re: /(are you (a )?(bot|robot|human|real|ai))/i, a: "I am the AI that sets up and runs your workspace. Right now I am listening to how your business works so I can build around it." },
  { re: /(who are you|what are you|your name)/i, a: "I am BUZZZ. I set this up, then I run the day to day inside it: answering, booking, chasing and keeping your records straight." },
];
/* an answer for almost anything: the FAQ first, then a topical fallback that is
   honest about not knowing rather than inventing a capability */
const onboardAnswer = (text) => {
  const f = ONBOARD_FAQ.find((x) => x.re.test(text || ""));
  if (f) return f.a;
  const t = String(text || "").toLowerCase();
  if (/\?\s*$/.test(t) || /^(what|how|why|can|does|is|do|will)\b/.test(t)) {
    /* name the nearest thing it does know, rather than a blank shrug */
    const topics = [["lead", "capturing and qualifying leads"], ["customer", "keeping every customer conversation in one place"],
      ["message", "messaging across WhatsApp, Instagram, email and SMS"], ["sale", "the sales pipeline, quotes and forecasting"],
      ["market", "campaigns and social content"], ["support", "support conversations and escalation"],
      ["staff", "team roles, permissions and shifts"], ["automat", "workflows that run on their own"]];
    const near = topics.find(([k]) => t.includes(k));
    return near
      ? `I am not certain I understood that one. What I can tell you is that BUZZZ handles ${near[1]}. Ask me more specifically and I will answer properly.`
      : "I am not sure about that specific thing, and I would rather say so than guess. Ask me about channels, pricing, data, control over the AI, or what happens after setup, and I can answer clearly.";
  }
  return null;
};

/* a plan built from the facts, with a reason attached to every piece */
/* every industry resolves to the closest plan archetype, so a cleaning company
   gets the field service shape rather than a generic one */
const PLAN_ARCHETYPE = {
  healthcare: "healthcare", pharmacy: "healthcare", veterinary: "healthcare", wellness: "healthcare", childcare: "healthcare",
  salon: "salon", fitness: "fitness", petcare: "salon",
  retail: "retail", crypto: "retail", printing: "retail", furniture: "retail",
  realestate: "realestate", rental: "realestate",
  education: "education",
  hospitality: "hospitality", travel: "hospitality", events: "hospitality",
  automotive: "automotive",
  nonprofit: "nonprofit", government: "nonprofit",
  legal: "services", accounting: "services", insurance: "services", finance: "services",
  recruitment: "services", agency: "services", saas: "services", media: "services",
  photography: "services", coworking: "services", services: "services",
  logistics: "services", manufacturing: "services", construction: "services",
  trades: "services", cleaning: "services", security: "services",
};
const planKeyFor = (ind) => PLAN_ARCHETYPE[ind] || "general";
const industryText = (ind) => INDUSTRY_LABEL[ind] || INDUSTRY_LABEL_EXTRA[ind] || "your business";

/* turn the blueprint into concrete workspace configuration: only what the
   business actually told us, so no speculative fields are created */
function blueprintConfig(bp) {
  const tags = [];
  (bp.customers.sources || []).forEach((src) => tags.push({ website: "Web enquiry", whatsapp: "WhatsApp", instagram: "Instagram",
    facebook: "Facebook", phone: "Phone", email: "Email", walkin: "Walk in", ads: "Paid ad", referral: "Referral",
    marketplace: "Marketplace" }[src] || src));
  if (bp.appointments.relevant) tags.push("Booked", "No show");
  if ((bp.support.topics || []).includes("returns")) tags.push("Return request");
  if ((bp.goals || []).includes("retention")) tags.push("Repeat customer");
  const segments = [];
  if (bp.appointments.relevant) segments.push({ name: "Missed appointments", rule: "tag = No show" });
  if ((bp.customers.sources || []).includes("referral")) segments.push({ name: "Referred", rule: "tag = Referral" });
  if ((bp.goals || []).includes("retention")) segments.push({ name: "Repeat customers", rule: "orders > 1" });
  if ((bp.goals || []).includes("recover")) segments.push({ name: "Gone quiet", rule: "no reply in 14 days" });
  /* escalation follows what they said must reach a person */
  const escalation = [];
  if (bp.profile.industry === "healthcare") escalation.push({ when: "clinical question", to: "human", priority: "high" });
  if ((bp.support.topics || []).includes("payment")) escalation.push({ when: "billing dispute", to: "human", priority: "high" });
  if ((bp.support.topics || []).includes("technical")) escalation.push({ when: "fault or complaint", to: "human", priority: "normal" });
  escalation.push({ when: "customer asks for a person", to: "human", priority: "high" });
  /* knowledge the person actually named, rather than generic placeholders */
  const knowledge = (bp.knowledge || []).map((k) => ({ website: "Website content", faq: "Frequently asked questions",
    pricing: "Prices and packages", policies: "Policies and terms", documents: "Documents and brochures" }[k.kind] || k.kind));
  return { tags: [...new Set(tags)], segments, escalation, knowledge: [...new Set(knowledge)],
    autonomy: bp.autonomy || null };
}

function composePlan(facts, lib) {
  const ind = facts.industry || "general";
  const base = lib[planKeyFor(ind)] || lib.general || { agents: [], workflows: [], integrations: [], crmTabs: [] };
  const goals = facts.goals || [];
  const channels = facts.channels && facts.channels.length ? facts.channels : ["whatsapp"];
  const agents = base.agents.map((a) => ({ ...a, why: `Standard for ${industryText(ind)}.` }));
  const add = (agent, why) => { if (!agents.some((a) => a.name.split(" ")[0] === agent.name.split(" ")[0])) agents.push({ ...agent, why }); };
  if (goals.includes("follow_up")) add({ name: "Mira — Follow up Agent", type: "followup", role: "Chase quotes and quiet leads, and stop the moment they reply.", autonomy: 2, channels }, "You said chasing is costing you.");
  if (goals.includes("never_miss") && channels.includes("voice")) add({ name: "Voz — Voice Agent", type: "voice", role: "Answer and return calls so nothing rings out.", autonomy: 2, channels: ["voice"] }, "You mentioned missed calls.");
  if (goals.includes("support")) add({ name: "Kai — Support Agent", type: "support", role: "Answer repetitive questions from your own documents and escalate the rest.", autonomy: 2, channels }, "You said the same questions keep coming.");
  if (goals.includes("qualify")) add({ name: "Rhea — Lead Qualification Agent", type: "lead_qual", role: "Qualify on budget, timeline and need before a person gets involved.", autonomy: 2, channels }, "You want fewer time wasters.");
  if (goals.includes("retention")) add({ name: "Sol — Retention Agent", type: "retention", role: "Spot lapsed customers and bring them back.", autonomy: 2, channels }, "You mentioned repeat business.");
  const workflows = [...(base.workflows || [])];
  if (goals.includes("more_bookings") && !workflows.includes("reminder")) workflows.push("reminder", "noshow");
  if (goals.includes("follow_up") && !workflows.includes("followup24")) workflows.push("followup24");
  if (goals.includes("retention") && !workflows.includes("winback")) workflows.push("winback");
  if (goals.includes("never_miss") && !workflows.includes("router")) workflows.push("router");
  /* autonomy recommendation scales with how much they are drowning */
  const heavy = (facts.volume && facts.volume.monthly >= 300) || goals.includes("scale");
  const autonomy = heavy ? 3 : 2;
  return { industry: ind, agents, workflows: [...new Set(workflows)], channels,
    integrations: base.integrations || [], crmTabs: base.crmTabs || ["Contacts", "Pipeline"],
    autonomy, autonomyWhy: heavy ? "Your volume is high enough that approving every action would slow you down, so Level 3 handles routine work and still asks before anything risky."
      : "Level 2 replies and organises on its own, and asks before anything that touches money or the calendar. Easy to raise later.",
    summary: `${agents.length} agents, ${[...new Set(workflows)].length} workflows and ${INDUSTRY_LABEL[ind] || INDUSTRY_LABEL_EXTRA[ind] ? "a " + industryText(ind) + " CRM setup" : "a CRM set up for how you work"}, on ${channels.map((c) => (CH[c] ? CH[c].label : c)).join(", ")}.` };
}

