const PLAN_TIERS = {
  starter: ["fast"],
  growth: ["fast", "mid"],
  scale: ["fast", "mid", "capable"],
  enterprise: ["fast", "mid", "capable", "frontier"],
};

/* ---- internal communication ----
   The team already lives in Slack or Discord. A notification they have to leave
   in order to act on is one they act on late, so the work comes to them:
   approve, deny, claim, all from the channel. Which events go where is a
   per-channel choice, because a team that gets everything turns it off. */
const TEAM_EVENTS = [
  { id: "approval.waiting",  label: "Approval needed",       note: "Work an agent prepared but may not send", urgency: "high" },
  { id: "escalation.raised", label: "Escalated to a person", note: "A customer needs someone now", urgency: "high" },
  { id: "sla.at_risk",       label: "SLA about to breach",   note: "Before it breaches, not after", urgency: "high" },
  { id: "agent.flagged",     label: "Agent needs attention", note: "Paused, or acting without guardrails", urgency: "medium" },
  { id: "deal.won",          label: "Deal won",              note: "The one everyone wants in the channel", urgency: "low" },
  { id: "handover.shift",    label: "Shift handover",        note: "What is open at the end of a shift", urgency: "low" },
];

const TEAM_PLATFORMS = [
  { id: "slack", label: "Slack", note: "Buttons in the channel. Approve without leaving Slack." },
  { id: "discord", label: "Discord", note: "The same, for teams that run on Discord." },
];

function TeamChatSettings({ value = {}, onChange, T }) {
  const links = value.links || [];
  const routes = value.routes || {};
  const [adding, setAdding] = useState(null);

  const setRoute = (event, patch) =>
    onChange({ ...value, routes: { ...routes, [event]: { ...(routes[event] || {}), ...patch } } });

  return (
    <div className="grid gap-3">
      <div className="grid gap-2 sm:grid-cols-2">
        {TEAM_PLATFORMS.map((p) => {
          const link = links.find((l) => l.platform === p.id);
          return (
            <div key={p.id} className={`rounded-xl p-3 ${T.card}`}>
              <div className="flex items-center gap-2">
                <span className={`text-[13px] font-semibold ${T.strong}`}>{p.label}</span>
                {link
                  ? <span className="text-[10px] px-1.5 rounded-full" style={{ background: RED_WASH, color: BRAND }}>connected</span>
                  : <span className={`text-[10px] px-1.5 rounded-full ${T.chip}`}>not connected</span>}
              </div>
              <div className={`text-[11.5px] mt-1 ${T.faint}`}>{link ? link.teamName || p.note : p.note}</div>
              <button onClick={() => setAdding(adding === p.id ? null : p.id)}
                className={`h-8 px-3 rounded-lg text-[12px] font-medium mt-2 border ${T.border} ${T.sub}`}>
                {link ? "Reconnect" : `Connect ${p.label}`}
              </button>
              {adding === p.id && (
                <div className={`text-[11.5px] mt-2 leading-relaxed ${T.faint}`}>
                  {/* said plainly rather than opening a flow that cannot finish */}
                  Connecting opens {p.label} to authorise BUZZZ. It needs the app credentials set on the server
                  first, so this is not available in this build.
                </div>
              )}
            </div>
          );
        })}
      </div>

      <div className={`rounded-xl p-3 ${T.card}`}>
        <div className={`text-[13px] font-semibold ${T.strong}`}>What gets posted, and where</div>
        <div className={`text-[11.5px] mt-0.5 mb-2 ${T.faint}`}>
          Send the things that need a person. Everything else is noise, and noise is why teams mute the channel.
        </div>
        <div className="grid gap-1.5">
          {TEAM_EVENTS.map((e) => {
            const r = routes[e.id] || {};
            return (
              <div key={e.id} className="flex items-center gap-2 flex-wrap py-1.5"
                style={{ borderTop: "1px solid rgba(0,0,0,0.05)" }}>
                <div className="flex-1 min-w-0">
                  <div className={`text-[12.5px] font-medium ${T.strong}`}>
                    {e.label}
                    {e.urgency === "high" && <span className="text-[10px] ml-1.5" style={{ color: BRAND }}>urgent</span>}
                  </div>
                  <div className={`text-[11px] ${T.faint}`}>{e.note}</div>
                </div>
                <input value={r.channel || ""} onChange={(ev) => setRoute(e.id, { channel: ev.target.value })}
                  placeholder="#channel"
                  className={`h-8 w-32 px-2 rounded-lg text-[12px] outline-none ${T.input}`} />
                <button onClick={() => setRoute(e.id, { on: !r.on })}
                  className={`h-8 px-3 rounded-lg text-[12px] font-medium border ${r.on ? "" : T.border} ${T.sub}`}
                  style={r.on ? { borderColor: BRAND, background: RED_WASH, color: BRAND } : undefined}>
                  {r.on ? "On" : "Off"}
                </button>
              </div>
            );
          })}
        </div>
      </div>

      <div className={`text-[11.5px] leading-relaxed ${T.faint}`}>
        Anyone can press a button in a channel, so BUZZZ checks who they are before it acts. Approving needs an
        owner, admin or manager, and the same rules that apply in the app apply there.
      </div>
    </div>
  );
}

function ModelChoice({ plan = "growth", value = {}, onChange, T }) {
  const tiers = PLAN_TIERS[plan] || PLAN_TIERS.starter;
  const [open, setOpen] = useState(null);
  /* which provider the person is looking inside, per function */
  const [viewing, setViewing] = useState({});

  return (
    <div className="grid gap-2">
      {AI_FUNCTIONS.map((f) => {
        const options = AI_CATALOG[f.id] || [];
        const affordable = options.filter(([, , tier]) => tiers.includes(tier));
        const chosen = value[f.id] || (affordable[0] || [])[0];
        const meta = options.find(([id]) => id === chosen);

        /* providers that have at least one model this plan can afford */
        const providers = [];
        affordable.forEach(([id]) => {
          const p = providerOfModel(id);
          if (!providers.includes(p)) providers.push(p);
        });
        const lockedProviders = [];
        options.forEach(([id, , tier]) => {
          const p = providerOfModel(id);
          if (!tiers.includes(tier) && !providers.includes(p) && !lockedProviders.includes(p)) lockedProviders.push(p);
        });
        const activeProvider = viewing[f.id] || (chosen ? providerOfModel(chosen) : providers[0]);

        return (
          <div key={f.id} className={`rounded-xl p-3 ${T.card}`}>
            <div className="flex items-center gap-3 flex-wrap">
              <div className="flex-1 min-w-0">
                <div className={`text-[13px] font-semibold ${T.strong}`}>
                  {f.label}{f.required && <span className="text-[10px] ml-1.5" style={{ color: BRAND }}>required</span>}
                </div>
                <div className={`text-[11.5px] ${T.faint}`}>{f.note}</div>
              </div>
              <button onClick={() => setOpen(open === f.id ? null : f.id)}
                className={`h-9 px-3 rounded-lg text-[12px] font-medium border ${T.border} ${T.sub}`}>
                {meta ? `${(MODEL_HOUSES[providerOfModel(chosen)] || {}).label || ""} · ${meta[1]}` : "Choose"}
              </button>
            </div>
            {meta && <div className={`text-[11px] mt-1.5 ${T.faint}`}>{meta[3]}</div>}

            {open === f.id && (
              <div className="mt-3">
                {/* step one: the provider */}
                <div className={`text-[10px] uppercase tracking-widest mb-1.5 ${T.faint}`}>Provider</div>
                <div className="flex flex-wrap gap-1.5">
                  {providers.map((p) => (
                    <button key={p} onClick={() => setViewing({ ...viewing, [f.id]: p })}
                      className={`h-8 px-2.5 rounded-lg text-[12px] font-medium border ${p === activeProvider ? "" : T.border} ${T.sub}`}
                      style={p === activeProvider ? { borderColor: BRAND, background: RED_WASH, color: BRAND } : undefined}>
                      {(MODEL_HOUSES[p] || {}).label || p}
                      <span className="opacity-60 ml-1">
                        {affordable.filter(([id]) => providerOfModel(id) === p).length}
                      </span>
                    </button>
                  ))}
                  {lockedProviders.map((p) => (
                    <span key={p} className={`h-8 px-2.5 rounded-lg text-[12px] inline-flex items-center border ${T.border} ${T.faint} opacity-50`}>
                      {(MODEL_HOUSES[p] || {}).label || p} · higher plan
                    </span>
                  ))}
                </div>
                {MODEL_HOUSES[activeProvider] && (
                  <div className={`text-[11px] mt-1.5 ${T.faint}`}>{MODEL_HOUSES[activeProvider].note}</div>
                )}

                {/* step two: a model from that provider */}
                <div className={`text-[10px] uppercase tracking-widest mt-3 mb-1.5 ${T.faint}`}>Model</div>
                <div className="grid gap-1.5">
                  {options.filter(([id]) => providerOfModel(id) === activeProvider).map(([id, label, tier, price]) => {
                    const locked = !tiers.includes(tier);
                    return (
                      <button key={id} disabled={locked}
                        onClick={() => { onChange({ ...value, [f.id]: id }); setOpen(null); }}
                        className={`text-left rounded-lg px-3 py-2 border disabled:opacity-45 ${id === chosen ? "" : T.border}`}
                        style={id === chosen ? { borderColor: BRAND, background: RED_WASH } : undefined}>
                        <div className="flex items-center gap-2 flex-wrap">
                          <span className={`text-[12.5px] font-medium ${T.strong}`}>{label}</span>
                          <span className={`text-[10px] px-1.5 rounded-full ${T.chip}`}>{tier}</span>
                          {locked && <span className="text-[10px]" style={{ color: BRAND }}>needs a higher plan</span>}
                        </div>
                        <div className={`text-[11px] mt-0.5 ${T.faint}`}>{price}</div>
                      </button>
                    );
                  })}
                </div>
              </div>
            )}
          </div>
        );
      })}
      <div className={`text-[11.5px] mt-1 ${T.faint}`}>
        Everything here is inside your plan's allowance. Credits are one currency across every function, so a
        cheap model on a routine job pays for a better one where it matters.
      </div>
    </div>
  );
}

function SettingsView() {
  const { T, dk, autonomy, setAutonomy, flash, ind, setIndustry, aiKeys, setAiKeys, ws, setWs, billing, setBilling,
    aiCfg, setAiCfg, escRules, setEscRules, notifRules, setNotifRules, usage, ent, changePlan, setSubState, setRegionByCountry,
    agents, wfs, camps, kb, activity, setConfirm, trail, log, conns, connOf,
    locale, setLocale, t, fx, setRate, queues, setQueues, shifts, setShifts, customFields, me } = useApp();
  const [sec, setSec] = useState("Workspace");
  const secs = ["Workspace", "Localisation", "Currency", "Queues", "AI models", "Team chat", "Permissions", "AI", "Escalation", "Notifications", "Billing", "Usage", "Security", "Danger zone"];
  const region = PRICING_REGIONS.find((r) => r.id === billing.region) || PRICING_REGIONS[0];
  const price = priceFor(billing.region, billing.plan, billing.cycle);
  const sub = SUB_STATES[billing.sub] || SUB_STATES.active;
  const cost = usageCost(usage);
  const counts = { agents: agents.filter((a) => a.status !== "Archived").length, workflows: wfs.length, campaigns: camps.length,
    contacts: CONTACTS.filter((c) => !c.archived).length, knowledge: kb.filter((k) => !k.archived).length, aiActions: usage.aiActions };

  const saveWs = (patch, label) => { setWs((w) => ({ ...w, ...patch })); trail("Workspace setting changed", label || Object.keys(patch)[0], String(ws[Object.keys(patch)[0]]), String(Object.values(patch)[0])); };

  const Bar = ({ used, allowed, label, unit }) => {
    const pct = usagePct(used, allowed);
    const projected = projectUsage(used);
    return (
      <div className="mb-3">
        <div className="flex items-baseline gap-2 text-[11px]">
          <span className="font-medium flex-1">{label}</span>
          <span className="tabular-nums">{used.toLocaleString()}{allowed !== Infinity ? " / " + allowed.toLocaleString() : ""} {unit}</span>
          {allowed !== Infinity && <span className={`tabular-nums w-10 text-right ${pct >= 90 ? "text-red-500" : pct >= 75 ? "text-amber-600" : T.faint}`}>{pct}%</span>}
        </div>
        <div className={`h-1.5 rounded-full overflow-hidden mt-1 ${dk ? "bg-zinc-800" : "bg-zinc-200"}`}>
          <div className="h-full transition-all" style={{ width: pct + "%", background: pct >= 90 ? "#dc2626" : pct >= 75 ? "#f59e0b" : BRAND }} />
        </div>
        {allowed !== Infinity && projected > allowed && <div className="text-[10px] text-amber-600 mt-0.5">On this pace you will reach {projected.toLocaleString()} by month end, which is over your allowance.</div>}
      </div>
    );
  };

  return (
    <div className="h-full flex min-h-0">
      <div className={`w-48 shrink-0 border-r overflow-y-auto bz-scroll ${T.border} ${T.panel} p-2`}>
        <SecTitle>Settings</SecTitle>
        {secs.map((x) => (
          <button key={x} onClick={() => setSec(x)} className={`w-full text-left px-2.5 py-1.5 rounded-lg text-xs font-medium mb-0.5 ${sec === x ? T.active : `${x === "Danger zone" ? "text-red-500" : T.sub} ${T.hover}`}`}>{x}</button>
        ))}
      </div>
      <div className="flex-1 overflow-y-auto bz-scroll p-6 max-w-3xl space-y-4">

        {sec === "Workspace" && (<>
          <div className={`rounded-2xl p-5 ${T.card}`}>
            <SecTitle>Identity</SecTitle>
            <div className="grid grid-cols-2 gap-3">
              <Field label="Company name"><input value={ws.name} onChange={(e) => saveWs({ name: e.target.value })} className={inputCls(T)} /></Field>
              <Field label="Industry pack"><input value={ind.name} readOnly className={inputCls(T) + " opacity-60"} /></Field>
              <Field label="Country" hint="Also sets your billing region."><select value={ws.country} onChange={(e) => setRegionByCountry(e.target.value)} className={inputCls(T)}>{COUNTRIES.map(([c, l]) => <option key={c} value={c}>{l}</option>)}</select></Field>
              <Field label="Currency" hint="Used for deal values and analytics."><select value={ws.currency} onChange={(e) => saveWs({ currency: e.target.value })} className={inputCls(T)}>{[...new Set(PRICING_REGIONS.map((r) => r.cur))].map((c) => <option key={c}>{c}</option>)}</select></Field>
            </div>
            <button onClick={() => { setIndustry(null); }} className={`mt-3 h-9 px-3 rounded-xl border text-xs font-semibold inline-flex items-center gap-1.5 ${T.chip} ${T.hover}`}><RefreshCw size={12} /> Rerun BUZZZ AI setup</button>
          </div>
          <div className={`rounded-2xl p-5 ${T.card}`}>
            <SecTitle>Time and working hours</SecTitle>
            <p className={`text-xs mb-3 ${T.sub}`}>Appointments, campaign quiet hours, workflow waits and analytics windows all use this. Changing it changes them.</p>
            <div className="grid grid-cols-2 gap-3">
              <Field label="Time zone"><select value={ws.tz} onChange={(e) => saveWs({ tz: e.target.value })} className={inputCls(T)}>{TZS.map((t) => <option key={t}>{t}</option>)}</select></Field>
              <Field label="Time format"><select value={ws.timeFmt} onChange={(e) => saveWs({ timeFmt: e.target.value })} className={inputCls(T)}><option>24h</option><option>12h</option></select></Field>
              <Field label="Opens"><input type="time" value={ws.hours.start} onChange={(e) => saveWs({ hours: { ...ws.hours, start: e.target.value } })} className={inputCls(T)} /></Field>
              <Field label="Closes"><input type="time" value={ws.hours.end} onChange={(e) => saveWs({ hours: { ...ws.hours, end: e.target.value } })} className={inputCls(T)} /></Field>
            </div>
            <div className="flex flex-wrap gap-1.5 mt-2">
              {["Mon", "Tue", "Wed", "Thu", "Fri", "Sat", "Sun"].map((d) => {
                const on = ws.hours.days.includes(d);
                return <button key={d} onClick={() => saveWs({ hours: { ...ws.hours, days: on ? ws.hours.days.filter((x) => x !== d) : [...ws.hours.days, d] } })}
                  className={`h-8 px-3 rounded-full border text-[11px] font-medium ${on ? "text-white border-transparent" : `${T.chip} ${T.hover}`}`} style={on ? { background: BRAND } : {}}>{d}</button>;
              })}
            </div>
          </div>
        </>)}

        {sec === "Localisation" && (
          <div className={`rounded-2xl p-5 ${T.card}`}>
            <SecTitle>Language</SecTitle>
            <p className={`text-xs mb-3 ${T.sub}`}>The interface language for this workspace. Right to left languages flip the whole layout.</p>
            <div className="grid grid-cols-2 md:grid-cols-4 gap-2">
              {Object.entries(LOCALES).map(([code, l]) => (
                <button key={code} onClick={() => { setLocale(code); trail("Interface language changed", ws.name, locale, code); flash(makeT(code)("save") + " · " + l.name); }}
                  className={`rounded-xl border p-3 text-left ${locale === code ? "" : T.border + " " + T.hover}`} style={locale === code ? { borderColor: BRAND } : {}}>
                  <div className="text-xs font-semibold">{l.name}</div>
                  <div className={`text-[10px] ${T.faint}`}>{code}{l.dir === "rtl" ? " · right to left" : ""}</div>
                </button>
              ))}
            </div>
            <div className={`rounded-xl p-3 mt-3 ${T.softcard}`} dir={localeDir(locale)}>
              <div className={`text-[10px] uppercase tracking-widest mb-1.5 ${T.faint}`}>Preview</div>
              <div className="flex gap-3 text-xs flex-wrap">
                {["contacts", "deals", "appointments", "quotes", "save", "search"].map((k) => (
                  <span key={k}><span className={T.faint}>{k}:</span> <span className="font-medium">{t(k)}</span></span>
                ))}
              </div>
              <div className={`text-[11px] mt-2 ${T.sub}`}>{fmtDateLocale(new Date(), locale)} · {fmtNumberLocale(1234567.89, locale)}</div>
            </div>
          </div>
        )}

        {sec === "Currency" && (<>
          <div className={`rounded-2xl p-5 ${T.card}`}>
            <SecTitle>Reporting currency</SecTitle>
            <p className={`text-xs mb-3 ${T.sub}`}>Deals and quotes keep their own currency. Reports convert into this one using the rate on the record's date, so a closed deal never changes value because the market moved.</p>
            <select value={ws.currency} onChange={(e) => saveWs({ currency: e.target.value })} className={inputCls(T) + " max-w-xs"}>
              {Object.entries(CURRENCIES).map(([c, m2]) => <option key={c} value={c}>{c} · {m2.name}</option>)}
            </select>
          </div>
          <div className={`rounded-2xl p-5 ${T.card}`}>
            <SecTitle right={<span className={`text-[10px] ${T.faint}`}>as of {fx.asOf}</span>}>Exchange rates</SecTitle>
            <p className={`text-xs mb-3 ${T.sub}`}>Per 1 {fx.base}. In production these refresh daily from a rate provider and every conversion stores the rate it used.</p>
            <div className="grid grid-cols-2 md:grid-cols-3 gap-2">
              {Object.entries(fx.rates).map(([code, rate]) => (
                <div key={code} className={`flex items-center gap-2 rounded-xl p-2.5 ${T.softcard}`}>
                  <span className="text-xs font-semibold w-12">{code}</span>
                  <input type="number" step="0.0001" value={rate} onChange={(e) => setRate(code, +e.target.value || 0)} className={`flex-1 h-7 px-2 rounded-lg text-[11px] outline-none ${T.input}`} />
                  <span className={`text-[10px] ${T.faint}`}>{fmtCurrency(100 * Math.pow(10, (CURRENCIES[code] || {}).decimals || 2) / 100 * 100, code)}</span>
                </div>
              ))}
            </div>
          </div>
        </>)}

        {sec === "Queues" && (<>
          <div className={`rounded-2xl p-5 ${T.card}`}>
            <SecTitle>Routing queues</SecTitle>
            <p className={`text-xs mb-3 ${T.sub}`}>Conversations are matched to a queue by channel and intent, then to a person who is actually on shift.</p>
            {queues.map((q) => (
              <div key={q.id} className={`rounded-xl border p-3 mb-2 ${T.border}`}>
                <div className="flex items-center gap-2 flex-wrap">
                  <span className="text-xs font-semibold flex-1">{q.name}</span>
                  <Pill c={T.chip}>{q.strategy === "load" ? "lightest workload" : "round robin"}</Pill>
                  <Pill c={T.chip}>SLA {q.slaMinutes}m</Pill>
                </div>
                <div className={`text-[11px] mt-1.5 ${T.faint}`}>
                  Channels: {q.channels.join(", ")} · Intents: {q.intents.join(", ")} · Members: {q.members.join(", ")} · Falls back to {q.fallback}
                </div>
              </div>
            ))}
          </div>
          <div className={`rounded-2xl p-5 ${T.card}`}>
            <SecTitle right={<Pill c="bg-emerald-50 text-emerald-700 border-emerald-200">{onDuty(shifts).length} on duty now</Pill>}>Shifts</SecTitle>
            {shifts.map((sh) => {
              const duty = onDuty(shifts).includes(sh.user);
              return (
                <div key={sh.id} className={`flex items-center gap-2.5 rounded-xl p-2.5 mb-1.5 ${T.softcard}`}>
                  <span className={`w-1.5 h-1.5 rounded-full ${duty ? "bg-emerald-500" : "bg-zinc-300"}`} />
                  <span className="text-xs font-medium w-32">{sh.user}</span>
                  <span className={`text-[11px] flex-1 ${T.faint}`}>{sh.days.join(" ")} · {sh.start}–{sh.end}</span>
                  <span className={`text-[10px] ${duty ? "text-emerald-600" : T.faint}`}>{duty ? "on shift" : "off"}</span>
                </div>
              );
            })}
            <p className={`text-[10px] mt-2 ${T.faint}`}>When nobody in a queue is on shift, the conversation waits and escalates to that queue's fallback rather than sitting unanswered.</p>
          </div>
        </>)}

        {sec === "Team chat" && (<>
              <p className={`text-xs ${T.sub}`}>
                Bring the work to where your team already is. BUZZZ posts what needs a person into Slack or
                Discord, and they can approve, deny or claim it without leaving.
              </p>
              <div className="mt-3">
                <TeamChatSettings value={ws.teamChat || {}} T={T}
                  onChange={(next) => saveWs({ teamChat: next }, "Team chat")} />
              </div>
            </>)}

            {sec === "AI models" && (<>
              <p className={`text-xs ${T.sub}`}>
                Pick a model per job. A cheap model on routine questions leaves credits for a better one where the
                answer actually matters. Your plan decides which are available.
              </p>
              <div className="mt-3">
                <ModelChoice plan={String(billing.plan || "growth").toLowerCase()} value={ws.aiModels || {}} T={T}
                  onChange={(next) => saveWs({ aiModels: next }, "AI models")} />
              </div>
            </>)}

            {sec === "Permissions" && (
          <div className={`rounded-2xl p-5 ${T.card}`}>
            <SecTitle right={<Pill c={T.chip}>you are {me.role}</Pill>}>Field level access</SecTitle>
            <p className={`text-xs mb-3 ${T.sub}`}>Fields are grouped by sensitivity. A role that cannot see a class never receives those fields, including through export.</p>
            <div className={`rounded-xl overflow-hidden border ${T.border}`}>
              <table className="w-full text-xs">
                <thead><tr className={`${T.faint} border-b ${T.border}`}>
                  <th className="px-3 h-8 text-left font-semibold uppercase tracking-wider text-[10px]">Role</th>
                  {["public", "contact", "internal", "financial"].map((c) => <th key={c} className="px-3 h-8 text-center font-semibold uppercase tracking-wider text-[10px]">{c}</th>)}
                </tr></thead>
                <tbody className={`divide-y ${T.divide}`}>
                  {Object.entries(ROLE_FIELD_ACCESS).map(([role, a]) => (
                    <tr key={role} className={role === me.role ? (dk ? "bg-zinc-900" : "bg-zinc-50") : ""}>
                      <td className="px-3 py-2 font-medium">{role}</td>
                      {["public", "contact", "internal", "financial"].map((c) => (
                        <td key={c} className="px-3 text-center">
                          {a.edit.includes(c) ? <span className="text-emerald-600 text-[10px] font-semibold">edit</span>
                            : a.see.includes(c) ? <span className={`text-[10px] ${T.sub}`}>view</span>
                            : <span className={`text-[10px] ${T.faint}`}>—</span>}
                        </td>
                      ))}
                    </tr>
                  ))}
                </tbody>
              </table>
            </div>
            <p className={`text-[10px] mt-2 ${T.faint}`}>Financial covers deal value, cost, margin and quota. Contact covers email, phone and location. Internal covers scores, lifetime value and notes.</p>
          </div>
        )}

        {sec === "AI" && (<>
          <div className={`rounded-2xl p-5 ${T.card}`}>
            <SecTitle right={<KeyRound size={13} style={{ color: BRAND }} />}>Providers</SecTitle>
            <p className={`text-xs mb-3 ${T.sub}`}>Buzzz runs on your own provider accounts, so usage bills to you directly. Keys are held server side and never returned to the browser in full.</p>
            {AI_PROVIDERS.map((p) => {
              const on = (aiCfg.enabled || []).includes(p.id);
              return (
                <div key={p.id} className={`rounded-xl border p-3 mb-2 ${T.border}`}>
                  <div className="flex items-center gap-2.5">
                    <Toggle on={on} set={(v) => { setAiCfg({ ...aiCfg, enabled: v ? [...aiCfg.enabled, p.id] : aiCfg.enabled.filter((x) => x !== p.id) }); trail("AI provider " + (v ? "enabled" : "disabled"), p.name, on ? "on" : "off", v ? "on" : "off"); }} />
                    <span className="text-xs font-semibold flex-1">{p.name}</span>
                    <span className={`text-[10px] ${T.faint}`}>{p.models.length} models</span>
                  </div>
                  {on && (
                    <div className="mt-2 flex gap-2">
                      <input type="password" value={aiKeys[p.keyField] || ""} onChange={(e) => setAiKeys({ ...aiKeys, [p.keyField]: e.target.value })} placeholder={p.id === "openweight" ? "endpoint URL" : "API key"} className={inputCls(T)} />
                      {aiKeys[p.keyField] ? <Pill c="bg-emerald-50 text-emerald-700 border-emerald-200"><Check size={9} /> set</Pill> : <Pill c={T.chip}>empty</Pill>}
                    </div>
                  )}
                </div>
              );
            })}
          </div>
          <div className={`rounded-2xl p-5 ${T.card}`}>
            <SecTitle>Model routing</SecTitle>
            <p className={`text-xs mb-3 ${T.sub}`}>Different work needs different models. The router picks one per task from what you have enabled, so nothing is hardcoded to a single vendor.</p>
            <div className="grid grid-cols-2 gap-3 mb-3">
              <Field label="Preferred model"><select value={aiCfg.primary} onChange={(e) => setAiCfg({ ...aiCfg, primary: e.target.value })} className={inputCls(T)}>
                {AI_PROVIDERS.filter((p) => aiCfg.enabled.includes(p.id)).flatMap((p) => p.models).map((m) => <option key={m.id} value={m.id}>{m.label}</option>)}
              </select></Field>
              <Field label="Fallback"><select value={aiCfg.fallback} onChange={(e) => setAiCfg({ ...aiCfg, fallback: e.target.value })} className={inputCls(T)}>
                {AI_PROVIDERS.filter((p) => aiCfg.enabled.includes(p.id)).flatMap((p) => p.models).map((m) => <option key={m.id} value={m.id}>{m.label}</option>)}
              </select></Field>
            </div>
            <div className="space-y-1">
              {Object.keys(AI_TASKS).map((t) => {
                const r = routeModel(t, aiCfg);
                return (
                  <div key={t} className={`flex items-center gap-2 rounded-lg px-2.5 py-1.5 text-[11px] ${T.softcard}`}>
                    <span className="flex-1">{AI_TASKS[t].label}</span>
                    <span className="font-medium">{r.model ? r.model.label : "none available"}</span>
                    {r.model && <span className={T.faint}>{r.model.reasoning ? "reasoning" : r.model.speed}</span>}
                  </div>
                );
              })}
            </div>
          </div>
          <div className={`rounded-2xl p-5 ${T.card}`}>
            <SecTitle>Workspace autonomy ceiling</SecTitle>
            <p className={`text-xs mb-3 ${T.sub}`}>The hard cap for every agent. Agents can sit lower but never higher, and lowering this downgrades the whole workforce immediately.</p>
            {AUTONOMY_LEVELS.map((o) => (
              <button key={o.l} onClick={() => { const prev = autonomy; setAutonomy(o.l); trail("Autonomy ceiling changed", ws.name, "Level " + prev, "Level " + o.l); log("You", "Autonomy ceiling changed", `Level ${prev} → Level ${o.l}`); flash(`Ceiling set to Level ${o.l}. Every agent is re-evaluated against it now.`); }}
                className={`w-full text-left flex items-start gap-2.5 p-2.5 rounded-xl mb-1 border ${autonomy === o.l ? (dk ? "border-red-800 bg-red-950/40" : "border-red-200 bg-red-50/50") : `border-transparent ${T.hover}`}`}>
                <span className="mt-0.5 w-3.5 h-3.5 rounded-full border-2 shrink-0" style={autonomy === o.l ? { borderColor: BRAND, background: BRAND } : { borderColor: dk ? "#3f3f46" : "#d4d4d8" }} />
                <div><div className="text-xs font-semibold">Level {o.l} · {o.name}</div><div className={`text-[11px] ${T.sub}`}>{o.d}</div></div>
              </button>
            ))}
          </div>
        </>)}

        {sec === "Escalation" && (
          <div className={`rounded-2xl p-5 ${T.card}`}>
            <SecTitle>When AI must involve a person</SecTitle>
            <p className={`text-xs mb-3 ${T.sub}`}>These are read by the agent runtime. Turning one off changes what agents do on the next conversation.</p>
            {escRules.map((r) => (
              <div key={r.id} className={`rounded-xl border p-3 mb-2 ${T.border}`}>
                <div className="flex items-center gap-2.5">
                  <Toggle on={r.on} set={(v) => { setEscRules(escRules.map((x) => x.id === r.id ? { ...x, on: v } : x)); trail("Escalation rule " + (v ? "enabled" : "disabled"), r.label, r.on ? "on" : "off", v ? "on" : "off"); }} />
                  <span className="text-xs font-medium flex-1">{r.label}</span>
                  {r.threshold !== null && (
                    <input type="number" step="0.1" value={r.threshold} onChange={(e) => setEscRules(escRules.map((x) => x.id === r.id ? { ...x, threshold: +e.target.value } : x))} className={`w-20 h-7 px-2 rounded-lg text-[11px] outline-none ${T.input}`} />
                  )}
                </div>
                {r.on && (
                  <div className="flex gap-2 mt-2 pl-11">
                    <select value={r.action} onChange={(e) => setEscRules(escRules.map((x) => x.id === r.id ? { ...x, action: e.target.value } : x))} className={`h-7 px-2 rounded-lg text-[10px] outline-none ${T.input}`}>
                      {["Hand to a human", "Require approval", "Notify only"].map((a) => <option key={a}>{a}</option>)}
                    </select>
                    <select value={r.team} onChange={(e) => setEscRules(escRules.map((x) => x.id === r.id ? { ...x, team: e.target.value } : x))} className={`h-7 px-2 rounded-lg text-[10px] outline-none ${T.input}`}>
                      {ROLES.map((a) => <option key={a}>{a}</option>)}
                    </select>
                  </div>
                )}
              </div>
            ))}
          </div>
        )}

        {sec === "Notifications" && (
          <div className={`rounded-2xl overflow-hidden ${T.card}`}>
            <div className={`px-5 py-4 border-b ${T.border}`}><SecTitle>Where each event goes</SecTitle></div>
            <table className="w-full text-xs">
              <thead><tr className={`${T.faint} border-b ${T.border}`}>{["Event", "In app", "Email", "WhatsApp"].map((h) => <th key={h} className="px-4 h-9 text-left font-semibold uppercase tracking-wider text-[10px]">{h}</th>)}</tr></thead>
              <tbody className={`divide-y ${T.divide}`}>
                {notifRules.map((r) => (
                  <tr key={r.id}>
                    <td className="px-4 py-2.5">{r.event}</td>
                    {["inApp", "email", "wa"].map((k) => (
                      <td key={k} className="px-4"><Toggle on={r[k]} set={(v) => setNotifRules(notifRules.map((x) => x.id === r.id ? { ...x, [k]: v } : x))} /></td>
                    ))}
                  </tr>
                ))}
              </tbody>
            </table>
          </div>
        )}

        {sec === "Billing" && (<>
          <div className={`rounded-2xl p-5 ${T.card}`}>
            <div className="flex items-start gap-3 flex-wrap">
              <div className="flex-1 min-w-0">
                <div className="flex items-center gap-2"><span className="text-lg font-semibold bz-display">{billing.plan}</span><Pill c={sub.tint}>{sub.label}</Pill></div>
                <div className={`text-xs mt-1 ${T.sub}`}>{price.label} · {region.label} · billed {billing.cycle}</div>
                <div className={`text-[11px] mt-0.5 ${T.faint}`}>{sub.entitled ? "Renews " + fmtD(new Date(billing.renewsAt)) : "Access is restricted until this is resolved."}</div>
              </div>
              <div className={`flex rounded-full border p-0.5 ${T.border}`}>
                {["monthly", "annual"].map((c) => <button key={c} onClick={() => setBilling({ ...billing, cycle: c })} className={`px-3 h-7 rounded-full text-[11px] font-semibold ${billing.cycle === c ? (dk ? "bg-zinc-800" : "bg-zinc-100") : T.sub}`}>{c}</button>)}
              </div>
            </div>
            {billing.cycle === "annual" && price.saving > 0 && (
              <p className="text-[11px] mt-2 text-emerald-600">Annual saves {region.sym}{price.saving.toLocaleString()} a year, which works out at {region.sym}{price.monthlyEquivalent.toLocaleString()} a month.</p>
            )}
            {billing.sub === "past_due" && (
              <div className="rounded-xl border border-amber-200 p-3 text-[11px] text-amber-700 mt-3">
                The last payment failed. You keep full access during the grace period, then the workspace becomes restricted. Update the payment method to clear this.
              </div>
            )}
          </div>

          <div className={`rounded-2xl p-5 ${T.card}`}>
            <SecTitle>Plans in {region.label}</SecTitle>
            <p className={`text-xs mb-3 ${T.sub}`}>Prices are set for each region rather than converted, and your billing country decides which apply.</p>
            <div className="grid grid-cols-1 md:grid-cols-2 gap-2">
              {PLANS.map((p) => {
                const pr = priceFor(billing.region, p, billing.cycle);
                const e = ENTITLEMENTS[p];
                const current = p === billing.plan;
                return (
                  <div key={p} className={`rounded-xl border p-3 ${current ? "" : T.border}`} style={current ? { borderColor: BRAND } : {}}>
                    <div className="flex items-baseline gap-2">
                      <span className="text-sm font-semibold flex-1">{p}</span>
                      <span className="text-sm font-semibold bz-display">{pr.amount === null ? "Custom" : region.sym + pr.amount.toLocaleString()}</span>
                    </div>
                    <div className={`text-[10px] mt-1 ${T.faint}`}>
                      {e.agents === Infinity ? "Unlimited agents" : e.agents + " agents"} · {e.aiActions === Infinity ? "custom AI" : e.aiActions.toLocaleString() + " AI actions"} · {e.users === Infinity ? "unlimited seats" : e.users + " seats"}
                    </div>
                    {current ? <div className="text-[10px] mt-2 font-semibold" style={{ color: BRAND }}>Current plan</div>
                      : <button onClick={() => setConfirm({ text: `Move to ${p}?`, detail: `Entitlements change immediately. ${PLANS.indexOf(p) < PLANS.indexOf(billing.plan) ? "Downgrading may put you over the new limits, which blocks creating more until you are back under them." : "Your new limits apply straight away."}`, yes: "Change plan", onYes: () => changePlan(p) })}
                        className={`mt-2 h-7 px-2.5 rounded-lg border text-[10px] font-semibold ${T.chip} ${T.hover}`}>{PLANS.indexOf(p) > PLANS.indexOf(billing.plan) ? "Upgrade" : "Downgrade"}</button>}
                  </div>
                );
              })}
            </div>
          </div>

          <div className={`rounded-2xl p-5 ${T.card}`}>
            <SecTitle>Subscription state</SecTitle>
            <p className={`text-xs mb-2 ${T.sub}`}>Checkout, invoices and payment methods are handled by the billing provider on the server; this artifact has no payment connection, so the states below are shown so you can see how each one affects entitlements.</p>
            <div className="flex flex-wrap gap-1.5">
              {Object.entries(SUB_STATES).map(([k, v]) => (
                <button key={k} onClick={() => setSubState(k)} className={`h-8 px-3 rounded-full border text-[11px] font-medium ${billing.sub === k ? "text-white border-transparent" : `${T.chip} ${T.hover}`}`} style={billing.sub === k ? { background: BRAND } : {}}>{v.label}</button>
              ))}
            </div>
          </div>
        </>)}

        {sec === "Usage" && (<>
          <div className={`rounded-2xl p-5 ${T.card}`}>
            <SecTitle right={<span className={`text-[10px] ${T.faint}`}>counted from your records</span>}>This month</SecTitle>
            <Bar used={usage.aiActions} allowed={ent.aiActions} label="AI actions" unit="" />
            <Bar used={counts.agents} allowed={ent.agents} label="Agents" unit="" />
            <Bar used={counts.workflows} allowed={ent.workflows} label="Workflows" unit="" />
            <Bar used={counts.contacts} allowed={ent.contacts} label="Contacts" unit="" />
            <Bar used={counts.knowledge} allowed={ent.knowledge} label="Knowledge sources" unit="" />
            <Bar used={counts.campaigns} allowed={ent.campaigns} label="Campaigns" unit="" />
          </div>
          <div className={`rounded-2xl p-5 ${T.card}`}>
            <SecTitle>Metered services</SecTitle>
            <p className={`text-xs mb-3 ${T.sub}`}>Voice, WhatsApp and messaging are charged on what you use, so they are never bundled as unlimited.</p>
            <div className="space-y-1.5 text-[11px]">
              {[["Voice minutes", usage.voiceMinutes, cost.voice], ["WhatsApp messages", usage.waSends, cost.wa], ["Email sends", usage.emailSends, cost.email], ["SMS sends", usage.smsSends, cost.sms], ["AI actions", usage.aiActions, cost.ai]].map(([k, n, c]) => (
                <div key={k} className="flex justify-between gap-3 py-1"><span className={T.sub}>{k}</span><span className="tabular-nums">{n.toLocaleString()} · {region.sym}{c.toFixed(2)}</span></div>
              ))}
              <div className={`flex justify-between gap-3 pt-2 border-t font-semibold ${T.border}`}><span>Estimated metered cost</span><span className="tabular-nums">{region.sym}{cost.total.toFixed(2)}</span></div>
            </div>
          </div>
          <div className={`rounded-2xl p-5 ${T.card}`}>
            <SecTitle>Spend controls</SecTitle>
            <div className="grid grid-cols-2 gap-3">
              <Field label="Monthly budget" hint="You are alerted as projected spend approaches this."><input type="number" value={billing.budget} onChange={(e) => setBilling({ ...billing, budget: +e.target.value || 0 })} className={inputCls(T)} /></Field>
              <Field label="Alert thresholds"><div className="flex gap-1.5 pt-1">{[50, 75, 90, 100].map((t) => {
                const on = (billing.alertAt || []).includes(t);
                return <button key={t} onClick={() => setBilling({ ...billing, alertAt: on ? billing.alertAt.filter((x) => x !== t) : [...billing.alertAt, t] })}
                  className={`h-8 px-2.5 rounded-full border text-[11px] font-medium ${on ? "text-white border-transparent" : `${T.chip} ${T.hover}`}`} style={on ? { background: BRAND } : {}}>{t}%</button>;
              })}</div></Field>
            </div>
            <label className="flex items-center gap-2.5 mt-3">
              <Toggle on={billing.hardCap} set={(v) => { setBilling({ ...billing, hardCap: v }); trail("Hard usage cap " + (v ? "enabled" : "disabled"), ws.name, String(billing.hardCap), String(v)); }} />
              <span className="text-xs">Stop billable AI actions when the allowance runs out, rather than allowing overage</span>
            </label>
            <p className={`text-[11px] mt-2 ${T.faint}`}>Projected AI actions this month: {projectUsage(usage.aiActions).toLocaleString()} against an allowance of {ent.aiActions === Infinity ? "unlimited" : ent.aiActions.toLocaleString()}.</p>
          </div>
        </>)}

        {sec === "Security" && (<>
          <div className={`rounded-2xl p-5 ${T.card}`}>
            <SecTitle>Access</SecTitle>
            <div className="space-y-1.5 text-[11px]">
              {[["Workspace isolation", "Every query is scoped to this workspace and enforced server side."],
                ["Role based access", "Approvals check the signer's role; see the Approval Center policy table."],
                ["Agent permissions", "Each agent's actions are gated by permission, tool, autonomy and the workspace ceiling."],
                ["Credential storage", "Provider keys are encrypted and never returned to the browser in full."],
                ["Audit trail", "Settings, billing and governance changes are all recorded in AI Activity."]].map(([k, v]) => (
                <div key={k} className={`flex items-start gap-2 py-1.5 border-b last:border-0 ${T.border}`}>
                  <CheckCircle2 size={12} className="text-emerald-500 shrink-0 mt-0.5" />
                  <div><div className="font-medium">{k}</div><div className={T.faint}>{v}</div></div>
                </div>
              ))}
            </div>
          </div>
          <div className={`rounded-2xl p-5 ${T.card}`}>
            <SecTitle>Recent settings changes</SecTitle>
            {activity.filter((e) => /setting|autonomy|plan|billing|provider|escalation|cap/i.test(e.action)).slice(0, 8).map((e) => (
              <div key={e.id} className={`flex gap-2 text-[11px] py-1.5 border-b last:border-0 ${T.border}`}>
                <span className={`shrink-0 tabular-nums ${T.faint}`}>{fmtT(new Date(e.at))}</span>
                <span className="font-medium">{e.actor}</span><span className="flex-1">{e.action}{e.before && e.after ? ` · ${e.before} → ${e.after}` : ""}</span>
              </div>
            ))}
            {!activity.some((e) => /setting|autonomy|plan/i.test(e.action)) && <p className={`text-[11px] ${T.faint}`}>No settings changes recorded yet. Change something above and it appears here and in AI Activity.</p>}
          </div>
        </>)}

        {sec === "Danger zone" && (
          <div className={`rounded-2xl p-5 border border-red-200`}>
            <SecTitle>Danger zone</SecTitle>
            <div className="space-y-2">
              {[["Pause all agents", "Every agent stops acting until you reactivate them.", () => flash("Use the workforce page to pause agents in bulk.")],
                ["Cancel subscription", "Access continues until the end of the paid period, then the workspace becomes read only. Data is retained.", () => setSubState("canceled")],
                ["Reset onboarding", "Clears your industry pack and reruns BUZZZ AI setup. Your data is kept.", () => setIndustry(null)]].map(([label, detail, fn]) => (
                <div key={label} className={`flex items-start gap-3 rounded-xl p-3 ${T.softcard}`}>
                  <div className="flex-1"><div className="text-xs font-semibold">{label}</div><div className={`text-[11px] ${T.faint}`}>{detail}</div></div>
                  <button onClick={() => setConfirm({ text: label + "?", detail, yes: label, onYes: fn })} className="h-8 px-3 rounded-xl border border-red-200 text-[11px] font-semibold text-red-500 shrink-0">{label.split(" ")[0]}</button>
                </div>
              ))}
            </div>
          </div>
        )}
      </div>
    </div>
  );
}

export const __VIEWS = {
  admin: AdminView,
  revenue: RevenueView,
  library: AgentLibraryView,
  home: Dashboard, inbox: InboxView, crm: CRMView, agents: AgentsView, approvals: ApprovalsView,
  activity: ActivityView, automations: AutomationsView, campaigns: CampaignsView, calls: CallsView,
  knowledge: KnowledgeView, analytics: AnalyticsView, integrations: IntegrationsView, settings: SettingsView,
  appointments: AppointmentsView, social: SocialView,
};

/* The gate lives in a wrapper so the application's own hooks are never
   skipped: React requires the same hooks on every render, and an early
   return inside the app would break that the moment someone signs in. */
export default function App({ __initialView, __openAI, __session, __staff } = {}) {
  const getInitialSession = () => {
    if (__session !== undefined) return __session;
    if (typeof window !== "undefined" && window.location.search) {
      const params = new URLSearchParams(window.location.search);
      if (params.get("auth") === "success") {
        const token = params.get("token");
        const user = params.get("user") || "User";
        if (token) {
          const payload = {
            demo: false,
            user: { id: `usr_${Date.now()}`, email: user, name: user.includes("@") ? user.split("@")[0] : user, role: "owner", emailVerified: true },
            token,
            workspaces: [{ workspaceId: "ws_default", role: "owner", onboardingComplete: true }],
            next: { screen: "dashboard", workspaceId: "ws_default" },
          };
          try { localStorage.setItem("buzzz_session", JSON.stringify(payload)); } catch (e) {}
          try { sessionStorage.setItem("buzzz_auth_flash", user); } catch (e) {}
          return payload;
        }
      }
    }
    try {
      const raw = localStorage.getItem("buzzz_session");
      if (raw) {
        const parsed = JSON.parse(raw);
        if (parsed && (parsed.user || parsed.demo)) return parsed;
      }
    } catch (e) {}
    return null;
  };

  const initialSession = getInitialSession();
  const [session, setSession] = useState(initialSession);
  const [authChecked, setAuthChecked] = useState(__session !== undefined || !!initialSession);
  const [publicScreen, setPublicScreen] = useState("site");
  /* __staff is a preview and test hook only: it never reads from the network
     and is not reachable from the UI. */
  const [staffSession, setStaffSession] = useState(__staff || null);
  const [route, setRoute] = useState(initialSession ? (initialSession.next || { screen: "dashboard" }) : null);

  useEffect(() => {
    if (__session !== undefined) return;
    let live = true;

    // Clean up OAuth query parameters from URL history if present
    if (typeof window !== "undefined" && window.location.search) {
      const params = new URLSearchParams(window.location.search);
      if (params.get("auth") === "success" || params.get("auth") === "error") {
        window.history.replaceState({}, document.title, window.location.pathname);
      }
    }

    authApi.session().then((r) => {
      if (!live) return;
      if (r.ok && r.data && r.data.user) {
        setSession(r.data);
        setRoute(r.data.next || { screen: "dashboard" });
      }
      setAuthChecked(true);
    });
    return () => { live = false; };
  }, []);

  const signOut = async () => {
    try { localStorage.removeItem("buzzz_session"); } catch (e) {}
    try { await authApi.logOut(); } catch (e) {}
    setSession(null);
    setRoute(null);
    setPublicScreen("site");
    if (typeof window !== "undefined") {
      window.location.href = "/";
    }
  };

  if (!authChecked) return <div className="min-h-screen flex items-center justify-center bg-white text-sm text-zinc-500">Loading…</div>;

  /* Staff are a separate population with their own credentials. A customer
     session can never become a staff session, and signing out of one does not
     touch the other. */
  if (staffSession) {
    return <AdminConsole staff={staffSession.staff}
      onSignOut={() => { setStaffSession(null); setPublicScreen("site"); }} />;
  }
  if (publicScreen === "admin") {
    return <AdminLogin onStaffIn={(data) => setStaffSession(data)} onBack={() => setPublicScreen("site")} />;
  }
  if (!session) {
    if (publicScreen === "site") return <PublicSite onSignUp={() => setPublicScreen("signup")} onLogIn={() => setPublicScreen("login")} onStaff={() => setPublicScreen("admin")} />;
    return <AuthScreen mode={publicScreen} setMode={setPublicScreen} onBack={() => setPublicScreen("site")}
      onAuthed={(data) => { setSession(data); setRoute(data.next || { screen: "dashboard" }); }} />;
  }
  if (route && route.screen === "verify_email") {
    return (
      <div className="min-h-screen flex items-center justify-center bg-white px-6 text-center">
        <div className="max-w-sm">
          <div className="text-lg font-semibold bz-display">Confirm your email</div>
          <p className="text-[13px] text-zinc-600 mt-2">We sent a link to {session.user && session.user.email}. Your workspace opens once it is confirmed.</p>
          <button onClick={signOut} className="mt-5 h-9 px-3 rounded-lg text-[12px] font-semibold border border-zinc-200">Sign out</button>
        </div>
      </div>
    );
  }
  return <AppShell __initialView={__initialView} __openAI={__openAI} route={route} onSignOut={signOut} session={session} />;
}
